# ── Unpacking-target representation ─────────────────────────────────
#
# `ForStmt.target` / `WithItem.target` / `Generator.target` are a comma-joined
# STRING, not an Expr tree, and this is the ONE place that representation is
# written and read. It exists because a for-target can be a dotted attribute
# set (`st.lineno`), a subscript store (`d["k"]`) and a starred name
# (`*rest`) as well as plain names, all in one comma list, and keeping the
# original text is the only spelling that survives all three
# (see Parser._parse_unpack_target).
#
# Two consequences made this its own section rather than a helper at each
# consumer:
#
#   * A 1-TUPLE and a PARENTHESISED SINGLE NAME are DIFFERENT targets and used
#     to be the same string. `for (a,) in b:` unpacks each item; `for (a) in
#     b:` binds the whole item to `a`. The parser emitted `"(a)"` for both,
#     and every consumer read the presence of a comma — so the compiled path
#     and the interpreter both bound the whole item, printing `1` where
#     CPython prints `(1,)`, exit 0, no diagnostic. `_parse_unpack_target`
#     now emits `"(a,)"` for the 1-tuple and keeps `"(a)"` for the
#     parenthesised name, and `for_target_is_tuple` is the only reader of
#     that difference. (CODEGEN_for_loop_target_one_tuple_vs_paren_single_name)
#   * A TRAILING comma used to leave an EMPTY name at every site that split
#     the string independently. `split_top_level_commas` drops empty slots,
#     so a trailing comma is now expressible and no consumer has to know it.
#
# `split_top_level_commas` is deliberately non-recursive and about the TEXT
# only; `for_target_names` is the recursive flattening of one target, and
# `for_target_is_tuple` is the one question about a target's shape that every
# lowering has to ask.


def split_top_level_commas(s: str) -> list[str]:
    """Split `s` on the commas that are not nested inside ([{ }).

    Bracket-aware, because the text it splits appears in two places that both
    nest brackets: a multi-arg bracket ANNOTATION (`UnsafePointer[X,
    Tuple[Int, Int]]` — the element segment has to survive the inner tuple's
    own comma) and an unpacking-target string (`'(a, (b, c))'` — a naive
    `str.split(',')` tore that into `'(a'`, `'(b'`, `'c))'`, fragments that then
    leaked into emitted C declarations verbatim). The depth counter tracks all
    three bracket kinds so the one function serves both.

    The segments are returned VERBATIM (unstripped, empties kept). That is
    deliberate on both sides: an annotation reader wants `[0]` to be the first
    element even when the annotation is malformed and that element is empty,
    and an annotation never carries a trailing comma. A target reader wants
    empties GONE and is asking a different question — how many SLOTS a pattern
    has — so it goes through `target_slots` below rather than reading this
    function's output directly. One splitter, two named readings.
    """
    parts, depth, buf = ([], 0, [])
    for c in s:
        if c in '([{':
            depth += 1
        elif c in ')]}':
            depth = max(0, depth - 1)
        if c == ',' and depth == 0:
            parts.append(''.join(buf))
            buf = []
        else:
            buf.append(c)
    parts.append(''.join(buf))
    return parts


def target_slots(s: str) -> list[str]:
    """The comma-separated SLOTS of an unpacking-target string, stripped, with
    empty slots dropped.

    This is where the trailing comma of a 1-tuple target is paid for once
    instead of at every reader. `'(a,)'` is the spelling `_parse_unpack_target`
    gives `for (a,) in b:` — it has to differ from `'(a)'` somehow, and the
    comma is the only thing Python itself distinguishes them by — so the split
    leaves one empty slot behind, and dropping it here is what lets the
    spelling exist without every consumer having to know about it.

    A real name can never be dropped: `for (a, b)` produces two non-empty
    slots, and a nested `for (a, (b,))` has its inner comma inside brackets, so
    it is not a top-level slot boundary at all.
    """
    return [p.strip() for p in split_top_level_commas(s) if p.strip()]


def _target_group_inner(t: str) -> str | None:
    """The inside of a target's wrapping group — `'(a, b)'` -> `'a, b'`,
    `'[a,]'` -> `'a,'` — or None if `t` is not wrapped in one.

    Both bracket kinds, because a comprehension's list-pattern target
    (`for [off] in ...`) is spelled the same way as its tuple-pattern one and
    is the same question: does this pattern unpack, or bind one name.

    Returns None (rather than the text unchanged) so a caller can tell "not a
    group" from "a group whose inside happens to equal itself", and does NOT
    recurse: only one level of group is peeled here, and
    `for_target_names` is the recursive one.
    """
    if len(t) >= 2:
        if (t[0] == '(' and t[-1] == ')') or (t[0] == '[' and t[-1] == ']'):
            return t[1:-1].strip()
    return None


def for_target_is_tuple(target: object) -> bool:
    """Does this for/with target UNPACK each item, rather than binding the
    whole item to one name?

    True for `for a, b in ...`, `for (a, b) in ...`, the nested
    `for (a, (b, c)) in ...`, and the 1-tuples `for (a,) in ...` / `for a, in
    ...` (spelled `'(a,)'`). False for `for a in ...` and for
    `for (a) in ...` — the parenthesised single NAME, which binds the whole
    item and is exactly what `for (a,) in` must not be confused with.

    Accepts the string form, the bare comma form a comprehension
    `Generator.target` carries (`'a, b'`, no surrounding parens), and the
    Expr forms (`IdentExpr` / nested `TupleExpr` / `ListExpr`) that a
    hand-built AST or a re-parsed expression can present.
    """
    if isinstance(target, str):
        t = target.strip()
        inner = _target_group_inner(t)
        if inner is not None:
            t = inner
        if len(target_slots(t)) > 1:
            return True
        # `'(a,)'` / `'a,'` — one name, but the trailing comma says "this is a
        # 1-tuple", and `target_slots` has just dropped the empty slot that
        # comma left, so it is indistinguishable from `'(a)'` by count. Reading
        # the comma off the text is the whole distinction between the two
        # targets, and it is why the parser has to keep it.
        return t.endswith(',')
    if isinstance(target, (TupleExpr, ListExpr)):
        return True
    if isinstance(target, IdentExpr):
        return False
    # Anything else (an int, None, a node kind this compiler has no
    # unpacking rule for) binds a single value.
    return False


def for_target_single_name(target: object) -> object:
    """The ONE name a non-tuple target binds, with redundant parens peeled;
    `target` itself unchanged when there is nothing to peel.

    `'(a)'` -> `'a'`. This is the third of the three questions about a target,
    and it exists because the first two are not enough: a consumer that has
    already established `not for_target_is_tuple(target)` still has to emit a
    C IDENTIFIER, and for `'(a)'` the target text is not one. Without it every
    lowering would either declare a variable literally named `"(a)"` or keep
    its own paren test — and its own paren test is the bug
    (CODEGEN_for_loop_target_one_tuple_vs_paren_single_name), because
    a paren test cannot see the trailing comma that makes a 1-tuple unpack.

    Returns the input unchanged for a bare name, for a tuple target (the
    caller is wrong to ask), and for anything that is not text."""
    if isinstance(target, str):
        inner = _target_group_inner(target.strip())
        if inner is not None and not for_target_is_tuple(target):
            return inner
    return target


def for_target_names(target: object) -> list[str]:
    """LEAF variable names of a for/with/comprehension target, flattened.

    `'(a, (b, c))'` -> `['a', 'b', 'c']`; `'(a,)'` -> `['a']`; `'a'` -> `['a']`;
    `'(a)'` -> `['a']` (a parenthesised name is still one name). Nested groups
    are flattened because every consumer wants leaves — declared-name sets,
    the interpreter's binder, the codegen's per-slot assignment — while the
    SHAPE (`for_target_is_tuple`) is what tells a consumer whether to unpack
    at all.

    A starred leaf keeps its star (`'*rest'`), because the binding rules for
    it are the consumer's, not this function's; `mojo/middle/boundnames.py`
    is the one that strips it.
    """
    if isinstance(target, str):
        t = target.strip()
        inner = _target_group_inner(t)
        if inner is not None:
            t = inner
        if len(target_slots(t)) > 1 or t.endswith(','):
            names = []
            for part in target_slots(t):
                names.extend(for_target_names(part))
            return names
        if inner is not None:
            # A single name in redundant parens — `'(a)'` binds `a`, and so
            # does a 1-tuple `'(a,)'`; for NAMES they are the same, and only
            # `for_target_is_tuple` can tell the two apart. Returning the
            # stripped text rather than recursing also keeps a SUBSCRIPT
            # target intact: `'d[a, b]'` is one name, and recursing on it
            # would hand the splitter the inside of a bracket that is not a
            # group.
            return [inner] if inner else []
        return [t] if t else []
    if isinstance(target, IdentExpr):
        return [target.name]
    if isinstance(target, (TupleExpr, ListExpr)):
        names = []
        for e in target.elements:
            names.extend(for_target_names(e))
        return names
    name = getattr(target, 'name', None)
    return [name] if isinstance(name, str) and name else []


# ── Lexer ──────────────────────────────────────────────────────────
_KEYWORDS = {'out', 'or', 'mut', 'finally', 'return', 'except', 'raises', 'struct', 'not', 'class', 'True', 'trait', 'assert', 'break', 'from', 'while', 'try', 'and', 'as', 'let', 'in', 'deinit', 'for', 'comptime', 'super', 'var', 'pass', 'ref', 'read', 'else', 'if', 'with', 'elif', 'raise', 'import', 'False', 'continue', 'def', 'is', 'fn', 'global', 'inout', 'borrowed', 'owned', 'enum', 'del', 'nonlocal', 'imm'}

_TOKEN_RE = re.compile(r'(?P<IMAG>(?:\d[\d_]*\.[\d_]*(?:[eE][+-]?\d[\d_]*)?|\.\d[\d_]*(?:[eE][+-]?\d[\d_]*)?|\d[\d_]*(?:[eE][+-]?\d[\d_]*)?)[jJ])|(?P<FLOAT>\d[\d_]*\.[\d_]*(?:[eE][+-]?\d[\d_]*)?|\.\d[\d_]*(?:[eE][+-]?\d[\d_]*)?|\d[\d_]*[eE][+-]?\d[\d_]*)|(?:0x|0X)[0-9a-fA-F][0-9a-fA-F_]*|(?:0o|0O)[0-7][0-7_]*|(?:0b|0B)[01][01_]*|(?P<INT>(?:0|[1-9][0-9_]*))|(?P<AUGASSIGN>\*\*=|//=|<<=|>>=|\+=|\-=|\*=|/=|%=|@=|\&=|\|=|\^=)|(?P<ARROW>->)|(?P<OP>\*\*|//|<<|>>|==|!=|<=|>=|:=|\*|@|/|%|\+|\-|\&|\^|\||<|>|\?|\~)|(?P<ASSIGN>=)|(?P<XFER>\^)|(?P<STRING>[fFrRbBuUtT]{0,2}(?:\"\"\"[\s\S]*?\"\"\"|\'\'\'[\s\S]*?\'\'\'|\"(?:[^\"\\]|\\.)*\"|\'(?:[^\'\\]|\\.)*\')|`[^`]*`)|(?P<DOT>\.)|(?P<COLON>:)|(?P<LPAREN>\()|(?P<RPAREN>\))|(?P<LBRACKET>\[)|(?P<RBRACKET>\])|(?P<LBRACE>\{)|(?P<RBRACE>\})|(?P<COMMA>,)|(?P<SEMICOLON>;)|(?P<NAME>[A-Za-z_][A-Za-z0-9_]*)|(?P<WS>[^\S\n]+)|(?P<UNK>.)')
_INDENT_SIZE    = 4

# ── T-string helpers: handle nested braces/interpolations ────────────────────────
# The regex-based tokenizer can't handle nested t-strings like:
#   t"L1: {t'L2: {t"L3: {val}"}'}"}
# So we replace them with placeholders before tokenization.

def _string_prefix_start(source: str, quote_pos: int) -> int:
    """Scan backward from a quote character to find the start of any
    legitimate 0-2 letter string prefix (f/F/r/R/b/B/u/U/t/T) immediately
    preceding it.

    Returns `quote_pos` itself if there's no such prefix — either because
    there are no prefix-shaped letters right before the quote, or because
    those letters are actually the tail of a longer identifier (e.g. the
    `r` in `self.attr"..."`) rather than a standalone prefix token; that
    distinction is made by checking that the character before the
    letter-run isn't itself alphanumeric/underscore.

    Shared by `_process_nested_tstrings` (which needs to know whether an
    ordinary string has a prefix in order to skip the whole thing as one
    opaque unit) and `py_tokenize`'s `replace_multiline_strings` (which
    needs the same prefix boundary for triple-quoted strings). Extracted
    here instead of duplicated per CLAUDE.md's "consolidate duplicates"
    rule — see PARSE_FAIL_backslash_t_escape_misdetected_as_tstring_prefix.
    """
    # Explicit `==` comparisons, not `c in 'fFrRbBuUtT'`: this codegen's
    # compiled `in`-for-char* path is a documented stub (always returns
    # False), so under self-hosting an `in`-based check here would never
    # advance and every string prefix would go undetected (the exact
    # regression `replace_multiline_strings`'s own prefix scan — the code
    # this helper replaces — was already written to avoid; see its
    # history/comments above its former inline copy of this logic).
    k = quote_pos
    letters = 0
    while letters < 2:
        if k <= 0:
            break
        c = source[k - 1]
        is_pfx = (c == 'f' or c == 'F' or c == 'r' or c == 'R'
                  or c == 'b' or c == 'B' or c == 'u' or c == 'U'
                  or c == 't' or c == 'T')
        if not is_pfx:
            break
        k -= 1
        letters += 1
    if letters == 0:
        return quote_pos
    prev = source[k - 1] if k > 0 else ''
    return k if not (prev.isalnum() or prev == '_') else quote_pos


def _prefix_is_interpolated(prefix: str) -> bool:
    """True when `prefix` -- the letters immediately before a quote -- makes the
    literal it opens an INTERPOLATED one: an f-string or a t-string, whose
    `{...}` replacement fields are CODE rather than text.

    THE one answer, asked from two places that could otherwise disagree:
    `_process_nested_tstrings` (which needs to know whether to use the
    brace-depth-aware closing-quote scan) and `replace_multiline_strings` (which
    needs to know whether a newline inside the literal is content, and whether
    the literal has to be collapsed to a placeholder). The second of those was
    the bug whose symptom was `fire_compiler.py` refusing a PEP 701 f-string
    whose replacement field spans **lines** — `test_formal_libc_symbol.py` was
    the one file in the 2026-10-04 sweep whose refusal read `unterminated string
    literal`, and the fix's record is
    `bugs/FORMAL_sweep_work_map_2026-10-05_b13.md` §5 (fixed 2026-10-05; the
    test is `test_string_literal_lexing.py`'s `LITERALS` block). With no shared
    predicate the scanner asked "is there a line end here?" without ever asking
    "am I inside code?", and CPython's rule for a replacement field is that it
    MAY span lines.

    Explicit `==` comparisons, not `c in 'fFtT'`, for the reason
    `_string_prefix_start` gives in full: this codegen's compiled `in`-for-char*
    path is a documented stub that always returns False, so an `in`-based check
    here would silently disable the branch under self-hosting.
    """
    for c in prefix:
        if c == 'f' or c == 'F' or c == 't' or c == 'T':
            return True
    return False


def _count_line_ends(text: str, unescaped_only: bool) -> int:
    r"""How many LINE ENDS `text` holds — and with `unescaped_only`, how many
    of them no backslash consumed.

    Line ends are `_LINE_ENDS`, which is the module's one definition of the
    question and includes a lone `\r`; `str.count('\n')` is not it, and two
    places in `replace_multiline_strings` used it. That is why the shape
    `f"a {q\r  } b"` — a replacement field crossing a bare CR — produced NO
    STRING token at all on the first version of this: the literal was not
    collapsed, so the `\r` reached `_source_lines`, which splits on it, and the
    half-literal became ordinary code.

    The two answers are different questions and both are needed. `unescaped_only`
    is the COLLAPSE decision: a backslash-continued literal must stay text on
    its physical line, because the pass that decides whether the pair is deleted
    or kept (`_unterminated_quote_pos` / `_is_raw_literal_at`) runs after this
    one and reads the line there. And the plain count is the PAD: every line end
    occupied a physical line, escaped or not, so both have to be paid back to keep
    every later line number where the source wrote it.

    Collapsing on the wrong one of those is what regressed
    `test_string_literal_lexing.py`'s eight continuation rows the first time this
    was written, and the symptom was the value keeping the pair on every
    architecture.
    """
    n = 0
    for m in _LINE_TERMINATORS.finditer(text):
        if unescaped_only:
            k = m.start()
            if k == 0:
                return 1
            if text[k - 1] != '\\':
                n += 1
        else:
            n += 1
    return n


def _flush_line_pad(out: list, seg: str, pending: int) -> int:
    """Append `seg` to `out`, inserting the `pending` owed newlines after `seg`'s
    FIRST line break; return what is still owed.

    The owed newlines stand in for lines a collapsed literal used to occupy, so
    that every physical line number after one is still the number the source
    wrote. They go after the first REAL newline rather than being emitted right
    after the placeholder, because emitting them there pushed any postfix or
    binary continuation on the literal's own closing line (a `.strip()` or a `%`
    written straight after the closing quote) onto an artificial blank line of
    its own, which made the line-based tokenizer end the statement early and
    left the `.`/`%` to start a new, primary-less statement
    (`Unexpected DOT('.')`/`Unexpected OP('%')`, found via real stdlib code like
    a triple-quoted literal followed straight by `.strip()`).

    Module-level rather than a nested closure over `out`/`pending` ON PURPOSE:
    a closure-based version of this was behaviourally identical and broke
    `make check-selfhost`, with `gimple_codegen.py` miscompiling unrelated code
    elsewhere once `replace_multiline_strings` gained a nested closure with
    mutated captured state at that scope depth. It is also the reason the flush
    used to be spelled out at each of its two call sites; there is one copy now.

    With nothing owed, or with nothing owed and no line break to anchor them to,
    this is an append and nothing else -- which is what every single-line
    literal in every file on this tree takes.
    """
    if pending == 0 or '\n' not in seg:
        out.append(seg)
        return pending
    nl_idx = seg.index('\n')
    out.append(seg[:nl_idx + 1])
    out.append('\n' * pending)
    out.append(seg[nl_idx + 1:])
    return 0


def _find_tstring_closing_quote(source: str, quote_pos: int, quote_ch: str) -> int:
    """Find closing quote of a t-string, handling nested braces with interpolations.

    Args:
        source: Full source string
        quote_pos: Position of opening quote
        quote_ch: Quote character (' or ")

    Returns:
        Index of closing quote, or -1 if not found.
    """
    i = quote_pos + 1
    while i < len(source):
        ch = source[i]
        if ch == '\\' and i + 1 < len(source):
            i += 2
            continue
        if ch == quote_ch:
            return i
        if ch == '{':
            i += 1
            depth = 1
            while i < len(source) and depth > 0:
                ch = source[i]
                if ch == '\\' and i + 1 < len(source):
                    i += 2
                    continue
                if ch == '{':
                    depth += 1
                elif ch == '}':
                    depth -= 1
                i += 1
            continue
        i += 1
    return -1


def _process_nested_tstrings(stmt: str, cache: dict, idx_list: list) -> str:
    """Replace t-strings with nested braces with __MOJO_STR_N__ placeholders.

    Args:
        stmt: Statement to process
        cache: String cache dict (modified in-place)
        idx_list: Single-element list [counter] (modified in-place)

    Returns:
        Statement with t-strings replaced.
    """
    result = []
    i = 0
    while i < len(stmt):
        # Any quoted string — with or without a prefix (`r"..."`, `f"..."`,
        # `rb"..."`, a bare `"..."`, etc.) — must be recognized and consumed
        # as ONE unit right when its opening quote is reached. Any prefix
        # letters immediately before the quote were already appended to
        # `result` one character at a time by the plain fallback below (they
        # aren't distinguishable from ordinary code until we reach the quote
        # that follows them), so they're removed from `result` here and
        # folded back into whichever unit — ordinary string or t/f-string —
        # this turns out to be.
        #
        # This dispatch is deliberately keyed off the QUOTE character (using
        # a backward scan for any prefix, via `_string_prefix_start`) rather
        # than off the prefix letter scanning forward for a quote: the
        # latter (the previous implementation) had no notion of "already
        # inside a string", so it could misfire on a `t`/`T` letter that was
        # actually part of another string's own escape sequence (e.g. the
        # `t` in `r"\t"`'s `\t`), treating the *original* string's own
        # closing quote as the *opening* quote of a brand-new bogus t-string
        # and scanning for the next unrelated quote later in the statement.
        # See PARSE_FAIL_backslash_t_escape_misdetected_as_tstring_prefix.
        if stmt[i] in ('"', "'"):
            qch = stmt[i]
            pstart = _string_prefix_start(stmt, i)
            prefix = stmt[pstart:i]
            # Both t-strings (t"...") and f-strings (f"...") use the same
            # `{expr}` interpolation syntax, so both need the brace-depth-
            # aware, quote-reuse-safe closing-quote scan below — an
            # f-string whose nested `{...}` expression contains a string
            # literal reusing the SAME quote character as the f-string's
            # own delimiter (legal since PEP 701 / Python 3.12, e.g.
            # `f'result: {g('a', 'b')}'`) would otherwise be truncated at
            # the first reused quote by the plain simple-scan branch below.
            # See PARSE_FAIL_fstring_same_quote_reuse. Whether a prefix makes
            # a literal interpolated is `_prefix_is_interpolated`'s one answer,
            # the same one `replace_multiline_strings` asks.
            if _prefix_is_interpolated(prefix):
                # A real t/f-string prefix: use the brace-depth-aware scan
                # so nested `{}` interpolations are handled correctly.
                close = _find_tstring_closing_quote(stmt, i, qch)
                if close != -1:
                    if prefix:
                        del result[-len(prefix):]
                    ts = stmt[pstart:close + 1]
                    ph = f"__MOJO_STR_{idx_list[0]}__"
                    cache[ph] = ts
                    idx_list[0] += 1
                    result.append(ph)
                    i = close + 1
                    continue
                # No closing quote found for this "t-string" reading — fall
                # through to the plain single-char fallback below, exactly
                # as before.
            else:
                # An ordinary (non-t/f) string literal, e.g. `'t"'` or
                # `r"\t"`: skip it as one whole unit so its contents (which
                # may coincidentally look like a t-string prefix, e.g. a
                # literal `t"` inside, or an escape like `\t` right before
                # the closing quote) are never re-scanned char-by-char.
                #
                # Deliberately NOT _find_tstring_closing_quote here: its
                # brace-depth tracking exists for real t-string
                # interpolation, where `{`/`}` are guaranteed balanced —
                # applying that same assumption to an ordinary string's
                # literal content (e.g. fire.py's own C-code-snippet string
                # literals, full of unbalanced `{`/`}` as plain text) scans
                # past the real closing quote entirely, misreading unrelated
                # later source as part of this "string". A plain string
                # only ever ends at its own closing quote, so a simple
                # backslash-escape-aware scan is correct and sufficient.
                j = i + 1
                while j < len(stmt):
                    if stmt[j] == '\\' and j + 1 < len(stmt):
                        j += 2
                        continue
                    if stmt[j] == qch:
                        break
                    j += 1
                if j < len(stmt):
                    if prefix:
                        del result[-len(prefix):]
                    result.append(stmt[pstart:j + 1])
                    i = j + 1
                    continue
        result.append(stmt[i])
        i += 1
    return ''.join(result)
_SEP_CHAR       = ';'
_CMT_CHAR       = '#'
_HAS_INDENT     = True

@dataclass
class Token:
    kind: str
    value: str
    line: int = 0
    col: int = 0

# ── Layout helpers ──────────────────────────────────────────────────
def _strip_inline_comment(s: str) -> str:
    """Remove trailing # comment, respecting quoted strings (including backtick strings and f/r/b prefixes)."""
    in_str = None
    i = 0
    while i < len(s):
        c = s[i]
        if in_str:
            if c == "\\" and in_str != '`': i += 2; continue
            if c == in_str: in_str = None
        elif c in ('"', "'", '`'):
            in_str = c
        elif i > 0 and c in ('"', "'") and s[i-1] in 'fFrRbBuUtT':
            # f"..." prefix: already entered via the quote char above
            in_str = c
        elif c == _CMT_CHAR:
            return s[:i]
        i += 1
    return s

def _split_on_separators(s: str) -> list[str]:
    """Split on ';' statement separator, respecting quoted strings (including
    backtick strings) AND bracket/paren/brace nesting — a ';' inside an
    unmatched `[`/`(`/`{` is never a real statement separator (real Python
    has no such thing as a semicolon inside an expression at all), so it's
    left in place for the surrounding bracketed text to consume whole. This
    matters for a fixed-size-array type-annotation position, `var x:
    [ElemType; N]` (see fire_compiler.py's `_parse_type_ann_inner` LBRACKET
    branch / `_capture_bracketed_text`, and gimple_codegen.py's
    `_FIXED_ARRAY_ANN_RE`) — without bracket-depth tracking here, the ';'
    was treated as an ordinary statement separator and silently DROPPED
    (never even reaching the token stream, unlike a real SEMICOLON token —
    see py_tokenize's `kind in ("WS", "UNK", "XFER"): continue`), losing the
    array's size entirely with no way to recover it downstream. See
    BUG-2026-008 (box.3d/game) for the real-world motivating case."""
    parts, buf, in_str, depth = [], [], None, 0
    i = 0
    while i < len(s):
        c = s[i]
        if in_str:
            buf.append(c)
            if c == "\\" and in_str != '`' and i + 1 < len(s):
                i += 1; buf.append(s[i])
            elif c == in_str:
                in_str = None
        elif c in ('"', "'", '`'):
            in_str = c; buf.append(c)
        elif c in ('[', '(', '{'):
            depth += 1; buf.append(c)
        elif c in (']', ')', '}'):
            depth = max(0, depth - 1); buf.append(c)
        elif c == _SEP_CHAR and depth == 0:
            parts.append("".join(buf)); buf = []
        else:
            buf.append(c)
        i += 1
    parts.append("".join(buf))
    return parts

# ── what a line break is ────────────────────────────────────────────────────
#
# The line terminators the LANGUAGE has, and `str.splitlines()` is not it: that
# also breaks on vertical tab, form feed, the four C1 information separators,
# NEL, LINE SEPARATOR and PARAGRAPH SEPARATOR, and CPython's tokenizer breaks on
# none of them. So `s.splitlines()` invented a line break inside any string
# literal containing one of those, which destroyed the literal — `x = "a\x0bb"`
# tokenized to NO STRING token at all, and the diagnostic then named a line with
# no problem on it — and inside a COMMENT, where the second half became a bare
# NAME statement the source never contained. Eight characters, every one of
# which CPython accepts inside a string, and not one of which occurs in any of
# the 617 `.mojo`/`.py` files reachable from this worktree (counted, not
# assumed).
#
# `\r` IS a line terminator, and CPython's tokenizer agrees: `compile` of
# `s = "a\rb"` is a SyntaxError. The value CPython gives a `\r` that lands inside
# a TRIPLE-quoted literal is normalized to `\n`, and this path normalizes nothing
# — that half is the documented byte-exact divergence. The SPLIT is the part that
# has to agree, and for a single-quoted literal agreeing means refusing.
#
# Both users are here so there is one answer to "where does a line end":
# `_scan_string_end` (which must refuse to let a literal cross one) and
# `_source_lines` (which must split on one and only on one).
_LINE_ENDS = '\r\n'
_LINE_TERMINATORS = re.compile(r'\r\n|\r|\n')


def _source_lines(src: str) -> list:
    """`src`'s physical lines, split the way the language splits them.

    Same shape as `str.splitlines()` for every input built from `\n`, `\r\n` and
    `\r` alone — including the trailing-empty-line convention, so this is a
    drop-in for every file on this tree.
    """
    lines = _LINE_TERMINATORS.split(src)
    if lines and lines[-1] == '':
        lines.pop()
    return lines


def _indent_expanded(line: str) -> str:
    r"""`line` with tabs expanded in its LEADING whitespace only.

    The tab expansion exists for the INDENT, and `indent` below is computed from
    the leading run and nothing else — so expanding the body of the line was
    pure loss. In code a tab is whitespace (`_TOKEN_RE`'s WS arm is `[^\S\n]+`,
    which a tab matches) and expanding it changed no token. Inside a string
    literal a tab is CONTENT, and expanding it rewrote the value in a program
    that built, ran and printed the wrong string:

        print("x<TAB>y")     CPython: x<TAB>y, len 3      here, before: x y, len 4

    The leading run is the only part that matters and a tab at the start of a
    line always lands on a column boundary, so expanding that run alone gives
    the same `indent` — and `lstrip` splits at the same place either way, since
    `expandtabs` turns a tab into spaces and both are whitespace to it.

    This is the third pass in this function to need to know where the literals
    are, after the backslash join and the line split; the other two are
    `_unterminated_quote_pos` and `_strip_inline_comment`, and this one is the
    only one that still had to be taught.
    """
    cut = len(line) - len(line.lstrip())
    return line[:cut].expandtabs(_INDENT_SIZE) + line[cut:]


def _scan_string_end(src: str, i: int, quote: str, triple: bool,
                     interpolated: bool = False) -> int:
    r"""Index just PAST the closing delimiter of the string literal that OPENS at
    `i`, or -1 when that literal is unterminated.

    `interpolated` says whether the literal opened at `i` is an f-string or a
    t-string, which is a question about CODE inside a string and not about the
    string; `_prefix_is_interpolated` is its one answer. It defaults to False so
    that a caller with no prefix in hand gets this function's ordinary-literal
    rule, which is the safe direction: the wrong answer is a refusal, never a
    different literal boundary.

    This is the one place in the front end that answers "where does this string
    literal end", shared by `py_tokenize`'s triple-quote collapse and its
    ordinary-quote skip (CLAUDE.md: consolidate duplicates — the two used to be
    separate inline loops that could disagree, and the disagreement is silent).

    The rule is CPython's, and it is worth stating exactly because getting it
    wrong is the bug this function exists to make impossible
    (CODEGEN_triple_quoted_literal_ending_in_a_backslash_swallows_the_rest_of_the_file).
    (That doc's examples spell quote runs out longhand from here on: a literal
    triple quote inside this docstring would close it.)

        A backslash consumes the NEXT CHARACTER, whatever it is.

    That is what makes a backslash-quote not close a non-raw literal, in a
    triple-quoted one as much as in a single-quoted one. Written with D for a
    double quote, the source `DDDa\DD"bDDD` is a triple-quoted literal whose
    content is `a\"bDD` — emphatically NOT "a literal that ends one quote
    early". It is also what makes a backslash immediately before the closing run
    UNTERMINATED rather than closed. CPython says so too — "unterminated
    triple-quoted string literal" for `DDD\DDD`, "unterminated string literal"
    for `"abc\"` — and refusing is what this path does now.

    The alternative rule proposed in that bug's original report — "an escape
    consumes the next byte only when it is a backslash or the quote character" —
    is the same rule for every input that can END a literal, because only a
    backslash or a quote can be both "the byte after a backslash" and "a
    delimiter". It therefore changes nothing about where literals end, and it
    cannot make the reported case parse, because CPython does not parse it
    either. (What it does change is the VALUE, and this path's value is already
    byte-exact: no escape is processed at all, which is a separate, documented
    divergence from CPython and not this function's business.)

    A single-quoted literal may not cross a bare newline (CPython: "EOL while
    scanning string literal"); a backslash-continued one may, and a
    triple-quoted one obviously may. Unterminated is returned as -1, never as
    "the rest of the file": a literal that ran off the end used to swallow
    every remaining line into its own value, which is a silent miscompile, and
    the alternative — pretending the delimiters were not there — is worse
    still, because it turns the literal's text into ordinary code
    (`x = "abc` used to parse as `x = abc`, and `x = it's` as `x = it`
    followed by a bare `s`).

    ONE rule above is CPython's for an ordinary literal and NOT its rule for an
    interpolated one, which is why `interpolated` is a parameter and not a
    detail of the caller: in `f"..."` a `{` opens a REPLACEMENT FIELD, and the
    field is code, and code may span lines. CPython 3.12+ accepts

        f"got {[q(n)
                for n in ys]}"

    and reports "unterminated string literal" for `f"a{b`. So for an
    interpolated single-quoted literal this tracks field depth and does not end
    the literal at a line break inside one. Depth 0 is unchanged, which is the
    property that keeps every genuinely unterminated literal a refusal. `{{` and
    `}}` are ESCAPED braces -- `f"a{{b"` is the three characters `a{b` and opens
    no field -- and a line break after one is still the end of the literal,
    exactly as CPython has it.

    A `#` inside a field needs NO arm here, and that is worth saying because the
    obvious arm is wrong. This function answers where a literal ENDS, and to
    that question every character inside a field is equally content: the
    reported shape `f"{a # note<nl>}"` is scanned correctly by the depth rule
    alone, the `#` being just a character between `{` and the line break. What
    an arm for it would actually have to decide is when a `#` starts a COMMENT
    rather than being a character, and CPython's answer is a property of the
    expression -- `:#x` is a format spec, `'a#b'` is inside a nested literal,
    `#b` with no space before it is neither -- so an arm would have to parse the
    field to get it right, and a plausible-looking one silently breaks a format
    spec. Written once, measured three ways: it broke `{x:#x}` and
    `{d['a#b']}` across 10 files on this tree before it was removed, and the
    comment case passes without it.

    THE DELIMITER INSIDE A FIELD IS A NESTED LITERAL, not the end of this one.
    Since PEP 701 (3.12) `f"{d["k"]}"` is valid, so the closing quote of a
    nested literal that reuses the enclosing delimiter must be stepped over
    rather than read as this literal's own — `PARSE_FAIL_fstring_same_quote_reuse`
    is the doc for that shape and it worked before this change, so a brace
    counter that does not understand quoting would have broken it. Which is why
    the delimiter arm below asks this same function rather than deciding: a
    nested literal that closes is skipped, and one that does not close means the
    quote was this literal's own after all — at which point an unclosed field is
    a refusal (CPython: "'{' was never closed") and depth 0 is the ordinary end.
    A nested literal of the OTHER quote character needs no arm at all, because
    it cannot close this one.

    Not done here, and deliberately: nothing about a nested literal this scan
    cannot finish. A field whose nested literal is itself unterminated is
    refused rather than guessed at, which is the safe direction and the same one
    this function has taken since it was written.
    """
    n = len(src)
    delim = quote * 3 if triple else quote
    dlen = len(delim)
    j = i + dlen
    # Replacement-field depth. Non-zero is only reachable for an interpolated
    # single-quoted literal, which is the only shape where a line break can be
    # content; a triple-quoted one crosses lines whatever the depth is, and an
    # ordinary one's braces are text.
    fields = interpolated and not triple
    depth = 0
    while j < n:
        c = src[j]
        if c == '\\' and j + 1 < n:
            if fields:
                # A backslash before a BRACE does not consume it, and this is
                # the raw-string half of the rule the docstring's "Not in scope"
                # paragraph is about. `rf'...\{{'` is what this codegen's own
                # `test_gimple_runner.py` writes: a raw f-string whose field is
                # an escaped brace pair. In a raw literal the backslash is
                # content and the pair is what escapes, so consuming the brace
                # here opened a field that never closed and REFUSED the file.
                # Letting the brace through gives CPython's reading, and for a
                # COOKED f-string `\{` is a syntax error either way, so the
                # boundary is still right in the only case that reaches it.
                if src[j + 1] == '{' or src[j + 1] == '}':
                    j += 1
                    continue
            j += 2
            continue
        if fields:
            if c == '{':
                if j + 1 < n:
                    if src[j + 1] == '{':
                        j += 2
                        continue
                depth += 1
                j += 1
                continue
            if c == '}':
                if j + 1 < n:
                    if src[j + 1] == '}':
                        j += 2
                        continue
                if depth > 0:
                    depth -= 1
                j += 1
                continue
        if src.startswith(delim, j):
            if depth > 0:
                # A triple run at the nested position opens a triple-quoted
                # literal, and this literal is single-quoted (that is what
                # `fields` means), so the run can only belong to the nested one.
                # Spelled as two comparisons rather than a slice compare for
                # the reason the opener test in `replace_multiline_strings`
                # gives in full: this codegen's `and` evaluates both operands.
                nested_triple = False
                if j + 2 < n:
                    if src[j + 1] == quote:
                        if src[j + 2] == quote:
                            nested_triple = True
                nested = _scan_string_end(src, j, quote, nested_triple,
                                          _prefix_is_interpolated(
                                              src[_string_prefix_start(src, j):j]))
                if nested < 0:
                    return -1
                j = nested
                continue
            return j + dlen
        if c in _LINE_ENDS and not triple:
            # A raw line break closes nothing in a single-quoted literal, and
            # that includes `\r`: CPython's tokenizer treats a lone CR as a line
            # end (its own value for a CR inside a triple-quoted literal is
            # normalized to `\n`, which is the byte-exact divergence, not this)
            # and refuses `compile('s = "a\rb"')` as an unterminated literal.
            # Without this arm the CR stayed invisible here and the front end
            # refused to refuse — see `_source_lines`, which splits on the same
            # two characters. Inside a replacement field it is content instead.
            if depth > 0:
                j += 1
                continue
            return -1
        j += 1
    return -1

def decode_c_escapes(s: str) -> str:
    r"""Decode C-style backslash escapes in a string literal's BODY.

    THE single decoder for this tree, and every engine calls it (CLAUDE.md:
    consolidate duplicates rather than maintaining parallel implementations — the
    interpreter and the compiled path each carried their own copy and the formal
    backends had none, which is
    FORMAL_string_literal_escape_is_not_decoded).

    Why a consumer has to call it at all: the parser strips a string literal's
    outer quotes and hands the body on as RAW SOURCE TEXT, because the compiled
    path passes that text to a C compiler, which decodes the escapes itself.
    A consumer that does not hand the text to a C compiler has to do it here.

        The set: the C simple escapes, plus \xHH.

    \n \t \r \\ \" \' \0 \a \b \f \v, then \x followed by two hex digits. An
    UNKNOWN escape keeps its backslash (`"\d"` is a backslash and a d, which is
    CPython's own behaviour and what `gimple_codegen._c_escape` passes through),
    and a trailing lone backslash is kept verbatim. That is deliberately
    permissive: a recognised escape it gets WRONG is a wrong answer, while an
    unrecognised one it leaves alone is what the source most likely meant.

    Not in scope, and worth saying so: RAW strings. `_scan_string_end` records
    that no engine here preserves `r"..."`, so a literal's body arriving here has
    already lost the distinction and decoding will not make it worse. Deciding
    what a raw string should do is a question about the tokenizer, not this
    function.
    """
    if '\\' not in s:
        return s
    simple = {'n': '\n', 't': '\t', 'r': '\r', '\\': '\\', '"': '"',
              "'": "'", '0': '\0', 'a': '\a', 'b': '\b', 'f': '\f', 'v': '\v'}
    out = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c == '\\' and i + 1 < n:
            nxt = s[i + 1]
            if nxt in simple:
                out.append(simple[nxt]); i += 2; continue
            if nxt == 'x' and i + 3 < n and s[i + 2] in '0123456789abcdefABCDEF' \
                    and s[i + 3] in '0123456789abcdefABCDEF':
                out.append(chr(int(s[i + 2:i + 4], 16))); i += 4; continue
            # Unknown escape — leave the backslash as-is (CPython's own
            # behaviour for e.g. "\d"), matching gimple_codegen._c_escape's
            # `\\` passthrough.
            out.append(c); i += 1; continue
        out.append(c); i += 1
    return ''.join(out)

def decoded_literal(lit) -> str:
    """`lit`'s body with its escapes decoded — or NOT, for a raw literal.

    THE reader every engine uses instead of calling `decode_c_escapes` on a
    `StringLiteral.value` directly, and the distinction is the whole of it: the
    `r` prefix is stripped by `_strip_string_prefix_and_quotes` and is
    otherwise unrecoverable from the body, so `r"a\\nb"` and `"a\\nb"` are the
    same four characters by the time a consumer sees them. CPython keeps the
    first at four and makes the second three.

    Consolidating the decoder into one function would otherwise have introduced
    that divergence in all three engines at once — the formal backends were the
    only ones decoding, and they decoded raw literals wrongly; making the
    interpreter and the compiled path join them by way of a shared table is
    only an improvement if the table is asked about the PREFIX as well as the
    escapes. `StringLiteral.is_raw` carries the answer from the parser, which
    is the only place it still exists.

    A plain STRING is returned unchanged rather than decoded. That is the other
    half of the same rule: a fold, a manifest value, a synthesized format
    string and `print_format`'s default `sep`/`end` are all already-decoded
    text, and a synthesized `StringLiteral` carries `is_raw=False` for the same
    reason — there was no source prefix for it to record. Decoding either would
    be decoding something twice, which is how `"a\\\\nb"` becomes a newline when
    the source wrote a backslash."""
    if isinstance(lit, str):
        return lit
    if getattr(lit, "is_raw", False):
        return lit.value
    return decode_c_escapes(lit.value)

def _unterminated_quote_pos(line: str) -> int:
    r"""Index of the opening quote of the string literal `line` ends inside, or
    -1 when it ends outside one.

    The companion question to `_scan_string_end` ("where does the literal that
    OPENS at `i` end") — this one asks "which literal is the line's last
    character inside", which is what the backslash-continuation join in
    `py_tokenize` needs to know. Same escape rule, so the two cannot disagree: a
    backslash consumes the NEXT character, and a backslash at the very end of
    the line therefore consumes the line break that follows it, leaving the
    line still inside its string.

    The answer is a position rather than a bool because the join has a second
    question to ask about that literal — is it RAW? — and that needs the quote,
    not a yes/no. Both are answered from this one scanner so they cannot
    disagree; see `_is_raw_literal_at`.

    A backtick string is skipped as an opaque unit and is NOT reported as being
    inside: it has no backslash escape, so a trailing backslash in one is not a
    continuation and the join must keep treating it as one (the pre-existing
    behaviour for that spelling, unchanged).

    Only single-quoted literals can reach a position. `py_tokenize` replaces
    triple-quoted spans with placeholder names before this is consulted, and a
    single-quoted literal cannot hold a raw newline, so a line can only end
    inside one by way of the backslash-newline pair this function exists for.

    `_unterminated_string_at` is the scan; this is its boolean, kept because
    `test_string_literal_lexing.py` and the join's own truthiness check read it
    as one.
    """
    i = 0
    n = len(line)
    delim = None
    open_at = -1
    while i < n:
        c = line[i]
        if delim is None:
            if c == '`':
                j = line.find('`', i + 1)
                if j < 0:
                    return -1
                i = j + 1
                continue
            if c in ('"', "'"):
                delim = c * 3 if line.startswith(c * 3, i) else c
                open_at = i
                i += len(delim)
                continue
            i += 1
            continue
        if c == '\\':
            i += 2
            continue
        if line.startswith(delim, i):
            i += len(delim)
            delim = None
            open_at = -1
            continue
        i += 1
    return open_at if delim is not None else -1


def _is_raw_literal_at(line: str, quote_pos: int) -> bool:
    r"""True when the literal whose opening quote is at `quote_pos` in `line` is
    raw — i.e. its prefix carries `r`/`R`, so nothing in it is an escape.

    What a backslash-newline pair is worth inside a literal is CPython's rule,
    measured rather than inferred (see the `CONTINUATIONS` table in
    test_string_literal_lexing.py): DELETED unless the literal is raw, where the
    pair is content. So this is the one question that decides whether the join
    may delete the pair, and the prefix is read with `_string_prefix_start` —
    the same helper `replace_multiline_strings` and `_process_nested_tstrings`
    use, which already knows that a prefix letter must not be the tail of a
    longer identifier (`self.r` before `.format("...")` is not a raw prefix).
    """
    if quote_pos < 0:
        return False
    prefix = line[_string_prefix_start(line, quote_pos):quote_pos]
    return 'r' in prefix or 'R' in prefix

# The marker a placeholder carries when it stands for a backslash-newline pair
# this join KEPT inside a raw literal, as opposed to a triple-quoted span
# `replace_multiline_strings` collapsed. Deliberately a namespace of its own:
# these two are substituted from two different caches into two different token
# shapes, and sharing a marker would make every docstring that NAMES the scheme
# (`__MOJO_STR_<n>__`, spelled in prose throughout this file) a live collision —
# measured, not theoretical: with one shared marker, this file's own module
# docstring was substituted into the middle of another docstring that mentioned
# the placeholder name, because the two happened to share an index.
_CONT_PLACEHOLDER = "__MOJO_CONT_"


def _substitute_str_placeholders(value: str, cache: dict) -> str:
    r"""Put back every continuation placeholder that landed INSIDE a STRING
    token's value, from `cache`.

    The other arm of this — `if kind == "NAME" and val in string_cache` — can
    only fire for a placeholder that occupies a token by itself, which is all a
    triple-quoted span ever produced. A raw literal's kept line continuation is
    the first shape where a placeholder lands in the middle of another token:
    `r"a\<nl>b"` joins to `r"a__MOJO_CONT_0__b"`, one STRING token, and what
    stands in for the pair is the line break alone. So the value that reaches
    the parser is this path's byte-exact content either way, with the pair kept
    because the literal is raw — which is CPython's answer, and the reason the
    join cannot simply delete the pair.

    A continuation placeholder is always inside the literal it belongs to (the
    join writes it where the backslash was, and `_unterminated_quote_pos` has
    already established that the backslash is inside one), so it can only ever
    appear inside a STRING token and needs no arm of its own above.

    A name under the marker that is not in `cache` is left exactly as written,
    so source that spells one in a string keeps that text.
    """
    if _CONT_PLACEHOLDER not in value:
        return value
    out = []
    i = 0
    n = len(value)
    while i < n:
        j = value.find(_CONT_PLACEHOLDER, i)
        if j < 0:
            out.append(value[i:])
            break
        name_end = value.find('__', j + len(_CONT_PLACEHOLDER))
        if name_end < 0:
            out.append(value[i:])
            break
        name = value[j:name_end + 2]
        if name in cache:
            out.append(value[i:j])
            out.append(cache[name])
            i = name_end + 2
        else:
            out.append(value[i:j + len(_CONT_PLACEHOLDER)])
            i = j + len(_CONT_PLACEHOLDER)
    return ''.join(out)

def _src_loc(src: str, pos: int, filename: str = "") -> str:
    """gcc-style `file:line:col: ` prefix for a diagnostic about `src[pos]`.

    Same shape as `Parser._loc` (which can only name a token, and the string
    scan runs before any token exists), so a lexer refusal reads exactly like
    the parser's own. `filename` is empty when the caller has none.
    """
    line = src.count('\n', 0, pos) + 1
    nl = src.rfind('\n', 0, pos)
    col = pos - nl
    if filename:
        return f"{filename}:{line}:{col}: "
    return f"{line}:{col}: "


def py_tokenize(src: str) -> list[Token]:
    """Tokenize with layout rules derived from the .md spec:
        - Indentation (4 spaces) → INDENT/DEDENT
        - ';' → statement separator
        - '#' → end-of-line comment
        - Multi-line statements use indentation (no backslash continuation)

    The one-argument entry point, and the one every caller but two uses. It
    is a FIXED C ABI symbol: `py_tokenize` is in
    `GimpleGen._NO_OVERLOAD_MANGLE`, is declared in `runtime/fire_runtime.h`
    as `MojoList *py_tokenize(char *source)`, and is in
    `GimpleGen._KNOWN_SIGS` with that one parameter. A DEFAULTED second
    parameter therefore silently changed that pinned ABI from one argument to
    two: the self-host materializes the default at every call site (so it
    emits `py_tokenize (src, 0)`), while the header's declaration — which is
    what gcc sees first, and therefore what every call is checked against —
    still said one. That is 25 "too many arguments to function 'py_tokenize';
    expected 1, have 2" plus a "conflicting types" at the definition, and it
    takes the whole self-host build down.

    So the filename-carrying variant is `py_tokenize_named`, an ordinary
    function whose arity the codegen derives from its definition like any
    other. Nothing is lost: the two callers that know a filename still get
    the `file:line:col:` prefix on the refusal."""
    return py_tokenize_named(src, "")


def py_tokenize_named(src: str, filename: str) -> list[Token]:
    """`py_tokenize(src)`, with `filename` used only to prefix an
    "unterminated string literal" diagnostic; pass `""` and the message
    carries `line:col:` alone. Same shape as `Parser._loc`, so a lexer
    refusal reads exactly like the parser's own."""
    import re
    string_cache = {}
    # Kept pairs from the backslash join below, restored into the STRING token
    # that contains them — a cache of its own, for the reason spelled out at
    # `_CONT_PLACEHOLDER`.
    continuation_cache = {}
    string_idx = [0]
    def replace_multiline_strings(src):
        # A single-pass, quote-nesting-aware scan — NOT a blind regex search
        # for the next `"""`/`'''` triple. A naive `re.sub` (the previous
        # approach here) matches the *literal 3-char run* anywhere in the
        # source, including inside an ordinary '...'/"..." string whose
        # *contents* happen to spell out three quote characters, e.g.
        # `_MULTI_QUOTES = ('"""', "'''")` (real CPython stdlib code,
        # _ast_unparse.py). That single-quoted string's embedded `"""` was
        # matched as a triple-quote *opener*, and the regex's non-greedy
        # `[\s\S]*?` then swallowed everything up to the *next* literal
        # `"""` it could find — which was the unrelated docstring of the
        # very next class — corrupting both. Scanning char-by-char and
        # skipping ordinary quoted strings as opaque units (matching their
        # own close quote, honoring backslash escapes) avoids ever treating
        # a quote character *inside* another string as a triple-quote
        # delimiter.
        out = []
        n = len(src)
        i = 0
        last = 0
        # Newlines "owed" to keep later physical-line numbers in sync after
        # collapsing a multi-line literal to one placeholder token. Flushed
        # at the next REAL newline actually appended to `out`, not
        # immediately after the placeholder — emitting them right away
        # pushed any postfix/binary continuation on the literal's own
        # closing line (e.g. `.strip()` or `%` right after the closing
        # `"""`) onto an artificial blank line of its own, which made the
        # line-based tokenizer end the statement early and left the `.`/`%`
        # to start a new, primary-less statement (`Unexpected DOT('.')`/
        # `Unexpected OP('%')` — found via real stdlib code like
        # `"""...""".strip()` and `"""...""" % (args)`). Deliberately
        # inlined at both flush points below rather than factored into a
        # nested closure: a closure-based version was behaviorally
        # identical but broke `make check-selfhost` (gimple_codegen.py
        # miscompiling unrelated code elsewhere once this file gained a
        # nested closure with mutated captured state at this scope depth).
        pending_pad = 0
        while i < n:
            c = src[i]
            if c == _CMT_CHAR:
                # A '#' can't start a comment while inside a string — and
                # strings are always skipped as whole units below — so
                # reaching here means we're in plain code. Comments can
                # contain stray quote characters (e.g. `# say "hi"`) that
                # must not be mistaken for string delimiters.
                j = src.find('\n', i)
                i = n if j == -1 else j
                continue
            if c == '`':
                # A backtick string is a Mojo extension with no CPython
                # counterpart, but it is a STRING, and the two quote checks
                # below must not see a delimiter that is inside one. Two real
                # silent misparses came from its not being skipped as a whole
                # unit, and the second is the reason the unterminated-string
                # refusal below is safe to add at all:
                #
                #   x = `it's fine`   the `'` opened a phantom string, so the
                #                       apostrophe in an English word was
                #                       scanned as a delimiter — the new
                #                       "unterminated string literal" refusal
                #                       would have named a line with no
                #                       unterminated literal on it.
                #   x = `a"""b`       the `"""` was taken as a triple-quote
                #                       OPENER, so the backtick string was
                #                       split in two and the second half
                #                       swallowed the rest of the file.
                #
                # No backslash escape: a backtick string ends at the next
                # backtick, which is what `_TOKEN_RE`'s `` `[^`]*` `` arm and
                # `_strip_inline_comment`'s `in_str != '`'` special case both
                # already assume. `find` is the whole rule.
                j = src.find('`', i + 1)
                if j < 0:
                    loc = _src_loc(src, i, filename)
                    raise SyntaxError(f"{loc}unterminated backtick string literal")
                i = j + 1
                continue
            if c in ('"', "'"):
                # Recognize an optional string prefix (f/r/b/u/t, up to two
                # letters) immediately before this quote, but only if those
                # letters form a standalone token — not the tail of a
                # longer identifier like `self` before `.format("...")`.
                # Deliberately avoid `src[k-1] in 'fFrRbBuUtT'` here: this
                # codegen's compiled `in`-for-char* path is a documented stub
                # (always returns False), so under self-hosting this loop
                # never advanced and every string prefix (f/r/b/...) went
                # undetected — the sole remaining cause of make bootstrap's
                # mojo.tok/.ast divergence (an f-string at fire.py's own line
                # 174 tokenized as one run-on NAME instead of a STRING).
                # Explicit `==` comparisons are the same proven-safe pattern
                # Parser._strip_string_prefix_and_quotes already uses for this
                # identical check. Also: no `k > 0 and ...` combined guard —
                # this codegen's `and`/`or` evaluate BOTH operands (no
                # short-circuit), so the `k > 0` bounds check must be its own
                # `if`, never ANDed with the index it guards.
                #
                # Shared with _process_nested_tstrings via
                # `_string_prefix_start` (module-level helper) rather than
                # duplicated here — see
                # PARSE_FAIL_backslash_t_escape_misdetected_as_tstring_prefix.
                start = _string_prefix_start(src, i)
                # A triple-quote opener is three of the quote character `c`
                # that opened this position, i.e. `src[i:i+3] == c * 3`,
                # spelled as the two remaining characters instead of a 3-byte
                # slice compare. `c` is `src[i]` (read a few lines above, so
                # the first of the three is known), so this is the same test;
                # the `i + 2 < n` is the same short-slice case the compare
                # already handled, and it must be its own `if` because this
                # codegen's `and` evaluates BOTH operands rather than
                # short-circuiting (see the comment on the prefix scan above).
                #
                # It is O(1) per position where the slice compare was O(i):
                # `src[i:i+3]` lowers to mojo_cstr_region_eq, whose length
                # scan runs from byte 0 to `stop`, and this loop runs once
                # per QUOTE character in the file, so the total was the sum
                # of every quote's offset - measured at 1.0e9 byte reads
                # self-hosted on this file's own 349KB source, and quadratic
                # in it (see
                # bugs/CODEGEN_selfhost_tokenize_region_eq_quadratic.md,
                # which is where the runtime side of the same cost is
                # measured).
                is_triple = False
                if i + 2 < n:
                    if src[i + 1] == c:
                        if src[i + 2] == c:
                            is_triple = True
                if is_triple:
                    end = _scan_string_end(src, i, c, True)
                    if end < 0:
                        loc = _src_loc(src, i, filename)
                        raise SyntaxError(
                            f"{loc}unterminated triple-quoted string literal")
                    seg = src[last:start]
                    pending_pad = _flush_line_pad(out, seg, pending_pad)
                    literal = src[start:end]
                    placeholder = f"__MOJO_STR_{string_idx[0]}__"
                    string_cache[placeholder] = literal
                    string_idx[0] += 1
                    # Preserve the original newline count: collapsing a
                    # multi-line triple-quoted string (a docstring is the
                    # common case) to a single-line placeholder shifted
                    # every subsequent physical line number by (that
                    # string's line count - 1) — real bug, found via `for`
                    # loops later in this exact file (fire.py has a
                    # top-of-file module docstring) reporting a diagnostic
                    # line number dozens of lines before the loop's actual
                    # location, off by roughly the cumulative length of
                    # every docstring/multi-line string above it. The pad is
                    # NOT appended here — see `pending_pad`'s comment above.
                    out.append(placeholder)
                    pending_pad += _count_line_ends(literal, False)
                    i = end
                    last = i
                    continue
                else:
                    # An ordinary (non-triple) quoted string: skip it as one
                    # opaque unit so its contents can never be misread as a
                    # triple-quote delimiter. Left in the output untouched —
                    # only real triple-quoted spans get placeholder-ed.
                    #
                    # EXCEPT an interpolated one that CROSSES A LINE. Every pass
                    # after this one is line-based — `_source_lines` splits the
                    # source and the lexer then reads it a line at a time — so a
                    # literal with a newline in it cannot reach the token stream
                    # as text and has to be collapsed to a placeholder exactly as
                    # a triple-quoted one is. The condition is the literal
                    # itself, so every single-line literal on this tree still
                    # takes the untouched path and this branch is reached once
                    # per multi-line f-string. What makes such a literal
                    # possible at all is `_scan_string_end`'s replacement-field
                    # depth; without that this branch is dead code, which is the
                    # shape of the bug
                    # the fixed bug (a PEP 701 f-string whose replacement field
                    # spans lines was refused as an unterminated literal; see
                    # `_replacement_field_depth`'s docstring and
                    # `bugs/FORMAL_sweep_work_map_2026-10-05_b13.md` §5) — the
                    # first of the two halves was missing and this is the second.
                    interpolated = _prefix_is_interpolated(src[start:i])
                    end = _scan_string_end(src, i, c, False, interpolated)
                    if end < 0:
                        loc = _src_loc(src, i, filename)
                        raise SyntaxError(f"{loc}unterminated string literal")
                    literal = src[start:end]
                    if _count_line_ends(literal, True) > 0:
                        pending_pad = _flush_line_pad(out, src[last:start],
                                                     pending_pad)
                        placeholder = f"__MOJO_STR_{string_idx[0]}__"
                        string_cache[placeholder] = literal
                        string_idx[0] += 1
                        # Owed for the same reason and by the same rule as the
                        # triple-quoted arm: collapsing physical lines to one
                        # would move every later line number up. The cached
                        # value is the literal's own source text, prefix and
                        # delimiters included, which is this path's byte-exact
                        # contract for an f-string — the same node a single-line
                        # f-string produces.
                        out.append(placeholder)
                        pending_pad += _count_line_ends(literal, False)
                        last = end
                    i = end
                    continue
            i += 1
        tail = src[last:i]
        pending_pad = _flush_line_pad(out, tail, pending_pad)
        if pending_pad:
            out.append('\n' * pending_pad)
        return ''.join(out)

    src = replace_multiline_strings(src)
    raw_lines = _source_lines(src)
    # Join backslash-continued lines: "expr = \\\n    continuation" → one logical line
    #
    # CPython deletes a backslash-newline pair from the source BEFORE it
    # tokenizes, and what the pair is worth depends on where it sits. Outside a
    # string it separates two tokens, so a space is the right thing to put
    # between the joined halves and the next line's indentation is
    # insignificant. INSIDE a string the pair is worth nothing and the next
    # line's indentation is CONTENT, and CPython keeps both facts:
    #
    #     x = "a\
    #     b"          CPython: 'ab'         here, before: 'a b'
    #     x = "a\
    #         b"      CPython: 'a    b'     here, before: 'a  b'
    #
    # (the second is `a`, four spaces, `b` — the join put one space in and took
    # the four out). Both were the silent-miscompile class, and both are the
    # same defect shape as the one `_scan_string_end` was written for: a
    # line-joining pass with no idea where the literals are.
    # `_unterminated_quote_pos` is the one place that now answers that, and it
    # is asked about the RSTRIPPED line, which is the text whose last character
    # the loop has just decided is a backslash.
    #
    # What the pair is worth is CPython's own rule, measured with `tokenize`
    # rather than inferred: the STRING token's TEXT is `'"a\\nb"'` for
    # `"a\<nl>b"` and `'r"a\\\nb"'` for `r"a\<nl>b"` — deleted unless the
    # literal is raw. So the raw case is NOT a deletion, and it cannot be one
    # here: a value reaches the token stream with a newline in it only through
    # the placeholder `replace_multiline_strings` builds, and this pass runs
    # after it. Hence the placeholder written below, holding the two characters
    # the source wrote and substituted back out of the STRING token's own value
    # by `_substitute_str_placeholders`. The triple-quoted shapes are
    # placeholdered before this pass runs and so are untouched by it either way
    # — `r"""a\<nl>b"""` already keeps the pair, which is CPython's answer.
    joined = []
    line_nums = []  # track physical line number (1-based) for each logical line
    i = 0
    while i < len(raw_lines):
        start_line = i + 1  # 1-indexed physical line number
        line = raw_lines[i]
        while line.rstrip().endswith('\\'):
            stripped = line.rstrip()
            quote_pos = _unterminated_quote_pos(stripped)
            inside = quote_pos >= 0
            if inside and _is_raw_literal_at(stripped, quote_pos):
                # The pair is CONTENT in a raw literal, so the backslash stays
                # where the source wrote it and only the line break has to be
                # carried across — as a placeholder, because nothing else in
                # this pass can hand a newline to the token stream. A cache of
                # its own, restored into the STRING token's own value below.
                placeholder = f"{_CONT_PLACEHOLDER}{string_idx[0]}__"
                continuation_cache[placeholder] = "\n"
                string_idx[0] += 1
                line = stripped + placeholder
            else:
                line = stripped[:-1]  # strip the backslash
            i += 1
            if i < len(raw_lines):
                nxt = raw_lines[i] if inside else raw_lines[i].lstrip()
                line = line + ('' if inside else ' ') + nxt
            else:
                break
        joined.append(line)
        line_nums.append(start_line)
        i += 1
    # Phase 2: lex line by line
    out: list[Token] = []
    stack = [0]
    paren_depth = 0  # Track (), [], {} nesting to suppress INDENT/DEDENT inside
    continued_from_prev = False  # last physical line ended in an implicit-continuation token
    for line_idx, line in enumerate(joined):
        physical_line = line_nums[line_idx]
        expanded = _indent_expanded(line)
        raw_content = expanded.lstrip()
        if not raw_content or raw_content.startswith(_CMT_CHAR): continue
        content = _strip_inline_comment(raw_content).rstrip()
        if not content: continue
        indent = len(expanded) - len(raw_content)
        sub_stmts = _split_on_separators(content)
        for stmt_idx, stmt in enumerate(sub_stmts):
            stmt = stmt.strip()
            if not stmt: continue
            # Only emit INDENT/DEDENT when at paren depth 0, and not when this
            # physical line is itself just the continuation of the previous one.
            if stmt_idx == 0 and paren_depth == 0 and not continued_from_prev:
                if indent > stack[-1]:
                    stack.append(indent)
                    out.append(Token("INDENT", "", line=physical_line, col=0))
                else:
                    while indent < stack[-1]:
                        stack.pop()
                        out.append(Token("DEDENT", "", line=physical_line, col=0))
            # Handle t-strings with nested braces before tokenization
            stmt_final = _process_nested_tstrings(stmt, string_cache, string_idx)

            for m in _TOKEN_RE.finditer(stmt_final):
                kind = m.lastgroup or "INT"
                val  = m.group()
                col  = m.start()
                if kind in ("WS", "UNK", "XFER"): continue
                if kind == "NAME" and val in _KEYWORDS: kind = "KW"
                # Restore multi-line strings from cache
                if kind == "NAME" and val in string_cache:
                    val = string_cache[val]
                    kind = "STRING"
                # …and the placeholders that landed INSIDE one: a raw literal's
                # line continuation is kept as content, and a content value can
                # only carry a newline through a placeholder.
                if kind == "STRING":
                    val = _substitute_str_placeholders(val, continuation_cache)
                # Track paren/bracket/brace depth to suppress INDENT/NEWLINE inside
                if kind in ("LPAREN", "LBRACKET", "LBRACE") or val in ("(", "[", "{"): paren_depth += 1
                elif kind in ("RPAREN", "RBRACKET", "RBRACE") or val in (")", "]", "}"): paren_depth = max(0, paren_depth - 1)
                out.append(Token(kind, val, line=physical_line, col=col))
            # Only emit NEWLINE when paren depth is 0 (not inside brackets/parens).
            # Also suppress it when the last token on the line is one that can only
            # be followed by more expression (a binary operator, assignment, `->`,
            # or a low-precedence keyword operator like `and`/`or`/`not`/`in`/`is`)
            # — real Mojo treats such a line as implicitly continued onto the next
            # physical line, no enclosing parens required. Deliberately excludes a
            # trailing `.` — `...` (Ellipsis, a common stub-function body) tokenizes
            # as three DOTs and must NOT be treated as a continuation.
            #
            # Also unconditionally excludes a trailing `*`: it can only appear as
            # the multiplication operator or as the wildcard marker of
            # `from MODULE import *` / `import *`. Real Python's own grammar never
            # allows a bare trailing `*` to start an implicit continuation anyway
            # (this "no-backslash-needed" feature is entirely this project's own
            # addition, not part of Python — real Python requires an explicit `\`
            # or enclosing parens for a line-ending `*` to continue). Nothing in
            # this codebase's own corpus (.mojo sources, test suites) relies on
            # `x = a *\n    b`-shaped continuation, so there's no real caller to
            # preserve narrowly. Treating `*` as ending a statement here fixes the
            # much more common and much worse case: `from X import *` (or bare
            # `import *`) — whose trailing `*` is a wildcard-import marker, not an
            # operator awaiting a right-hand operand — was being misread as a
            # continuation, silently swallowing the NEWLINE (and therefore the
            # DEDENT tracking) between it and whatever statement follows. That is
            # a real, silent semantic miscompile for the extremely common
            # `try: from _fast import * / except ImportError: from _slow import *`
            # idiom (e.g. CPython's own Lib/datetime.py): the dropped NEWLINE/DEDENT
            # meant the parser never recognized the following `except` as starting
            # a handler, so `except ImportError:` was misparsed as bare statements
            # and the TryStmt ended up with handlers=[] — the except clause never
            # actually caught anything.
            last = out[-1] if out else None
            implicit_continuation = last is not None and (
                (last.kind == "OP" and last.value != "^" and last.value != "*")  # `^` transfer sigil, `*` wildcard/mul — see above
                or last.kind in ("AUGASSIGN", "ASSIGN", "ARROW")
                or (last.kind == "KW" and last.value in ("and", "or", "not", "in", "is"))
            )
            if paren_depth == 0 and not implicit_continuation:
                out.append(Token("NEWLINE", "", line=physical_line, col=0))
            continued_from_prev = paren_depth == 0 and implicit_continuation
    last_line = 0
    if line_nums:
        last_line = line_nums[-1]
    while len(stack) > 1:
        stack.pop()
        out.append(Token("DEDENT", "", line=last_line, col=0))
    out.append(Token("EOF", "", line=last_line, col=0))
    return out

# ── Parser ─────────────────────────────────────────────────────────
# Higher number binds tighter. Mirrors CPython's grammar: boolean ops loosest,
# then comparisons, then bitwise | ^ &, shifts, arithmetic, power. (Comparisons
# bind LOOSER than the bitwise ops — `a == b ^ c` is `a == (b ^ c)`.)
_PREC    = {
    ':=': 1,
    '==': 5,
    '!=': 5,
    '<': 5,
    '<=': 5,
    '>': 5,
    '>=': 5,
    '|': 6,
    '^': 7,
    '&': 8,
    '<<': 9,
    '>>': 9,
    '+': 10,
    '-': 10,
    '*': 11,
    '@': 11,
    '/': 11,
    '//': 11,
    '%': 11,
    '**': 12,
}
_KW_PREC = {
    'or': 2,
    'and': 3,
    'not': 4,
    'in': 5,
    'is': 5,
    'as': 13,
}

# Precedence level shared by every operator that can participate in a
# Python-style chained comparison (`a < b <= c != d`): the OP-form operators
# in _PREC ('==','!=','<','<=','>','>=') and the KW-form ones in _KW_PREC
# ('in', 'is', plus the two-token 'not in'/'is not' forms). All chain at the
# SAME precedence in real Python regardless of which of these forms is used
# — 'not in' is deliberately treated as this same level here (not
# _KW_PREC['not']'s lower value 4, which only governs the unrelated prefix
# `not expr` operator) so `a in b not in c` chains correctly.
_COMPARE_CHAIN_PREC = 5
_COMPARE_OPS = {'==', '!=', '<', '<=', '>', '>='}

def _synthesize_fieldwise_inits(stmts: list) -> list:
    """Mojo's @fieldwise_init decorator synthesizes a memberwise
    __init__(out self, field1, field2, ...) constructor alongside any
    explicit __init__ a struct already defines. The parser only sees Mojo
    source text and has no other way to represent this real, additional
    constructor overload, so materialize it here as an ordinary
    FunctionDef appended to StructDef.methods.

    Called once, unconditionally, at the end of parse_module() — not as an
    opt-in step some callers remember to invoke — so every consumer of a
    parsed module (codegen's own struct-method walk, source-based overload
    elaboration, dylib reflection export) sees the identical
    StructDef.methods list. If different consumers synthesized this
    independently, a dylib-resolved call and a source-elaborated call for
    the same struct could disagree on the overload's parameter order/mangling.

    Idempotent via a marker on the StructDef itself (not a local set),
    since parsed stmts get cached and handed to multiple GimpleGen
    instances (module_stmts) — a second call on the same objects must not
    double-append.
    """
    for s in stmts:
        if not isinstance(s, StructDef):
            continue
        if getattr(s, '_fieldwise_ctor_synthesized', False):
            continue
        s._fieldwise_ctor_synthesized = True
        decs = s.decorators or []
        if 'fieldwise_init' not in decs and 'value' not in decs:
            continue
        field_decls = [f for f in s.fields if isinstance(f, VarDecl)]
        if not field_decls:
            continue
        existing = {m.name for m in s.methods}
        # A struct can hand-write its own __init__ (e.g. a no-arg one for
        # Defaultable conformance) alongside @fieldwise_init's synthesized
        # memberwise one — real Mojo overloads on arity, it doesn't let the
        # hand-written one suppress the synthesized one. Comparing by name
        # alone (as opposed to (name, arity)) treated any hand-written
        # __init__ as "already have one" and dropped the fieldwise overload
        # entirely, so `Person("John Smith", 42)` had no matching __init__
        # to call even though the struct is @fieldwise_init.
        target_arity = 1 + len(field_decls)  # self + one param per field
        has_matching_init = any(
            m.name == '__init__' and len(m.params) == target_arity
            for m in s.methods)
        if not has_matching_init:
            params = [('self', s.name)] + [(f.name, f.type_ann) for f in field_decls]
            body = [AssignStmt(target=MemberExpr(obj=IdentExpr(name='self'), member=f.name),
                                value=IdentExpr(name=f.name))
                    for f in field_decls]
            s.methods.append(FunctionDef(
                name='__init__', params=params, return_type=None, body=body,
                param_convs={'self': 'out'}))
        if 'value' not in decs:
            continue
        # @value additionally synthesizes __copyinit__/__moveinit__ — a
        # member-by-member copy of `existing` into `self` (this interpreter
        # has no distinct move-vs-copy semantics, so both bodies match).
        if '__copyinit__' not in existing:
            params = [('self', s.name), ('existing', s.name)]
            body = [AssignStmt(target=MemberExpr(obj=IdentExpr(name='self'), member=f.name),
                                value=MemberExpr(obj=IdentExpr(name='existing'), member=f.name))
                    for f in field_decls]
            s.methods.append(FunctionDef(
                name='__copyinit__', params=params, return_type=None, body=body,
                param_convs={'self': 'out'}))
        if '__moveinit__' not in existing:
            params = [('self', s.name), ('existing', s.name)]
            body = [AssignStmt(target=MemberExpr(obj=IdentExpr(name='self'), member=f.name),
                                value=MemberExpr(obj=IdentExpr(name='existing'), member=f.name))
                    for f in field_decls]
            s.methods.append(FunctionDef(
                name='__moveinit__', params=params, return_type=None, body=body,
                param_convs={'self': 'out', 'existing': 'owned'}))
    return stmts

# Built-in stdlib trait names — never declared via `trait X:` in the
# source being parsed, so Parser._known_traits (a single forward pass over
# the file's own tokens) can't discover them; hardcoded instead.
_BUILTIN_TRAITS = {
    'Movable', 'Copyable', 'ImplicitlyCopyable', 'Defaultable', 'AnyType',
    'Hashable', 'Stringable', 'Sized', 'Boolable', 'Intable', 'Writable',
    'KeyElement', 'CollectionElement', 'EqualityComparable', 'Representable',
    'Comparable', 'Indexer', 'Absable', 'Powable', 'Roundable',
}

def _scan_yield_bearing(node, out_ids):
    """Walk `node`'s subtree collecting id() of every statement/expression
    node that has a YieldExpr/YieldFromExpr reachable within it, WITHOUT
    crossing into a nested FunctionDef/LambdaExpr body (a `yield` there
    belongs to that inner function's own scope, not this one — matches real
    Python scoping) or into a Comprehension's element/generators (real
    Python: `yield` inside a comprehension is a SyntaxError in the general
    case; simplest correct stance here is to not detect/support it at all).

    Returns True if `node` itself is (or contains) a yield-bearing node, and
    as a side effect records every such node's id() into `out_ids`.
    """
    if node is None:
        return False
    if isinstance(node, (YieldExpr, YieldFromExpr)):
        out_ids.add(id(node))
        return True
    if isinstance(node, (FunctionDef, LambdaExpr)):
        # A `yield` inside a nested function/lambda makes THAT function a
        # generator, not the enclosing one — don't recurse, don't mark.
        return False
    if isinstance(node, Comprehension):
        # `yield` inside a comprehension body isn't supported/detected here
        # (see docstring) — don't recurse into it.
        return False
    found = False
    if isinstance(node, list):
        for item in node:
            if _scan_yield_bearing(item, out_ids):
                found = True
    elif dataclasses.is_dataclass(node):
        for f in dataclasses.fields(node):
            if _scan_yield_bearing(getattr(node, f.name), out_ids):
                found = True
    if found:
        out_ids.add(id(node))
    return found


def _detect_generator(body: list):
    """Given a FunctionDef's own body (list of statements), return
    (is_generator, yield_bearing_node_ids frozenset-or-None)."""
    out_ids = set()
    found = _scan_yield_bearing(body, out_ids)
    if not found:
        return False, None
    return True, frozenset(out_ids)


# ─── Generator expressions: one shared lowering, two front ends ────────────
#
# A parenthesized generator expression (`(x * 2 for x in xs if x > 1)`) is
# represented by the parser as a `Comprehension` with kind == 'generator' —
# structurally identical to a list comprehension apart from that kind tag.
# `genexp_body` below is the SINGLE definition of what such an expression
# means as statements: the nested `for`/`if` chain of its `generators`,
# innermost one a single `yield` of the element expression. Both front ends
# build exactly that, and neither invents its own idea of the semantics:
#
# - The interpreter (myinterpreter.py `_generator_expression`) hands the
#   statement list straight to the same `MojoGeneratorObject` a real `def`
#   generator function uses, so it gets real laziness, `.send()`/`.close()`,
#   and correct closure capture over the enclosing function's live scope for
#   free.
# - The compiled path (`desugar_genexps` below) hoists the same statement
#   list into a synthesized module-level generator FUNCTION and replaces the
#   expression with a call to it, which is a shape the generator codegen
#   already supports natively.
#
# The one semantic detail the parameter-passing strategy buys for free:
# real Python evaluates a generator expression's OUTERMOST iterable eagerly,
# at construction time. The desugared call site's own argument evaluation
# does exactly that, so the outermost iterable stays eager without any
# statement-level bookkeeping at the call site.

# Names the genexp desugar must never treat as a captured local: they are
# bound by the runtime in every scope, so passing one as an argument would
# mean passing a builtin/constant as a value (a shape the compiled path
# cannot call).
_BUILTIN_NAMES = frozenset({
    'None', 'True', 'False', 'len', 'print', 'range', 'str', 'int', 'float',
    'bool', 'list', 'dict', 'set', 'tuple', 'enumerate', 'zip', 'sum', 'min',
    'max', 'any', 'all', 'sorted', 'reversed', 'abs', 'map', 'filter',
    'isinstance', 'hasattr', 'getattr', 'setattr', 'type', 'open', 'input',
    'self', 'super',
})


# Calls whose result is a fresh, side-effect-free iterable — the ones the
# compiled genexp desugar may inline into a hoisted generator function
# (see `_inline_safe_outer_iterable`).
_PURE_ITER_CALLS = frozenset({
    'range', 'enumerate', 'zip', 'reversed', 'sorted',
})


# Annotations that make a parameter a usable ITERABLE type for a synthesized
# generator function: the hoisted function's parameter then carries a real
# container type, so the compiled body types its loop variable from the
# annotation instead of guessing from a runtime tag (an untyped parameter
# degrades to a boxed int64_t, and the arithmetic on the loop variable is
# then emitted for whichever branch the guess picked — a list of ints
# silently becoming `char *` string repetition).
#
# Deliberately NOT `Set` or `String`, both measured on a HAND-WRITTEN
# generator with that annotation (so this is the generator body's own
# limitation, not the desugar's):
#   - `Set[Int]`: iterating it inside a generator body reads the set's
#     internal layout as a list — `for x in items: yield x` printed
#     `[3, 4390443264, 0]` for `{1, 2, 3}`.
#   - `String`: `for s in items` has no lowering there at all
#     ("mojo_unsupported_iter: 'for' loop over unsupported iterable type
#     int64"), producing an empty result.
# Both keep the existing (eager but CORRECT) lowering rather than being
# compiled into a wrong answer.
_CONTAINER_ANNOTATIONS = ('List', 'Dict', 'Slice',
                          'ListLiteral', 'DictLiteral')


def _container_annotation(ann) -> str:
    """The annotation string if it names a container type, else ''.

    Used to decide whether a generator expression over a PARAMETER can be
    desugared into a typed generator function: the parameter's own
    declaration is authoritative, so passing it through is exact — no
    inference, no guesswork. An unannotated parameter (or a scalar
    annotation) gives nothing to carry, and that case stays on the eager
    path rather than being compiled from a guess."""
    if not ann or not isinstance(ann, str):
        return ''
    base = ann.split('[', 1)[0].strip()
    if base in _CONTAINER_ANNOTATIONS:
        return ann
    return ''


def _inline_safe_outer_iterable(node, module_names: set, rebound_module: set) -> bool:
    """True iff the compiled genexp desugar may place this outermost
    iterable expression INSIDE the synthesized generator function instead
    of passing it in.

    Inlining is what gives the compiled body a real, inferred iterable (see
    `_GenexpDesugarer`), at the cost of evaluating it on the generator's
    first resume rather than at construction. That is unobservable exactly
    when re-evaluating it later cannot differ from evaluating it now:

    - a literal container/sequence (nothing to defer at all),
    - a MODULE-LEVEL name that is never rebound: the hoisted function reads
      the same global directly, with no parameter to lose the type through.
      A local or parameter name is NOT safe this way — naming it in the
      hoisted body would just turn it into an untyped parameter of that
      function, the very shape inlining exists to avoid,
    - a call to one of `_PURE_ITER_CALLS`, which builds a fresh iterable
      from arguments that are themselves re-evaluated identically.

    Anything else (an arbitrary call, an attribute, a subscript) could
    observe or produce something different on the second evaluation, so it
    is left alone."""
    if isinstance(node, (ListExpr, TupleExpr, DictExpr, SetExpr,
                         StringLiteral, TstringLiteral)):
        return True
    if isinstance(node, IdentExpr):
        return node.name in module_names and node.name not in rebound_module
    if isinstance(node, CallExpr) and isinstance(node.func, IdentExpr):
        return node.func.name in _PURE_ITER_CALLS
    return False


def genexp_body(expr, outer_iterable) -> list:
    """Statement list equivalent to the generator expression `expr` (a
    `Comprehension` with kind == 'generator'): its `generators` clauses as
    nested `for` loops, each clause's `if` conditions as nested `if`s inside
    that clause's own loop body (so a condition is tested after its target
    is bound, per item, exactly where Python evaluates it), and a single
    `yield` of the element expression at the center.

    `outer_iterable` is the expression node the OUTERMOST loop iterates —
    the interpreter passes an `IdentExpr` naming the already-evaluated
    iterable (evaluated eagerly at construction time, as real Python does;
    see the note above), while the compiled path passes the outermost
    iterable expression itself (see `desugar_genexps`)."""
    gens = expr.generators
    body = [ExprStmt(value=YieldExpr(value=expr.element,
                                     line=expr.line, col=expr.col),
                     line=expr.line, col=expr.col)]
    i = len(gens) - 1
    while i >= 0:
        gen = gens[i]
        inner = body
        for cond in gen.conditions:
            inner = [IfStmt(condition=cond, then_body=inner, elifs=[],
                            else_body=None, line=gen.line, col=gen.col)]
        iterable = gen.iterable
        if i == 0:
            iterable = outer_iterable
        body = [ForStmt(target=gen.target, iterable=iterable, body=inner,
                        else_body=None, is_async=False,
                        line=gen.line, col=gen.col)]
        i = i - 1
    return body


def _target_names(target, out: set):
    """Collect the names a binding target introduces. `target` is a plain
    string for comprehension/`for` targets — possibly a tuple target and
    possibly starred (`a, *rest`) — or an expression node (an ordinary
    assignment target). The string form splits through `target_slots`, so
    a NESTED target's commas do not tear it into fragments bound as bogus
    names."""
    if isinstance(target, str):
        name = target.strip()
        if for_target_is_tuple(name):
            for part in target_slots(_target_group_inner(name) or name):
                _target_names(part, out)
            return
        if name.startswith('*'):
            name = name[1:].strip()
        if name and not name.startswith('.'):
            out.add(name)
        return
    if isinstance(target, IdentExpr):
        out.add(target.name)
    elif isinstance(target, (TupleExpr, ListExpr)):
        for el in target.elements:
            _target_names(el, out)
    elif isinstance(target, UnaryOp) and target.op == '*':
        _target_names(target.operand, out)


def _count_binding_names(node, counts: dict, stop_at_functions: bool):
    """Count how many times each name is BOUND under `node` (same targets
    as `_collect_assigned_names`, but counted rather than merely recorded).
    Used to tell an initialization from a rebind."""
    if node is None:
        return
    if isinstance(node, list):
        for item in node:
            _count_binding_names(item, counts, stop_at_functions)
        return
    if stop_at_functions and isinstance(node, (FunctionDef, LambdaExpr)):
        return
    if isinstance(node, (AssignStmt, AugAssignStmt, ForStmt)):
        names: set = set()
        _target_names(node.target, names)
        for n in names:
            counts[n] = counts.get(n, 0) + 1
    elif isinstance(node, VarDecl):
        names = set()
        _target_names(node.name, names)
        for n in names:
            counts[n] = counts.get(n, 0) + 1
    elif isinstance(node, MultiAssignStmt):
        for t in node.targets or []:
            names = set()
            _target_names(t, names)
            for n in names:
                counts[n] = counts.get(n, 0) + 1
    if isinstance(node, Comprehension):
        for gen in node.generators:
            names = set()
            _target_names(gen.target, names)
            for n in names:
                counts[n] = counts.get(n, 0) + 1
    if dataclasses.is_dataclass(node):
        for f in dataclasses.fields(node):
            _count_binding_names(getattr(node, f.name), counts, stop_at_functions)


def _collect_assigned_names(node, out: set, stop_at_functions: bool):
    """Names BOUND anywhere under `node` (assignments, declarations,
    augmented assignments, `for` targets, `global` declarations). Used to
    decide whether a generator expression captures a name that is rebound
    later in its enclosing function — the one capture shape a
    pass-by-value argument cannot model (real Python's generator expression
    closes over a CELL, so a rebind is visible to later iterations).

    `stop_at_functions` keeps the walk out of nested `def`/`lambda` bodies
    (a caller asking about ONE function's own scope), or descends through
    them (a caller asking about the whole module)."""
    if node is None:
        return
    if isinstance(node, list):
        for item in node:
            _collect_assigned_names(item, out, stop_at_functions)
        return
    if stop_at_functions and isinstance(node, (FunctionDef, LambdaExpr)):
        return
    if isinstance(node, (AssignStmt, AugAssignStmt, ForStmt)):
        _target_names(node.target, out)
    elif isinstance(node, VarDecl):
        _target_names(node.name, out)
    elif isinstance(node, MultiAssignStmt):
        for t in node.targets:
            _target_names(t, out)
    elif isinstance(node, GlobalStmt):
        for n in node.names:
            out.add(n)
    if isinstance(node, Comprehension):
        for gen in node.generators:
            _target_names(gen.target, out)
    if dataclasses.is_dataclass(node):
        for f in dataclasses.fields(node):
            _collect_assigned_names(getattr(node, f.name), out, stop_at_functions)


def _collect_receiver_names(node, out: set):
    """Names used as the RECEIVER of an attribute access (`x` in `x.f` /
    `x.m()`) anywhere under `node`.

    A generator expression that reads a field or calls a method on a local
    captures that local and uses it as an object inside the hoisted
    generator. The compiled coroutine body has no working model for that —
    measured: `(c.note(i) for i in range(1000))` lowered fine and then
    printed `[4310292864, 4310292864, 4310292864]` with the counter still
    at 0, i.e. the receiver arrived as a bare integer and every field
    access read garbage. A silent wrong answer, so the desugar declines
    these rather than compiling them; the expression keeps its correct
    (eager) lowering."""
    if node is None:
        return
    if isinstance(node, MemberExpr):
        if isinstance(node.obj, IdentExpr):
            out.add(node.obj.name)
        _collect_receiver_names(node.obj, out)
        return
    if isinstance(node, list):
        for item in node:
            _collect_receiver_names(item, out)
        return
    if dataclasses.is_dataclass(node):
        for f in dataclasses.fields(node):
            _collect_receiver_names(getattr(node, f.name), out)


def _collect_free_names(node, bound: set, out: list):
    """Names `node` READS, in first-appearance (source) order, excluding
    anything in `bound` (the generator expression's own loop targets) and
    excluding the attribute half of `obj.attr` (only `obj` is a name)."""
    if node is None:
        return
    if isinstance(node, IdentExpr):
        if node.name not in bound and node.name not in out:
            out.append(node.name)
        return
    if isinstance(node, MemberExpr):
        _collect_free_names(node.obj, bound, out)
        return
    if isinstance(node, list):
        for item in node:
            _collect_free_names(item, bound, out)
        return
    if isinstance(node, Comprehension):
        # A nested generator expression has its own scope and its own
        # targets: recurse so its targets count as bound HERE too.
        nested_bound = set(bound)
        for gen in node.generators:
            _target_names(gen.target, nested_bound)
        if node.kind == 'dict':
            _collect_free_names(node.element, nested_bound, out)
            _collect_free_names(node.key, nested_bound, out)
        else:
            _collect_free_names(node.element, nested_bound, out)
        for gen in node.generators:
            _collect_free_names(gen.iterable, nested_bound, out)
            for cond in gen.conditions:
                _collect_free_names(cond, nested_bound, out)
        return
    if dataclasses.is_dataclass(node):
        for f in dataclasses.fields(node):
            if f.name in ('target', 'targets', 'name'):
                continue
            _collect_free_names(getattr(node, f.name), bound, out)


class _GenexpDesugarer:
    """Rewrites every `Comprehension(kind='generator')` in a parsed module
    into a call to a synthesized module-level generator function (see
    `genexp_body`), returning the module with those definitions inserted at
    the front — before any call site can run, since real Python executes
    top-level statements in order.

    The synthesized function INLINES the outermost iterable expression
    rather than taking it as a parameter. That is what makes the compiled
    lowering correct: the generator body's own `for` then sees the very
    expression the program wrote, so the compiler's regular container
    inference types the loop variable (and everything computed from it)
    exactly as it would in a hand-written generator — a value smuggled in
    through an untyped parameter instead erases to a boxed `int64_t`, and
    the loop over it falls back to a runtime-tag guess whose ARITHMETIC is
    then emitted for the guessed branch's type (a list of ints silently
    becoming `char *` string repetition). The cost is that the outermost
    iterable is evaluated on the generator's first resume rather than at
    construction, which is why `_inline_safe_outer_iterable` restricts it to
    expressions where that is unobservable.

    Names the expression reads that are neither module-level names nor
    builtins are CAPTURED: passed as extra arguments at the call site and
    taken as parameters by the synthesized function, so the hoisted
    function never needs a closure. A captured name REBOUND anywhere in the
    enclosing function is left alone (the node is not rewritten): real
    Python's generator expression closes over a mutable cell, so such a
    capture is genuinely observable (`g = (x + n for x in xs); n = 5` sees
    the new `n`), and passing it by value would silently compute something
    else. `self` is left alone for the same reason — a method's receiver is
    not safely passable as a value."""

    def __init__(self, module_names: set, rebound_module: set):
        self.module_names = module_names
        self.rebound_module = rebound_module
        self.hoisted: list = []
        self.counter = 0
        self._assigned_cache: dict = {}

    def _unique_name(self) -> str:
        while True:
            name = '__genexp_' + str(self.counter)
            self.counter = self.counter + 1
            if name not in self.module_names:
                self.module_names.add(name)
                return name

    def _rebound_in(self, fn_body):
        """Names bound MORE THAN ONCE in an enclosing function's own body,
        cached per body list — the ones a pass-by-value capture cannot
        model.

        A single assignment is that name's INITIALIZATION (`items = []`,
        `c = Counter()`), and capturing its value is exact. Two or more is a
        genuine rebind, where real Python's generator expression would see
        whichever object is current at each iteration rather than the one
        that was current when the expression was written."""
        if fn_body is None:
            return set()
        key = id(fn_body)
        cached = self._assigned_cache.get(key)
        if cached is None:
            counts: dict = {}
            _count_binding_names(fn_body, counts, True)
            cached = {n for n, c in counts.items() if c > 1}
            self._assigned_cache[key] = cached
        return cached

    def desugar(self, node, fn_body, fn_params=None):
        """Return the replacement expression for one generator expression,
        or `node` itself when it must be left alone.

        The outermost iterable decides HOW the hoisted function receives it:
        inlined into its body when re-evaluating it later is unobservable
        (a literal, a pure call, a never-rebound module-level name), or
        passed as a TYPED PARAMETER when it is a parameter of the enclosing
        function carrying a container annotation — the declaration is
        authoritative, so the synthesized generator types its loop variable
        exactly. Anything else is left alone."""
        gens = node.generators
        outer = gens[0].iterable
        typed_param = ''
        if isinstance(outer, IdentExpr) and fn_params:
            typed_param = _container_annotation(fn_params.get(outer.name))
        if not typed_param and not _inline_safe_outer_iterable(
                outer, self.module_names, self.rebound_module):
            return node

        bound: set = set()
        for gen in gens:
            _target_names(gen.target, bound)
        # Free names of everything the hoisted body will contain EXCEPT the
        # outermost iterable, which is inlined rather than captured.
        free: list = []
        if node.kind == 'dict':
            _collect_free_names(node.element, bound, free)
            _collect_free_names(node.key, bound, free)
        else:
            _collect_free_names(node.element, bound, free)
        for i, gen in enumerate(gens):
            if i > 0:
                _collect_free_names(gen.iterable, bound, free)
            for cond in gen.conditions:
                _collect_free_names(cond, bound, free)

        captures: list = []
        rebound: list = []
        rebound_names = self._rebound_in(fn_body)
        for name in free:
            if name in _BUILTIN_NAMES or name in self.module_names:
                continue
            if name in rebound_names:
                rebound.append(name)
                continue
            captures.append(name)

        receivers: set = set()
        if node.kind == 'dict':
            _collect_receiver_names(node.element, receivers)
            _collect_receiver_names(node.key, receivers)
        else:
            _collect_receiver_names(node.element, receivers)
        for i, gen in enumerate(gens):
            if i > 0:
                _collect_receiver_names(gen.iterable, receivers)
            for cond in gen.conditions:
                _collect_receiver_names(cond, receivers)

        if rebound or 'self' in free or (receivers & set(captures)):
            # Left exactly as the parser produced it — see the class
            # docstring, and _collect_receiver_names, for why each of
            # these captures is not approximable.
            return node

        fn_name = self._unique_name()
        if typed_param:
            # The iterable rides in as the generator's FIRST parameter,
            # carrying the enclosing parameter's own annotation.
            outer_iter = IdentExpr(name=outer.name, line=node.line, col=node.col)
            params = [(outer.name, typed_param)]
        else:
            outer_iter = outer
            params = []
        body = genexp_body(node, outer_iter)
        is_gen, yield_ids = _detect_generator(body)
        for cap in captures:
            params.append((cap, None))
        self.hoisted.append(FunctionDef(
            name=fn_name, params=params, return_type=None, body=body,
            is_generator=is_gen, yield_bearing_node_ids=yield_ids,
            line=node.line, col=node.col))

        args = []
        if typed_param:
            args.append(IdentExpr(name=outer.name, line=node.line, col=node.col))
        for cap in captures:
            args.append(IdentExpr(name=cap, line=node.line, col=node.col))
        return CallExpr(func=IdentExpr(name=fn_name, line=node.line, col=node.col),
                        args=args, line=node.line, col=node.col)

    # ── generic walk ──────────────────────────────────────────────────────

    def walk_list(self, seq: list, fn_body, fn_params=None):
        i = 0
        while i < len(seq):
            item = seq[i]
            if isinstance(item, Comprehension) and item.kind == 'generator' and item.generators:
                seq[i] = self.desugar(item, fn_body, fn_params)
            elif isinstance(item, list):
                self.walk_list(item, fn_body, fn_params)
            elif dataclasses.is_dataclass(item):
                self.walk_node(item, fn_body, fn_params)
            i = i + 1

    def walk_node(self, node, fn_body, fn_params=None):
        """Recurse into one non-generator-expression dataclass node."""
        if isinstance(node, FunctionDef):
            # Parameter defaults and decorators are evaluated in the
            # ENCLOSING scope, so they keep the outer `fn_body`/`fn_params`;
            # the body itself becomes the new enclosing function scope, with
            # THIS function's own parameters visible to a genexp inside it
            # (their declared annotations are what a typed-parameter
            # desugar carries into the synthesized generator).
            for f in dataclasses.fields(node):
                if f.name == 'body':
                    continue
                self.walk_field(node, f.name, fn_body, fn_params)
            own = {}
            for p in node.params or []:
                if isinstance(p, tuple) and len(p) >= 2:
                    own[p[0]] = p[1]
                elif isinstance(p, str):
                    own[p] = None
            self.walk_list(node.body, node.body, own)
            return
        if isinstance(node, LambdaExpr):
            # A lambda's `body` is a single EXPRESSION (not a statement
            # list, unlike FunctionDef.body), and it is evaluated in the
            # enclosing scope.
            self.walk_field(node, 'body', fn_body, fn_params)
            return
        for f in dataclasses.fields(node):
            self.walk_field(node, f.name, fn_body, fn_params)

    def walk_field(self, obj, name: str, fn_body, fn_params=None):
        value = getattr(obj, name)
        if isinstance(value, list):
            self.walk_list(value, fn_body, fn_params)
        elif isinstance(value, Comprehension) and value.kind == 'generator' and value.generators:
            setattr(obj, name, self.desugar(value, fn_body, fn_params))
        elif dataclasses.is_dataclass(value):
            self.walk_node(value, fn_body, fn_params)


def desugar_genexps(stmts: list) -> list:
    """Module-level entry point: rewrite every generator expression in
    `stmts` into a call to a synthesized module-level generator function,
    returning the same list with those definitions inserted at the front.

    A no-op for a module with no generator expressions, and for any single
    expression whose capture cannot be modeled (see `_GenexpDesugarer`).

    The names of the functions it synthesized are recorded in
    `DESUGARED_GENEXP_NAMES` (cleared and repopulated on every call) so the
    compiled pipeline can verify afterwards that each one really was lowered
    — a synthesized generator that NO path claims used to become a silent
    stub at its call site."""
    global DESUGARED_GENEXP_NAMES
    d = _GenexpDesugarer(_module_level_names(stmts), _rebound_names(stmts))
    d.walk_list(stmts, None)
    if d.hoisted:
        stmts[0:0] = d.hoisted
    DESUGARED_GENEXP_NAMES = [fn.name for fn in d.hoisted]
    return stmts


# Names synthesized by the most recent `desugar_genexps` call. Read (and
# cleared) by gimple_codegen's compile choke point, which is the only
# caller; a plain module-level list rather than a return value so the
# desugar keeps the single-argument shape every other AST pass here has.
DESUGARED_GENEXP_NAMES: list = []


def _rebound_names(stmts: list) -> set:
    """Module-level names that are assigned MORE THAN ONCE anywhere in the
    module, or assigned anywhere from inside a function body.

    Only consulted for the outermost iterable of a generator expression: a
    module-level name is read directly by the hoisted generator function
    (no parameter, so no type is lost), but the hoisted function's loop
    runs on the generator's FIRST RESUME — so the name must be guaranteed
    to hold the same object then as it did when the expression was written.
    A single module-level assignment is that initialization (`DATA = [...]`
    at the top of the file), which is fine; anything beyond it could
    differ."""
    counts: dict = {}
    inside_fn: set = set()

    def _count(node, in_fn):
        if node is None:
            return
        if isinstance(node, list):
            for item in node:
                _count(item, in_fn)
            return
        if isinstance(node, FunctionDef):
            in_fn = True
        if isinstance(node, (AssignStmt, VarDecl, AugAssignStmt,
                             MultiAssignStmt, ForStmt)):
            names: set = set()
            _collect_assigned_names(node, names, True)
            for n in names:
                if in_fn:
                    inside_fn.add(n)
                else:
                    counts[n] = counts.get(n, 0) + 1
        if isinstance(node, Comprehension):
            return
        if dataclasses.is_dataclass(node):
            for f in dataclasses.fields(node):
                _count(getattr(node, f.name), in_fn)

    _count(stmts, False)
    out = set(inside_fn)
    for n, c in counts.items():
        if c > 1:
            out.add(n)
    return out


def _module_level_names(stmts: list) -> set:
    """Every name bound at module level — the ones a generator expression
    can read WITHOUT capturing them, since a hoisted module-level function
    can see them directly."""
    names: set = set()
    for s in stmts:
        if isinstance(s, (FunctionDef, StructDef, TraitDef)):
            names.add(s.name)
        elif isinstance(s, VarDecl):
            _target_names(s.name, names)
        elif isinstance(s, AssignStmt):
            _target_names(s.target, names)
        elif isinstance(s, MultiAssignStmt):
            for t in s.targets:
                _target_names(t, names)
        elif isinstance(s, ImportStmt):
            # `_as_str`: on the self-hosted compiled path these fields are
            # boxed `char *` handles, not Python strs, so `.split`/truth
            # tests must go through the file's own narrowing helper (same
            # convention as every other reader of ImportStmt in the
            # compiled pipeline).
            alias = _as_str(s.alias) if s.alias is not None else ''
            if alias:
                names.add(alias)
            else:
                names.add(_as_str(s.module).split('.')[0])
            for extra_module, extra_alias in (s.extra or []):
                extra_alias = _as_str(extra_alias) if extra_alias is not None else ''
                if extra_alias:
                    names.add(extra_alias)
                else:
                    names.add(_as_str(extra_module).split('.')[0])
        elif isinstance(s, FromImportStmt):
            # `names` holds (name, alias|None) TUPLES as the parser builds
            # them; `name_alias_strs` is the flat "name" / "name as alias"
            # string list the compiled/self-hosted representation carries
            # (see FromImportStmt's own field docs — tuples do not survive
            # self-hosting intact). Accept either shape.
            for entry in s.names:
                if isinstance(entry, tuple):
                    bound = entry[1] or entry[0]
                else:
                    bound = str(entry).split(' as ')[-1].strip()
                if bound:
                    names.add(bound)
            for entry in (getattr(s, 'name_alias_strs', None) or []):
                bound = str(entry).split(' as ')[-1].strip()
                if bound:
                    names.add(bound)
    return names


def _as_ident_node(e: object) -> IdentExpr:
    """Static narrowing view of a boxed AST-side expression handle.

    The compiled backend refines neither chained expressions nor plain
    locals through isinstance() — after `isinstance(_s.value, IdentExpr)`
    passes, a subsequent `_s.value.name` still lowers to a
    `_mojo_dispatch_getattr` call whose boxed int64_t result is then
    mis-coerced at the use site (observed: `mojo_str_from_int` of the raw
    pointer before `mojo_dict_get_str`, and `(char)` truncation in `==`
    comparisons), so every lookup missed and whole parser passes silently
    no-op'd under stage2/mojo while working identically under CPython.
    Call sites guard with isinstance() first (runtime-accurate via type
    tags), then route the value through this annotated identity function
    so subsequent attribute reads compile to direct struct field loads."""
    return e


def _as_funcdef_node(e: object) -> FunctionDef:
    """See _as_ident_node: static FunctionDef view of a boxed handle."""
    return e


def _as_structdef_node(e: object) -> StructDef:
    """See _as_ident_node: static StructDef view of a boxed handle, so a
    following `.bases` / `.fields` / `.methods` / `.name` read compiles to a
    direct struct field load rather than a `_mojo_dispatch_getattr` on an
    int64_t. Needed by `_merge_struct_inheritance` (Python-style class
    inheritance): its `for s in all_struct_defs` loop var was boxed, so
    `s.bases` erased and the whole inheritance merge silently no-op'd on the
    self-hosted compiled path — every `class Child(Base):` lost its
    inherited fields/methods (ArcPointer's `_value`, and ~thousands of
    stage1-vs-stage2 `.ci` divergences under MOJO_NO_SHIM=1)."""
    return e


def _as_member_node(e: object) -> MemberExpr:
    """See _as_ident_node: static MemberExpr view of a boxed handle, so a
    following `.obj` / `.member` read compiles to a direct field load rather
    than a `_mojo_dispatch_getattr` on an int64_t."""
    return e


def _as_intlit_node(e: object) -> IntLiteral:
    """See _as_ident_node: static IntLiteral view of a boxed handle, so a
    following `.value` / `.raw` read compiles to a direct field load. Needed
    where a module-global static initializer is extracted from an
    already-isinstance-checked RHS (`x = 42` -> `.x = 0` instead of
    `.x = 42` under MOJO_NO_SHIM=1, because `.value` went through
    `_mojo_dispatch_getattr` and came back 0)."""
    return e


def _as_boollit_node(e: object) -> BoolLiteral:
    """See _as_intlit_node — static BoolLiteral view for a following
    `.value` read."""
    return e


def _as_floatlit_node(e: object) -> FloatLiteral:
    """See _as_intlit_node: static FloatLiteral view of a boxed handle, so a
    following `.value` read compiles to a direct `double` field load rather
    than a `_mojo_dispatch_getattr` that TRUNCATES the double to the boxed
    int64_t. Needed by `_lower_FloatLiteral`'s `repr(node.value)`: a
    reflective read gave `repr(4.2)` == `'4.0'` self-hosted (the fraction was
    lost), which then emitted `4.0`/`0.0`/`1.0` for source literals
    `4.2`/`0.1`/`1.5`."""
    return e


def _as_assignstmt_node(e: object) -> AssignStmt:
    """See _as_ident_node: static AssignStmt view of a boxed handle."""
    return e


def _as_vardecl_node(e: object) -> VarDecl:
    """See _as_ident_node: static VarDecl view of a boxed handle."""
    return e


def _as_callexpr_node(e: object) -> CallExpr:
    """See _as_ident_node: static CallExpr view of a boxed handle, so a
    following `.func` / `.args` / `.kwargs` read compiles to a DIRECT struct
    field load rather than a `_mojo_dispatch_getattr` on the boxed node.
    Load-bearing for `.kwargs`: the per-type reflection dispatch
    (`_mojo_dispatch_getattr`) does not reliably carry a `CallExpr` case in
    every compiled module (see bugs/CODEGEN_noshim_dumpfull_preexisting_
    divergence.md continuation 7), so a reflective `node.kwargs` read comes
    back as the miss sentinel 1 and a later `len(node.kwargs)` SIGSEGVs in
    `mojo_list_len(0x1)`. A direct field read is immune."""
    return e


def _as_multiassignstmt_node(e: object) -> MultiAssignStmt:
    """See _as_ident_node: static MultiAssignStmt view of a boxed handle."""
    return e


def _as_comptimevar_node(e: object) -> ComptimeVarStmt:
    """See _as_ident_node: static ComptimeVarStmt view of a boxed handle, so a
    following `.target` read compiles to a direct `char *` field load.
    Needed by `_parse_struct`'s `comptime_aliases` map: read straight off a
    boxed loop var, `s.target` lowered through runtime dispatch and its
    int64_t result was stored via `mojo_str_from_int`, so every alias key
    became the pointer's decimal ADDRESS instead of the alias name."""
    return e


def _sms_key(struct_name: object, method: object) -> str:
    """Composite string key for `_struct_method_signatures`.

    That map used to be keyed by the 2-tuple `(struct_name, method)`. In
    CPython a tuple hashes by CONTENTS; self-hosted, a tuple lowers to a
    MojoList and the dict coerces the key to that list's ADDRESS. Storing
    and looking up therefore used two different fresh tuples' addresses,
    so lookups normally missed outright — and, worse, could spuriously HIT
    when the allocator handed a fresh tuple the address of a freed one.

    That spurious hit is not hypothetical: it made `_lower_MemberExpr`
    believe `PassStmt.targets` was a METHOD, emit a bound-method value for
    it, and degrade `for _tgt in _s.targets:` to `mojo_unsupported_iter` —
    silently dropping the whole loop body. Whether it happened depended on
    heap addresses, so the SAME binary produced different output for the
    same input on consecutive runs.

    A string key hashes by content on both paths.
    """
    return _pair_key(struct_name, method)


def _pair_key(a: object, b: object) -> str:
    """Content-hashed composite key for a dict that would otherwise be keyed
    by the 2-tuple `(a, b)`. See `_sms_key` for the full rationale — in short,
    a tuple key hashes by CONTENTS under CPython but by the tuple's heap
    ADDRESS once self-hosted, so stores and lookups miss (or spuriously hit a
    reused address), which makes the compiled compiler's output depend on the
    allocator and differ run to run.
    """
    # None-safe: `_as_str` is a CPython identity function, so `_as_str(None)`
    # is None and a bare concatenation would raise. Several call sites test
    # membership for a key whose first half is not resolved yet.
    _a = a if a is not None else ''
    _b = b if b is not None else ''
    # `\x00` separator, matching `_sms_key`'s long-standing form. On the
    # compiled path `mojo_str_cat` is `strlen`-based so the NUL collapses and
    # the key is a bare `a+b` concat — still a stable content key as long as
    # every store and lookup goes through here (they do). A caller that needs
    # to SPLIT the halves back out on the self-hosted path must use its own
    # non-NUL separator instead (see `gimple_gen_infra._FC_SEP`).
    return _as_str(_a) + '\x00' + _as_str(_b)


def _as_str(e: object) -> str:
    """See _as_ident_node: static `str` view of a value the compiled
    backend erased to int64_t (e.g. a loop variable over
    `sorted(a_set_of_str)` whose element type the seeder could not fill
    in in time). CPython identity; the `-> str` annotation is the point."""
    return e


def _as_set(e: object) -> set:
    """`MojoSet *` view of a value the compiled backend erased to int64_t
    (e.g. a `set` slot round-tripped through a returned tuple / a
    dict-of-mixed-value-types). CPython identity; the annotation is the point."""
    return e


def _as_list(e: object) -> list:
    """`MojoList *` view — the list sibling of `_as_set`/`_as_str`."""
    return e


def _as_dict(e: object) -> dict:
    """`MojoDict *` view of a value the compiled backend erased to int64_t
    (e.g. `self.<dict-field>` where `_lower_MemberExpr` lost the declared
    `dict[...]` ctype). CPython identity."""
    return e


def _ptr_slot_in_range(e: object) -> bool:
    """Guard for a `char *` metadata-dict slot the compiled backend may
    hand back as an erased sentinel (`-1`, a tiny value) after its slot
    type unified to int64_t. CPython: a genuine `str` is always in range.
    Compiled: range-check the raw 64-bit value against the plausible
    userspace-heap window."""
    if isinstance(e, str):
        return True
    _n = _as_int(e)
    return 0x0000000000100000 <= _n <= 0x00007fffffffffff


def _as_int(e: object) -> int:
    """`int64_t` view of a value — the numeric sibling of `_as_str`. Used
    to range-check a pointer-typed slot the compiled backend may hand back
    as an erased sentinel (e.g. a metadata-dict value stored via set_int
    after its slot type was unified to int64_t): in the compiled backend
    this yields the raw 64-bit value; in CPython it is identity, so
    callers must `isinstance(..., int)`-gate any numeric comparison so the
    interpreter path stays unaffected."""
    return e


def method_receiver_kind(m: object) -> str:
    """Which receiver, if any, a struct METHOD's node declares: 'self',
    'cls', or '' (none).

    The single definition of the rule, in the parser that produces the
    nodes, because three independent consumers need to agree on it and
    disagreed before: the A3 stack-switch lowering (`mojo/middle/coro.py`'s
    `_lower_one`), the C++20 coroutine emitter
    (`mojo/backend_gimple/cpp_async.py`'s `_gen_cpp_generator_unit`), and
    the receiver bookkeeping both register on the api entry
    (`mojo/middle/module_shared.py`). Reading only the first parameter's
    NAME is what let a `@staticmethod` through as a receiver-less method
    whose unit was then emitted under the free-function symbol
    `_mojogen_<name>` and registered in the free-function table, so
    `C.gen(...)` was never recognised as a generator call at all.

    Decorator first, because it is the only thing that says whether the
    first parameter is a receiver AT ALL; the parameter name is the
    fallback for the undecorated (ordinary instance method) case. A
    `@staticmethod` is receiver-less even if its first parameter is
    unusually named `self`. A method with no decorator whose first
    parameter is neither `self` nor `cls` is genuinely ambiguous and is
    reported as receiver-less, which is what the name-only rule always did.

    Plain loops, no comprehension: this file is itself compiled by the
    self-hosted path, where a comprehension's tuple-unpacked element can
    erase to int64_t.
    """
    _decs = getattr(m, 'decorators', None) or []
    _has_cls = False
    _has_static = False
    for _d in _decs:
        _ds = _as_str(_d)
        if _ds == 'classmethod':
            _has_cls = True
        elif _ds == 'staticmethod':
            _has_static = True
    if _has_cls:
        return 'cls'
    if _has_static:
        return ''
    try:
        _ps = getattr(m, 'params', None) or []
        if not _ps:
            return ''
        _first = _as_str(_ps[0][0])
    except Exception:
        return ''
    if _first == 'self' or _first == 'cls':
        return _first
    return ''


# ---------------------------------------------------------------------------
# Argument/ownership CONVENTIONS: the vocabulary, in one place.
# ---------------------------------------------------------------------------
# `_CONV_CANON` collapses SPELLINGS of one convention onto one spelling
# (the old-style `inout`/`borrowed` and the new-style `mut`/`read` are
# semantically identical; a parameter-position `var` means the same as
# `owned`). Storing the canonical form in `param_convs` means every later
# consumer checks one spelling instead of tracking every historical name
# everywhere -- see doc/OWNERSHIP_MODEL.md's Phase 0.
_CONV_CANON = {'inout': 'mut', 'borrowed': 'read', 'var': 'owned'}

# ---------------------------------------------------------------------------
# What each convention MEANS, for the consumers that reason about it.
# ---------------------------------------------------------------------------
# `_CONV_CANON` above collapses SPELLINGS of one convention onto one spelling;
# these three sets are the other direction — they say which conventions share a
# PROPERTY, so a consumer asks "is this an exclusive borrow?" instead of
# hardcoding a subset of names.
#
# They exist because the set of spellings grew past what any single consumer
# tracked. `read`, `ref` and `imm` all mean "borrows immutably", and each was
# recognised separately: `ownership_check.py` tested `c == 'mut'` and so let an
# `imm` parameter through as "not mutable" only by accident of not matching,
# while `funcs_shared._param_ctype` carried its own literal `('read', 'ref')`
# tuple. Adding `imm` to the language would have silently widened that gap. One
# table, asked two ways, cannot drift that way.
#
# Module-level frozensets reached through module-level FUNCTIONS, not class
# attributes: a class-attribute dict read erases to int64_t on the self-hosted
# path (see `_canon_conv`'s own note), which would turn these lookups into
# truthy garbage rather than failing loudly.
_CONV_READ_ONLY = frozenset({'read', 'ref', 'imm'})
# Exclusive/mutable borrows: the callee may write through them, so two of them
# aliasing one binding in a single call is a conflict (ownership_check Phase 2).
_CONV_EXCLUSIVE = frozenset({'mut', 'out'})
# Ownership transfer: the callee takes the value outright.
_CONV_TRANSFER = frozenset({'owned'})


def conv_is_read_only(conv) -> bool:
    """True if `conv` is an immutable borrow (`read`, `ref`, `imm`).

    An unannotated parameter is NOT read-only: callers must opt in by writing
    the convention, so an absent convention has to read as "unknown" and fail
    the safe way. Pass the raw value; None and '' are both unknown.
    """
    return bool(conv) and conv in _CONV_READ_ONLY


def conv_is_exclusive(conv) -> bool:
    """True if `conv` is a mutable/exclusive borrow (`mut`, `out`)."""
    return bool(conv) and conv in _CONV_EXCLUSIVE


def conv_is_transfer(conv) -> bool:
    """True if `conv` transfers ownership (`owned`)."""
    return bool(conv) and conv in _CONV_TRANSFER


# ── Code generator ─────────────────────────────────────────────────




def _canon_conv(conv: str):
    # `cls._CONV_CANON.get(conv, conv)` was the original form: a
    # CLASS-attribute dict read erases to int64_t on the self-hosted
    # path, so the following `dict.get(...)` fell to the scalar-receiver
    # stub and returned 0 for EVERY convention — the single largest .ast
    # divergence class (`param_convs={'x': None}` vs the reference's
    # `'mut'`/`'read'`/`'owned'`).
    #
    # Explicit `==` comparisons alone are NOT enough: `conv` arrives
    # BOXED (its callers pass `_as_str(self._advance().value)` through a
    # local, and the two-argument classmethod erases it) — a boxed
    # int64_t compared against a `char *` string literal is the
    # constant-FALSE static guard, so `conv == 'inout'` was always
    # False and the function fell through to `return conv`, whose own
    # boxed return then rendered as `''` in `param_convs`. Re-view the
    # argument with `_as_str` INSIDE this one place so every comparison
    # and the returned value are real `char *`.
    # A SEPARATE local name (`_cv`), not `conv = _as_str(conv)` + reuse:
    # the codegen re-read the PARAMETER `conv` (erased int64_t) in every
    # comparison below even after the reassignment (`_t5 = (int64_t)conv;
    # _t6 = (char*)conv; mojo_cstr_cmp(_t6, ...)` in the emitted .ci), so
    # `conv == 'inout'` was still the constant-FALSE static guard. A
    # fresh local that is only ever written from `_as_str(...)` keeps the
    # real `char *` type through every use.
    _cv = _as_str(conv)
    if _cv == 'inout':
        return 'mut'
    if _cv == 'borrowed':
        return 'read'
    if _cv == 'var':
        return 'owned'
    return _cv
# ── Code generator ─────────────────────────────────────────────────


class Parser:
    def __init__(self, tokens: list[Token]):
        self._tok = tokens
        self._pos = 0
        self._filename = ""
        self._pending_decs = []  # decorators awaiting next struct/trait
        # `comptime NAME = <rhs>` the parser could not parse, as
        # `[(loc, text, exception_text), ...]`. A comptime right-hand side has
        # two very different fates that used to be INDISTINGUISHABLE: a
        # function type (`comptime F = def[T](Int) -> None`) is deliberately
        # not modelled and becomes `IdentExpr('_comptime_expr')`, while a
        # bracket call that failed to parse became the SAME placeholder —
        # because `_skip_comptime_rhs`'s bare `except:` turned the ParseError
        # into a skip-to-newline. So "not implemented" and "misparsed" were
        # the same value, every consumer read the alias as a placeholder, and
        # nothing said which. `std/io/file.mojo`'s `O_APPEND` was the visible
        # damage: a `comptime` integer constant that reached `open(2)`'s flags
        # as a placeholder (see
        # bugs/CODEGEN_comptime_function_type_alias_is_erased_by_the_parser.md).
        #
        # A `ParseError` is now recorded here and re-raised as a SyntaxError
        # with its own message, so the source line is refused instead of
        # compiling to a wrong value. The function-type skip is NOT recorded
        # and NOT raised — it is the deliberate case, and its placeholder is
        # still what part 3 of that doc has to replace.
        self._comptime_rhs_failures: list = []
        # `struct Box[T: Movable]:` — a generic TYPE parameter bound by a
        # trait, syntactically identical to `struct SIMD[width: Int]:`'s
        # genuine comptime VALUE parameter (`name: Ident` either way). This
        # parser has no type checker, so the only way to tell them apart is
        # to know whether the name after the colon is a trait; a single
        # forward scan of this file's own tokens for `trait NAME` finds every
        # user-defined trait (traits are declared before use in this dialect,
        # same assumption structs/functions already rely on), unioned with
        # the built-in stdlib traits above that never appear as a `trait`
        # declaration in user source. See _parse_struct_params_as_fields,
        # which used to add every `T: Movable` as a real VarDecl field —
        # corrupting @fieldwise_init's synthesized constructor arity for any
        # generic struct with a trait-bounded type parameter.
        self._known_traits = set(_BUILTIN_TRAITS)
        for i, t in enumerate(tokens):
            if t.kind == "KW" and t.value == "trait" and i + 1 < len(tokens):
                nxt = tokens[i + 1]
                if nxt.kind == "NAME":
                    self._known_traits.add(nxt.value)


    def _parse_funcdef(self, decorators=None, is_async=False):
        if decorators is None: decorators = []
        # Allow keywords, backtick identifiers as function names (e.g., def read(...), def `6bit`(...))
        t = self._peek()
        if t.kind == "NAME":
            name = self._advance().value
        elif t.kind == "KW":
            name = self._advance().value
        elif t.kind == "STRING" and t.value.startswith("`"):
            name = self._advance().value  # backtick identifier
        else:
            raise SyntaxError(f"{self._loc(t)}Expected NAME or KW got {t.kind}({t.value!r})")
        # Generic type-param block [T: Trait, count: Int, //] — capture the
        # names (see _parse_generic_params_capture) so the interpreter can
        # bind `f[Int32]()`'s subscript to them by position.
        comptime_params = []
        comptime_param_defaults = {}
        comptime_param_annotations = {}
        if self._peek().kind == "LBRACKET":
            (comptime_params, comptime_param_defaults,
             comptime_param_annotations) = self._parse_generic_params_capture()
        self._expect("LPAREN")
        params = []
        param_convs = {}
        param_has_default = {}
        param_defaults = {}
        kwonly = []
        seen_bare_star = False
        while self._peek().kind != "RPAREN":
            # Skip newlines and indentation within parameter list
            while self._peek().kind in ("NEWLINE", "INDENT", "DEDENT"):
                self._advance()
            if self._peek().kind == "RPAREN": break
            # Capture last argument-convention prefix (read/mut/var/ref/out/deinit)
            # Disambiguation: KW followed by COLON/ASSIGN/COMMA/RPAREN is a param name, not a convention
            conv = None
            while self._peek().kind == "KW" and self._peek().value in self._CONV_KWS:
                if self._peek(1).kind in ("COLON", "ASSIGN", "COMMA", "RPAREN"):
                    break
                # `conv` is captured across the rest of the param loop
                # and used much later (param_convs[pname]=...), by which
                # point a bare `.value` read lost its char* (emptied to '');
                # pin the str view at capture.
                conv = _as_str(self._advance().value)
            # Skip positional-only parameter separator /
            if self._peek().kind == "OP" and self._peek().value == "/":
                self._advance()
                if self._peek().kind == "COMMA": self._advance()
                if self._peek().kind == "RPAREN": break
            # Handle ** (keyword variadic parameter: **kwargs)
            if self._peek().kind == "OP" and self._peek().value == "**":
                self._advance()
                t = self._peek()
                if t.kind in ("NAME", "KW"):
                    pname = self._advance().value
                    ptype = None
                    if self._peek().kind == "COLON":
                        self._advance(); ptype = self._parse_type_ann()
                    params.append(("**" + pname, ptype))
                    if conv is not None: param_convs[pname] = _as_str(_canon_conv(conv))
                    if self._peek().kind == "COMMA": self._advance()
                    while self._peek().kind in ("NEWLINE", "INDENT", "DEDENT"):
                        self._advance()
                    continue
            # Handle * (keyword-only separator or variadic parameter)
            if self._peek().kind == "OP" and self._peek().value == "*":
                self._advance()
                # Skip lifetime parameters if present after *
                if self._peek().kind == "LBRACKET": self._skip_bracketed()
                # An optional convention keyword may follow the `*`
                # (`*, var x: Int`). Captured early, used later — pin the
                # str view at capture (a bare `.value` read lost its char*).
                conv = None
                while self._peek().kind == "KW" and self._peek().value in self._CONV_KWS:
                    if self._peek(1).kind in ("COLON", "ASSIGN", "COMMA", "RPAREN"):
                        break
                    conv = _as_str(self._advance().value)
                # After the optional convention keyword: a NAME/KW is either a
                # VARIADIC parameter (`*args` -> packed into one MojoList*) or
                # a keyword-only param (`*, x`); the variadic form is
                # distinguished by `conv is None` (a convention keyword can
                # only precede a keyword-only param, never a `*args`). An
                # ASSIGN on the variadic form is impossible in Python syntax.
                #
                # This branch used to sit INSIDE the `while _CONV_KWS` loop
                # body, so a BARE `*args` (no convention keyword) never
                # reached it: the `while` was never entered, the `*` was
                # consumed as a separator, and `args` was left to be read as
                # the NEXT parameter name — which for `def _git(*args):` is
                # `RPAREN`, ending the loop with `params == []`. The closure
                # then emitted as `(<void>)` while every call site still
                # passed the loose args ("too many arguments to function
                # 'version__git'; expected 0, have 3"). See version.py's own
                # nested `def _git(*args)`.
                t = self._peek()
                if t.kind in ("NAME", "KW"):
                    pname = self._advance().value
                    ptype = None
                    if self._peek().kind == "COLON":
                        self._advance(); ptype = self._parse_type_ann()
                    if conv is None:
                        # `*args` — the variadic parameter
                        if self._peek().kind == "ASSIGN":
                            self._advance()
                            default_expr = self._parse_expr(0)
                            param_has_default[pname] = True
                            param_defaults[pname] = default_expr
                        params.append(("*" + pname, ptype))
                        if self._peek().kind == "COMMA": self._advance()
                        while self._peek().kind in ("NEWLINE", "INDENT", "DEDENT"):
                            self._advance()
                        continue
                    # keyword-only param after a bare star (`*, var x`)
                    if self._peek().kind == "ASSIGN":
                        self._advance()
                        default_expr = self._parse_expr(0)
                        param_has_default[pname] = True
                        param_defaults[pname] = default_expr
                    params.append((pname, ptype))
                    param_convs[pname] = _as_str(_canon_conv(conv))
                    if seen_bare_star: kwonly.append(pname)
                    if self._peek().kind == "COMMA": self._advance()
                    while self._peek().kind in ("NEWLINE", "INDENT", "DEDENT"):
                        self._advance()
                    continue
                # Otherwise it's a separator: skip following comma and check for end
                if self._peek().kind == "COMMA": self._advance()
                seen_bare_star = True
                if self._peek().kind == "RPAREN": break
                # Continue to next parameter (convention keywords might follow)
                continue
            if self._peek().kind == "RPAREN": break
            # Skip lifetime parameters in brackets: ref[origin] param_name
            if self._peek().kind == "LBRACKET": self._skip_bracketed()
            # Allow KW tokens as parameter names (e.g., "if", "out")
            t = self._peek()
            if t.kind == "NAME": pname = self._advance().value
            elif t.kind == "KW": pname = self._advance().value
            else: raise SyntaxError(f"{self._loc(t)}Expected NAME or KW got {t.kind}({t.value!r})")
            ptype = None
            if self._peek().kind == "COLON":
                self._advance(); ptype = self._parse_type_ann()
            # Default value =expr: parsed and stored for the interpreter to use
            # when the argument is omitted.
            if self._peek().kind == "ASSIGN":
                self._advance()
                default_expr = self._parse_expr(0)
                param_has_default[pname] = True
                param_defaults[pname] = default_expr
            params.append((pname, ptype))
            if conv is not None: param_convs[pname] = _as_str(_canon_conv(conv))
            if seen_bare_star: kwonly.append(pname)
            # Skip trailing comma and newlines
            if self._peek().kind == "COMMA": self._advance()
            while self._peek().kind in ("NEWLINE", "INDENT", "DEDENT"):
                self._advance()
        self._expect("RPAREN")
        # Skip optional `raises` keyword and exception types (must come before return type)
        if self._is_kw("raises"):
            self._advance()  # skip raises
            # Skip exception type list: Type1, Type2, ... until we see -> or : or where
            while self._peek().kind not in ("COLON", "NEWLINE", "EOF", "ARROW"):
                # Stop at 'where' keyword to allow the where-clause handler below
                if self._peek().kind == "NAME" and self._peek().value == "where": break
                if self._peek().kind in ("NAME", "DOT", "STRING", "COMMA"):
                    self._advance()
                elif self._peek().kind == "LBRACKET":
                    self._skip_bracketed()  # Skip subscripted exception types like ExcType[Param]
                else:
                    break
        # Skip function qualifiers (unified, register_passable, capturing, raises,
        # calling-convention markers thin/abi("C"), etc.)
        # ('raises' lexes as a keyword, the rest as names.)
        while self._peek().kind in ("NAME", "KW") and self._peek().value in ("unified", "register_passable", "capturing", "raises", "thin", "abi"):
            self._advance()
            # abi may take a parenthesized convention string: abi("C")
            if self._peek().kind == "LPAREN":
                self._advance()  # consume LPAREN
                depth = 1
                while depth > 0:
                    t = self._advance()
                    if t.kind == "LPAREN":
                        depth += 1
                    elif t.kind == "RPAREN":
                        depth -= 1
                    elif t.kind == "EOF": break
        ret = None
        if self._peek().kind == "ARROW":
            self._advance()
            # Drop `ref` lifetime prefix on return type and skip lifetime parameters
            if self._is_kw("ref"):
                self._advance()
                # Skip lifetime parameters in brackets: ref[Origin]
                if self._peek().kind == "LBRACKET":
                    self._skip_bracketed()
            ret = self._parse_type_ann()
            # Skip additional qualifiers after return type
            while self._peek().kind == "NAME" and self._peek().value in ("unified", "register_passable", "capturing", "raises"):
                self._advance()
        # Skip optional `where conforms_to(...)` clause
        if self._peek().kind == "NAME" and self._peek().value == "where":
            self._advance()  # where
            while self._peek().kind not in ("COLON", "NEWLINE", "EOF"):
                self._advance()
        # Capture list in curly braces: `def handler(...) {mut count, var s}:`
        #
        # This used to be skipped token by token, which made the list
        # unrecoverable — the closure analysis then had to GUESS the captures
        # from which names the body reads minus which it declares, and the
        # guess is wrong in both directions for exactly the shapes the list
        # exists to state:
        #
        #   * a name the body only AUGMENTS (`got_sum += x`) is invisible to
        #     the read-based scan, so it was not captured at all and the
        #     lifted function referenced it undeclared — a hard "got_sum
        #     undeclared" (test/builtin/test_tuple.mojo);
        #   * a name the body ASSIGNS (`got_str = ...`) was taken for a local
        #     of the inner function rather than a capture of the enclosing
        #     one, so the write landed in a local and the enclosing
        #     `assert_equal(got_str, "hello")` read back a zero.
        #
        # Parsed, not skipped: the list is the authoritative statement of what
        # the inner function borrows, and `discover_closures` reads it. An
        # ABSENT list still falls back to the read-based inference, so every
        # closure written without one behaves exactly as before.
        captures = []
        has_capture_list = False
        if self._peek().kind == "LBRACE":
            captures = self._parse_capture_list()
            has_capture_list = True
        # Return type may appear after the capture list
        if ret is None and self._peek().kind == "ARROW":
            self._advance()
            if self._is_kw("ref"):
                self._advance()
                if self._peek().kind == "LBRACKET":
                    self._skip_bracketed()
            ret = self._parse_type_ann()
        self._expect("COLON")
        body = self._parse_block()
        is_generator, yield_bearing_node_ids = _detect_generator(body)
        return FunctionDef(name=name, params=params, return_type=ret,
                           body=body, decorators=decorators,
                           param_convs=param_convs,
                           param_has_default=param_has_default,
                           param_defaults=param_defaults,
                           kwonly=kwonly,
                           comptime_params=comptime_params,
                           comptime_param_defaults=comptime_param_defaults,
                           comptime_param_annotations=comptime_param_annotations,
                           is_generator=is_generator,
                           yield_bearing_node_ids=yield_bearing_node_ids,
                           is_async=is_async,
                           captures=captures,
                           has_capture_list=has_capture_list)

    def _parse_capture_list(self):
        """A brace-delimited CAPTURE list on a nested `def`:
        `def handler(...) {mut count, var s}:`, LBRACE current.

        Returns `(name, conv_or_None)` pairs in source order, where `conv` is the
        canonical convention the capture is taken under — `mut` for a capture
        the body may write, `var`/`owned` for one it takes by value, `imm`/
        `read`/`ref` for a read-only borrow. A bare name (`{self_ptr}`) has
        conv None: captured, convention unspecified.

        An EMPTY list `{}` is a real and meaningful list — it says "captures
        nothing" — and is returned as `[]`, which the consumer distinguishes
        from "no list at all" by the list being absent, not by being empty.
        """
        self._expect("LBRACE")
        out = []
        self._skip_newlines()
        while self._peek().kind not in ("RBRACE", "EOF"):
            if self._peek().kind == "COMMA":
                self._advance(); self._skip_newlines(); continue
            # A convention prefix may precede the captured name (`mut count`)
            # or stand alone (`{mut}`, meaning "captures, mutably, whatever the
            # body references" — 42 occurrences in the stdlib, so it is a form
            # with its own meaning and not a typo for a missing name).
            conv = None
            # A KW from the convention set at the START of an entry is always a
            # prefix, never the captured name — the same disambiguation the
            # parameter loop uses (KW followed by COLON/ASSIGN is a name), with
            # one addition: `peek(1) in (COMMA, RBRACE)` does NOT make it a
            # name here, because `{mut}` and `{var}` are the bare-convention
            # form ("capture whatever this body references, under this
            # convention"). Requiring a non-terminating `peek(1)` instead made
            # `{mut}` parse as a capture of a variable named `mut`.
            while (self._peek().kind == "KW"
                   and self._peek().value in self._CONV_KWS
                   and self._peek(1).kind not in ("COLON", "ASSIGN")):
                conv = _as_str(self._advance().value)
            if self._peek().kind in ("COMMA", "RBRACE"):
                # `{mut}` / `{var}` — a convention with NO name: "capture
                # whatever this body references, under this convention" (42
                # `{mut}` and 4 `{var}` in the stdlib). Recorded with a None
                # name so it cannot be confused with a capture of a variable
                # that happens to be called `mut`, and so the consumer can
                # tell "infer the names, this is the convention" from an
                # ordinary named capture.
                out.append((None, _as_str(_canon_conv(conv))
                            if conv is not None else None))
                self._skip_newlines()
                if self._peek().kind == "COMMA":
                    self._advance(); self._skip_newlines()
                continue
            if self._peek().kind not in ("NAME", "KW"):
                t = self._peek()
                raise SyntaxError(
                    f"{self._loc(t)}Unexpected {t.kind}({t.value!r}) in capture "
                    f"list")
            name = self._advance().value
            # A trailing `^` MOVES the value into the closure: `{var data^}`
            # — `data` is owned by the closure for its whole life, which the
            # source comments call out as the reason the form exists (an
            # implicit by-reference capture would not keep it alive). The
            # closure then owns the captured value, so the move is recorded as
            # the `owned` convention, which is what `var` already canonicalises
            # to; an explicit conv on the same entry wins, since the source
            # said so. No information is lost: the two spellings agree on the
            # only thing the capture machinery acts on.
            moved = False
            if (self._peek().kind == "OP" and self._peek().value == "^"):
                self._advance()
                moved = True
            _cc = _as_str(_canon_conv(conv)) if conv is not None else None
            if _cc is None and moved:
                _cc = 'owned'
            out.append((name, _cc))
            self._skip_newlines()
            if self._peek().kind == "COMMA":
                self._advance(); self._skip_newlines()
        self._expect("RBRACE")
        return out

    def _parse_struct(self):
        # Accept both "struct" and "class" keywords
        kw = self._peek()
        if kw.kind == "KW" and kw.value in ("struct", "class"):
            self._advance()
        else:
            self._expect("KW", "struct")
        name = self._ident()
        # Parse struct parameter block [x: Type, y: Type = default, ...] as fields
        param_fields = []
        if self._peek().kind == "LBRACKET":
            param_fields = self._parse_struct_params_as_fields()
        # `struct Child(Base1, Base2):` / `class Child(Base):` — Python-style
        # base-class list. Capture the top-level names (skipping keyword
        # args like `metaclass=X` and trait-bound expressions we can't
        # resolve as a real base) instead of discarding the whole
        # parenthesized list; MojoClass merges the named bases' fields and
        # methods at struct-definition time (see execute_StructDef).
        bases = []
        if self._peek().kind == "LPAREN":
            self._advance()
            depth = 1
            expect_name = True
            while depth > 0:
                t = self._peek()
                if t.kind == "LPAREN":
                    self._advance(); depth += 1; continue
                if t.kind == "RPAREN":
                    self._advance(); depth -= 1; continue
                if t.kind == "EOF":
                    break
                if t.kind == "COMMA" and depth == 1:
                    self._advance(); expect_name = True; continue
                if depth == 1 and expect_name and t.kind == "NAME":
                    nxt = self._peek(1)
                    is_kwarg = nxt.kind in ("ASSIGN", "EQUAL") or (
                        nxt.kind == "OP" and nxt.value == "=")
                    if is_kwarg:
                        self._advance()
                        expect_name = False
                        continue
                    # A dotted base (`class Foo(module.Bar):`) — walk the
                    # chain and keep the TRAILING name (the actual class),
                    # not just the leading module-name token. Capturing
                    # only the leading token made EVERY dotted base look
                    # unresolvable downstream (gimple_codegen.py's
                    # _structs_with_unresolved_base checks each captured
                    # base name against this compile's own known
                    # StructDefs — "module" is never one, even when the
                    # real class "module.Bar" genuinely is, e.g.
                    # `class _Dialog(commondialog.Dialog):` in
                    # tkinter/filedialog.py, whose Dialog IS a real,
                    # compiled struct from the imported commondialog
                    # module) — see COMPILE_FAIL_tkinter_filedialog.
                    last_name = t.value
                    self._advance()
                    while self._peek().kind == "DOT" and self._peek(1).kind == "NAME":
                        self._advance()  # consume DOT
                        last_name = self._peek().value
                        self._advance()  # consume NAME
                    bases.append(last_name)
                    expect_name = False
                    continue
                self._advance()
        # Optional `where conforms_to(...)` clause after the base list, the
        # struct-level counterpart of the one `_parse_funcdef` already skips
        # after a parameter list:
        #     struct Iter[...](Iterable where conforms_to(...), ...) \
        #         where conforms_to(T.Element, Deinitable):
        # The bases are consumed as a token soup above, so the clause lands
        # here. It constrains conformance and carries no codegen meaning in
        # this backend, so it is skipped to the colon — the same treatment
        # `_parse_funcdef`'s own `where` skip gets.
        if self._peek().kind == "NAME" and self._peek().value == "where":
            self._advance()
            while self._peek().kind not in ("COLON", "NEWLINE", "EOF"):
                self._advance()
        self._expect("COLON")
        body = self._parse_block()
        fields  = param_fields + [s for s in body if isinstance(s, (VarDecl, AssignStmt))]
        methods = [s for s in body if isinstance(s, FunctionDef)]

        # Methods defined inside CLASS-BODY CONDITIONAL blocks were
        # silently dropped here (an `if`/`elif`/`else` statement in a
        # class body is neither a VarDecl/AssignStmt nor a top-level
        # FunctionDef, so the comprehensions above skipped its nested
        # `def`s entirely) — e.g. Lib/test/support/__init__.py's
        # `PythonSymlink`, whose `_platform_specific` exists only as
        # two `if sys.platform == "win32": / else:` branch definitions;
        # `self._platform_specific()` in `__init__` then compiled
        # against a phantom `<Class>__platform_specific` symbol that
        # nothing ever defined ("symbol(s) not found" at link).
        # Hoist every branch-nested `def` into `.methods`. When the
        # SAME name is defined in more than one mutually-exclusive
        # branch (the whole point of the idiom), keep only the LAST —
        # matching real Python's "a later `def` rebinds the attribute"
        # semantics and the conventional guard layout where the final
        # `else:` holds the default implementation.
        seen_method_names = {m.name for m in methods}
        _cond_stack = [s for s in body if isinstance(s, IfStmt)]
        while _cond_stack:
            _c = _cond_stack.pop(0)
            for _bd in ([_c.then_body]
                        + [_eb for _, _eb in getattr(_c, 'elifs', [])]
                        + ([_c.else_body] if _c.else_body else [])):
                for _bs in _bd:
                    if isinstance(_bs, FunctionDef):
                        if _bs.name in seen_method_names:
                            methods = [m for m in methods if m.name != _bs.name]
                        else:
                            seen_method_names.add(_bs.name)
                        methods.append(_bs)
                    elif isinstance(_bs, IfStmt):
                        _cond_stack.append(_bs)
        # A class-body DUNDER-METHOD ALIAS via chained assignment
        # (`__iter__ = __len__ = __getitem__ = __setitem__ = __delitem__
        # = keys = closed`, Lib/shelve.py's `_ClosedDict` idiom — every
        # container-protocol dunder rebound to one shared implementation)
        # parses as a `MultiAssignStmt`, which neither the `fields`
        # comprehension above (VarDecl/AssignStmt only) nor the
        # `methods` one (FunctionDef only) recognizes — it was silently
        # dropped from the StructDef entirely, so e.g. `__setitem__`
        # never reached `_struct_method_signatures`, and codegen's own
        # `obj[key] = v` lowering fell through to "no `__setitem__`
        # method and no backing container field" as if the class had no
        # subscript support at all. Recognized here, narrowly: only when
        # the RHS is a bare name that already resolves to a method
        # defined earlier in this same class body (never a data value),
        # each target name gets registered as its own method — a shallow
        # copy of the referenced method's FunctionDef with `.name`
        # replaced, so it compiles as an ordinary same-body method under
        # the new name (small code duplication, no shared codegen state,
        # same low-risk shape the conditional-def hoisting just above
        # already uses for a different `methods`-population gap).
        # Build the name map with an explicit loop, not a comprehension:
        # `m` inside `{m.name: m for m in methods}` is an unknown-typed list
        # element, so `m.name` lowered through runtime dispatch and its
        # boxed result was mistyped at the use site (see _as_ident_node).
        # `_mf` is statically FunctionDef via the annotated helper, so
        # `.name` is a direct field load on both backends.
        _alias_by_name = {}
        for _m in methods:
            _mf = _as_funcdef_node(_m)
            _alias_by_name[_mf.name] = _m
        for _s in body:
            if not isinstance(_s, MultiAssignStmt):
                continue
            if not isinstance(_s.value, IdentExpr):
                continue
            _ma_value = _as_ident_node(_s.value)
            _src = _alias_by_name.get(_ma_value.name)
            if _src is None:
                continue
            _sf = _as_funcdef_node(_src)
            for _tgt in _s.targets:
                if not isinstance(_tgt, IdentExpr):
                    continue
                _ta = _as_ident_node(_tgt)
                if _ta.name in _alias_by_name:
                    continue
                # dataclasses.replace() lowers to identity in the compiled
                # backend (gimple_gen_methods' documented approximation), so
                # build the renamed shallow copy explicitly. Field-by-field
                # construction produces exactly what replace() would.
                _alias = FunctionDef(
                    name=_ta.name,
                    params=_sf.params,
                    return_type=_sf.return_type,
                    body=_sf.body,
                    decorators=_sf.decorators,
                    param_convs=_sf.param_convs,
                    param_has_default=_sf.param_has_default,
                    param_defaults=_sf.param_defaults,
                    kwonly=_sf.kwonly,
                    comptime_params=_sf.comptime_params,
                    comptime_param_defaults=_sf.comptime_param_defaults,
                    is_generator=_sf.is_generator,
                    yield_bearing_node_ids=_sf.yield_bearing_node_ids,
                    is_async=_sf.is_async,
                    line=_sf.line,
                    col=_sf.col,
                )
                methods.append(_alias)
                _alias_by_name[_ta.name] = _alias
        # Same idiom, single-target form (`__copy__ = copy` /
        # `__iter__ = keys` — Lib/weakref.py's WeakValueDictionary/
        # WeakKeyDictionary; `__call__ = _idfunc` /
        # `__instancecheck__ = __subclasscheck__` — Lib/typing.py;
        # `__del__ = Close` — Lib/subprocess.py's Popen). This parses as
        # a plain `AssignStmt`, so unlike the chained form above it WAS
        # already being captured by the `fields` comprehension — as a
        # bogus data field (a `_class_attrs` global of a made-up ctype,
        # never the real callable), silently shadowing the method
        # dispatch this name actually needs. Recognized the same way:
        # RHS a bare name resolving to an already-known method: register
        # the alias method AND drop the AssignStmt from `fields` (it was
        # never a real field — leaving it there would double-register
        # this name as both a method and a struct field).
        _alias_assigns = []
        for _s in body:
            if not isinstance(_s, AssignStmt):
                continue
            if not (isinstance(_s.target, IdentExpr) and isinstance(_s.value, IdentExpr)):
                continue
            # See the MultiAssign block above: route both handles through
            # the annotated helpers so `.name` compiles to direct field
            # loads instead of mistyped runtime-dispatch results.
            _alias_target = _as_ident_node(_s.target)
            _alias_value = _as_ident_node(_s.value)
            if _alias_target.name in _alias_by_name:
                continue
            _src = _alias_by_name.get(_alias_value.name)
            if _src is None:
                continue
            _sf = _as_funcdef_node(_src)
            # Explicit renamed shallow copy — dataclasses.replace() is an
            # identity approximation in the compiled backend.
            _alias = FunctionDef(
                name=_alias_target.name,
                params=_sf.params,
                return_type=_sf.return_type,
                body=_sf.body,
                decorators=_sf.decorators,
                param_convs=_sf.param_convs,
                param_has_default=_sf.param_has_default,
                param_defaults=_sf.param_defaults,
                kwonly=_sf.kwonly,
                comptime_params=_sf.comptime_params,
                is_generator=_sf.is_generator,
                yield_bearing_node_ids=_sf.yield_bearing_node_ids,
                is_async=_sf.is_async,
                line=_sf.line,
                col=_sf.col,
            )
            methods.append(_alias)
            _alias_by_name[_alias_target.name] = _alias
            _alias_assigns.append(_s)
        if _alias_assigns:
            _alias_assign_ids = {id(f) for f in _alias_assigns}
            fields = [f for f in fields if id(f) not in _alias_assign_ids]
        # Struct-level `comptime NAME = expr` are aliases, not physical fields.
        # Capture them so member access can expand `self.NAME` to its expression
        # (this codegen does not monomorphize, so e.g. _words_size depends on the
        # runtime `size` field).
        # Explicit loop + static narrowing, not a comprehension: `s` inside
        # `{s.target: s.value for s in body ...}` is an unknown-typed list
        # element, so `s.target` lowered through runtime dispatch and its
        # boxed int64_t result was stored as a decimal address key (see
        # _as_comptimevar_node). `_cs` is statically ComptimeVarStmt, so
        # `.target` compiles to a direct `char *` load on both backends.
        aliases = {}
        for _cs in body:
            if not isinstance(_cs, ComptimeVarStmt):
                continue
            _cvnode = _as_comptimevar_node(_cs)
            aliases[_cvnode.target] = _cvnode.value
        decs    = getattr(self, "_pending_decs", [])
        self._pending_decs = []
        return StructDef(name=name, fields=fields, methods=methods, decorators=decs,
                         comptime_aliases=aliases, bases=bases)

    def _parse_enum(self):
        # `enum Name: member1, member2, ...` — not real Mojo syntax (the real
        # Mojo compiler has no `enum` keyword; the language idiom is a
        # `struct` with `comptime NAME = value` aliases, e.g. `MojoTypeKind`
        # in mojolib's own ast_nodes.mojo). This is a deliberate extension:
        # sugar that desugars straight into that same StructDef shape (fields
        # + methods empty, one comptime alias per member, auto-numbered from
        # 0 unless given an explicit `= value`), reusing execute_StructDef's
        # class-registration/comptime_aliases machinery unchanged. Member
        # names are read as raw tokens (NAME or KW) rather than parsed as
        # expressions, since a member is allowed to shadow a keyword (e.g.
        # `class,`/`enum,` as member names, both seen in the wild).
        self._expect("KW", "enum")
        # Read the enum's own name via `_ident()` (NAME/KW/backtick), not a
        # strict NAME-only `_expect`, so an enum can itself be named after
        # another keyword (e.g. `enum struct:`), mirroring the
        # `struct super:` fix for `_parse_struct`'s own name read.
        name = self._ident()
        # Skip an optional Python-style base list: `enum Name(SomeBase):`
        if self._peek().kind == "LPAREN":
            self._advance()
            depth = 1
            while depth > 0:
                t = self._advance()
                if t.kind == "LPAREN": depth += 1
                elif t.kind == "RPAREN": depth -= 1
                elif t.kind == "EOF": break
        self._expect("COLON")
        decs = getattr(self, "_pending_decs", [])
        self._pending_decs = []
        members = []
        if self._peek().kind != "NEWLINE":
            # Inline single-line body: `enum Name: a, b, c`
            while self._peek().kind not in ("NEWLINE", "DEDENT", "EOF"):
                members.append(self._parse_enum_member())
                if self._peek().kind == "COMMA": self._advance()
                else: break
            return self._build_enum_struct(name, members, decs)
        self._expect("NEWLINE")
        self._skip_newlines()
        if self._peek().kind in ("DEDENT", "EOF"):
            return self._build_enum_struct(name, members, decs)
        self._expect("INDENT")
        self._skip_newlines()
        while self._peek().kind not in ("DEDENT", "EOF"):
            members.append(self._parse_enum_member())
            if self._peek().kind == "COMMA": self._advance()
            self._skip_newlines()
        self._expect("DEDENT")
        return self._build_enum_struct(name, members, decs)

    def _parse_enum_member(self):
        # Member name: a bare NAME, or a keyword used as a bare identifier
        # (Mojo doesn't allow that in general, but enum members are
        # deliberately more permissive — see _parse_enum's docstring).
        t = self._advance()
        value = None
        if self._peek().kind == "ASSIGN":
            self._advance()
            value = self._parse_expr()
        return (t.value, value)

    def _build_enum_struct(self, name, members, decs):
        aliases = {}
        next_auto = 0
        for member_name, value_expr in members:
            if value_expr is not None:
                aliases[member_name] = value_expr
                if isinstance(value_expr, IntLiteral):
                    next_auto = value_expr.value + 1
            else:
                aliases[member_name] = IntLiteral(next_auto, raw='')
                next_auto += 1
        return StructDef(name=name, fields=[], methods=[], decorators=decs,
                         comptime_aliases=aliases)

    def _parse_trait(self):
        self._expect("KW", "trait")
        name = self._expect("NAME").value
        # Skip generic type-param block [T: Trait, ...]
        if self._peek().kind == "LBRACKET": self._skip_bracketed()
        if self._peek().kind == "LPAREN":
            self._advance()
            # Skip balanced parentheses in trait list
            depth = 1
            while depth > 0:
                t = self._advance()
                if t.kind == "LPAREN":
                    depth += 1
                elif t.kind == "RPAREN":
                    depth -= 1
                elif t.kind == "EOF":
                    break
        self._expect("COLON")
        body = self._parse_block()
        methods = [s for s in body if isinstance(s, FunctionDef)]
        decs = getattr(self, "_pending_decs", [])
        self._pending_decs = []
        return TraitDef(name=name, methods=methods)

    def _parse_try(self):
        # The `try` keyword's own line, recorded because `TryStmt` is the one
        # statement here whose position nothing downstream could recover: every
        # other node in a body is reached through a statement whose position a
        # diagnostic can name, and a `try` is the statement a refusal about
        # EXCEPTION SCOPES has to name (`formal/build.py::_refuse_try_handlers`,
        # whose message is useless with line 0). Additive — the field already
        # existed with this default, so nothing that reads it changes except
        # from "always 0" to the truth.
        line = self._peek().line
        self._expect("KW", "try"); self._expect("COLON")
        body = self._parse_block()
        handlers = []
        while self._is_kw("except"):
            self._advance()
            # `except*` exception groups (PEP 654): the star is cosmetic for
            # our tag-based dispatch — accept and ignore it.
            if self._peek().kind == "OP" and self._peek().value == "*":
                self._advance()
            exc_type, exc_name = None, None
            if self._peek().kind == "LPAREN":
                # Parenthesized tuple of exception types:
                #   except (ValueError, TypeError):
                # Stored as a list of dotted-name strings; codegen ORs the
                # tag match across every type in the tuple.
                self._advance()
                names = []
                while self._peek().kind != "RPAREN":
                    names.append(self._parse_dotted_name())
                    if self._peek().kind == "COMMA": self._advance()
                    else: break
                self._expect("RPAREN")
                exc_type = names
                if self._is_kw("as"):
                    self._advance(); exc_name = self._ident()
            elif self._peek().kind != "COLON" and not self._is_kw("as"):
                # The common case is a single (possibly dotted) exception
                # type, e.g. `except ValueError:` / `except
                # asyncio.CancelledError:`. Try that fast path first (it's
                # stored as a plain string, which the interpreter's and
                # gimple_codegen's per-type tag dispatch special-case for
                # speed). But real Python's `except` clause actually takes a
                # full *expression* — a bare name is just the common
                # special case of that — evaluated once and checked against
                # the raised exception. So if what follows the dotted name
                # isn't the end of the clause (COLON or `as`), it wasn't a
                # plain dotted name after all (e.g. a function call like
                # `except get_error_types():`) — rewind and reparse it as a
                # general expression, using the same "expr but don't
                # swallow a following `as`" precedence trick _parse_with
                # uses for `with EXPR as alias:`.
                #
                # The dotted-name fast path only makes sense when the type
                # position actually starts with a NAME/KW token; anything
                # else (INT/FLOAT/STRING literals, etc. — not unambiguously
                # "no type here", but not name-shaped either, e.g. a
                # malformed `except 42:`) has no dotted-name shape to try at
                # all, so go straight to the general expression parse.
                if self._peek().kind in ("NAME", "KW"):
                    saved = self._pos
                    name = self._parse_dotted_name()
                    if self._peek().kind == "COLON" or self._is_kw("as"):
                        exc_type = name
                    elif self._peek().kind == "COMMA":
                        exc_type = name
                        self._advance()
                        exc_name = self._ident()
                    else:
                        self._pos = saved
                        exc_type = self._parse_expr(_KW_PREC['as'] + 1)
                else:
                    exc_type = self._parse_expr(_KW_PREC['as'] + 1)
                if self._is_kw("as"):
                    self._advance(); exc_name = self._ident()
                elif self._peek().kind == "COMMA":
                    self._advance()
                    exc_name = self._ident()
            self._expect("COLON")
            handlers.append(ExceptHandler(exc_type=exc_type, name=exc_name,
                                           body=self._parse_block()))
        else_body = None
        if self._is_kw("else"):
            self._advance(); self._expect("COLON"); else_body = self._parse_block()
        finally_body = None
        if self._is_kw("finally"):
            self._advance(); self._expect("COLON"); finally_body = self._parse_block()
        return TryStmt(body=body, handlers=handlers,
                       else_body=else_body, finally_body=finally_body,
                       line=line)

    def _parse_with(self):
        self._expect("KW", "with")
        items = []
        # `as` in a with-item's own `expr as alias` clause is NOT the binary
        # cast operator (_KW_PREC['as']) — parse at one above its precedence
        # so the operator loop stops before swallowing the alias as a
        # BinaryOp(op='as', ...) right-hand side.
        with_expr_prec = _KW_PREC['as'] + 1
        expr = self._parse_expr(with_expr_prec)
        alias = None
        if self._is_kw("as"):
            # alias may be a bare NAME (the common case) or a parenthesized
            # tuple-unpacking target, `with EXPR as (a, b):` — real Python
            # requires the parens here (unlike a for-target), since a bare
            # comma after `as` instead means a SECOND with-item (`with a()
            # as x, b() as y:`, handled by the COMMA loop below). Reuse the
            # same unpacking-target-element parser/representation as
            # for-loop targets (_parse_unpack_target) rather than inventing
            # a separate with-specific tuple-target parser.
            self._advance(); alias = self._parse_unpack_target()
        items.append(WithItem(expr=expr, alias=alias))
        while self._peek().kind == "COMMA":
            self._advance(); expr = self._parse_expr(with_expr_prec); alias = None
            if self._is_kw("as"):
                # see the parenthesized-tuple-target note above.
                self._advance(); alias = self._parse_unpack_target()
            items.append(WithItem(expr=expr, alias=alias))
        self._expect("COLON")
        return WithStmt(items=items, body=self._parse_block())

    def _parse_comptime(self):
        self._expect("KW", "comptime")
        t = self._peek()
        if t.value == "if":  return self._parse_comptime_if()
        if t.value == "for": return self._parse_comptime_for()
        # comptime assert expr[, msg]
        if t.value == "assert":
            return self._parse_assert(is_comptime=True)
        # `comptime var NAME = expr` — the canonical Mojo spelling, and the
        # one the stdlib uses throughout. `var` (like `let`) is only a
        # declaration sigil here, so consume it and fall into the NAME shape
        # below. Without this the keyword is silently dropped: the statement
        # parses as ExprStmt(IdentExpr('comptime')) plus a separate VarDecl,
        # which emits a load of an undefined name and dies on the interpreted
        # path as `name 'comptime' is not defined` — a real misparse, not a
        # missing feature, so it is fixed here rather than worked around in
        # each backend.
        if t.kind == "KW" and t.value in ("var", "let"):
            self._advance()
            t = self._peek()
        # `comptime __match dtype:` — a compile-time match, which the stdlib uses
        # to pick a value out of a DType at compile time. Routed here rather
        # than falling into the NAME branch below, which would read `__match` as
        # the name being declared and leave a dangling `dtype:` behind.
        if t.kind == "NAME" and t.value in ("match", "__match") \
                and self._is_match_stmt():
            return self._parse_match()
        # comptime NAME [TypeParams] [: Type] = expr
        # Also allow backtick-quoted identifiers: comptime `A` = Byte(ord("A"))
        if t.kind == "NAME" or (t.kind == "STRING" and t.value.startswith("`")):
            name = self._advance().value
            # Skip optional type parameters: comptime Alias[T, U]: Type = ...
            if self._peek().kind == "LBRACKET": self._skip_bracketed()
            # Skip optional type annotation: comptime MIN: Bool = False
            if self._peek().kind == "COLON":
                self._advance()  # skip colon
                self._parse_type_ann()  # parse and discard type annotation
            # A multi-target comptime binding: `comptime a, b = expr(...)`, which
            # unpacks ONE compile-time value into two names. Collected BEFORE the
            # ASSIGN test below, because at this point the next token is the
            # COMMA — testing for `=` first returned a bare `ExprStmt(IdentExpr
            # ('a'))` and left `, b = expr` to be parsed as an ordinary statement
            # tuple-assignment, which is how it silently misparsed.
            targets = [name]
            # The loop consumes its OWN `=`, so remember that it did: testing
            # for an ASSIGN again afterwards looks for a SECOND one, finds the
            # RHS expression instead, and falls through to
            # `ExprStmt(IdentExpr(name))` — which silently drops the binding
            # and leaves the RHS to be parsed as the next statement.
            # `comptime char, num_bytes = Codepoint.unsafe_decode_...(...)`
            # (std/collections/string/codepoint.mojo) compiled that way, with
            # both names bound to nothing and the call statement orphaned; only
            # a fixture that inspects the resulting node types saw it.
            _saw_multi_eq = False
            while (self._peek().kind == "COMMA"
                   and self._peek(1).kind in ("NAME", "KW")
                   and self._peek(2).kind == "ASSIGN"):
                self._advance()
                targets.append(self._advance().value)
                self._advance()          # this entry's own '='
                _saw_multi_eq = True
            if _saw_multi_eq:
                rhs = self._skip_comptime_rhs()
                # Each name is bound to the same RHS node: the parser cannot see
                # that `expr` yields a 2-tuple (nothing in the syntax says so),
                # and this backend models a comptime alias as name-to-expression,
                # which is the shape every consumer of `comptime NAME = expr`
                # already reads. Splitting one value per name is the backends'
                # business, not the parser's.
                #
                # The loop variable is `_name`, NOT `t`: `t` is already a
                # `Token *` local in this function (from the `t = self._peek()`
                # above), and a comprehension target that shadows an enclosing
                # local used to reuse that local's C variable, so the `char *`
                # element came out as an `int64_t` temp assigned into
                # `struct Token * t` and the self-hosted `make mojoc` died with
                # "non-trivial conversion in 'var_decl'". Shadowing an int64_t
                # local happened to work; shadowing a struct pointer did not,
                # and this function has one.
                #
                # The compiled path no longer requires the rename — a
                # comprehension's target gets its own binding and the enclosing
                # one is restored afterwards, in `emit_infra.py`'s
                # `_compr_bind_target` / `_compr_restore_target`, regression
                # `comprehension_target_shadows_struct_local` in
                # `test_gimple_runner.py`. The rename stays: it is free, and it
                # keeps this function's own C output identical to what the
                # self-host stages were compared byte-for-byte against.
                return [ComptimeVarStmt(target=_name, value=rhs) for _name in targets]
            if self._peek().kind == "ASSIGN":
                self._advance()
                # Parse/skip RHS expression, handling complex function types
                rhs = self._skip_comptime_rhs()
                return [ComptimeVarStmt(target=name, value=rhs)]
            return ExprStmt(IdentExpr(name))
        raise SyntaxError(f"{self._loc(t)}Unexpected token after comptime: {t.value!r}")

    def _skip_comptime_rhs(self):
        """Parse RHS of comptime assignment, with fallback for complex types.

        Comptime variables are compile-time only and shouldn't generate runtime code.
        Try to parse simple literals/calls; for complex types (def[...] -> ...), skip them.
        """
        t = self._peek()

        # Check for function type definitions — skip to newline
        if self._comptime_rhs_is_function_type():
            depth = 0
            while self._peek().kind not in ("NEWLINE", "DEDENT", "EOF"):
                t = self._peek()
                if t.kind in ("LBRACKET", "LPAREN"):
                    depth += 1
                elif t.kind in ("RBRACKET", "RPAREN"):
                    depth -= 1
                    if depth < 0: break
                self._advance()
            return IdentExpr("_comptime_expr")

        # Try to parse simple expressions (literals, identifiers, simple calls)
        saved_pos = self._pos
        try:
            expr = self._parse_expr(0)
            return expr
        except (SyntaxError, ValueError, TypeError, AttributeError,
                IndexError, KeyError) as e:
            # This is a MISPARSE, not the function-type case above, and the
            # two used to be the same value. Skip to the newline so the rest
            # of the module still parses, record WHY, and re-raise: a
            # `comptime` alias whose value was lost is a wrong answer at every
            # use (the stdlib's `O_CREAT`/`O_APPEND` file-open flags are the
            # measured instance), and this backend's stated rule is that a
            # shape it cannot lower is refused rather than answered with
            # something the source never wrote.
            #
            # The exception set is enumerated rather than bare because a bare
            # `except:` here also swallowed the compiler's own bugs — a
            # `TypeError` from a malformed AST node read as "unparseable
            # comptime rhs" and became a placeholder, which is how a real
            # crash in this function could present as a stdlib constant
            # silently reading 0. `RecursionError` and `MemoryError` are
            # deliberately NOT caught either: a runaway parse is a bug to
            # surface, not a comptime alias to skip.
            self._pos = saved_pos
            text_parts = []
            while (self._peek().kind not in ("NEWLINE", "DEDENT", "EOF")
                   and len(text_parts) < 12):
                text_parts.append(_as_str(self._advance().value))
            _rhs_text = " ".join(text_parts)
            _where = self._loc(t)
            self._comptime_rhs_failures.append((_where, _rhs_text, str(e)))
            raise SyntaxError(
                f"{_where}cannot parse the right-hand side of a `comptime` "
                f"assignment: {_rhs_text!r} ({e}). A function TYPE "
                f"(`comptime F = def[T](Int) -> None`) is accepted and skipped "
                f"on purpose; anything else is a source this compiler cannot "
                f"read, and its alias would otherwise reach every use as a "
                f"placeholder value.")

    def _comptime_rhs_is_function_type(self) -> bool:
        """Is the pending `comptime` right-hand side a FUNCTION TYPE — the one
        shape deliberately not modelled, which becomes the
        `IdentExpr('_comptime_expr')` placeholder?

        Three ways to spell one, and all three are in this project's own
        stdlib:

        * `comptime F = def[T](Int) -> None` — the `def` token is first.
        * `comptime F = (\n    def[...]\n    (...) -> ...\n)` — a
          parenthesized, MULTI-LINE function type, which is 6 of the 22
          function-type aliases the new-modular stdlib declares
          (`std/_plugin/_trait.mojo`'s
          `_ReduceGeneratorPluginHookFnType` is the smallest). This is why
          there is a `(` case at all: with only the `def` and `->` tests, the
          `(`-wrapped form fell through to `_parse_expr`, raised, and — once
          a misparse is a REFUSAL rather than a silent placeholder (see
          `_skip_comptime_rhs`) — took a real stdlib module out of the
          build.
        * `comptime F = SomeType -> None`-shaped, i.e. the `->` at bracket
          depth 0: `_will_see_arrow`.

        Deliberately a shape test and not an "any `->` anywhere" scan: `->` at
        depth 0 is the existing rule and it is narrow on purpose, and looking
        through arbitrary parens would start claiming an ordinary parenthesized
        arithmetic expression whose operand happens to be a lambda."""
        t = self._peek()
        if t.kind == "KW" and t.value == "def":
            return True
        if t.kind == "LPAREN":
            nxt = self._peek(1)
            if nxt.kind == "KW" and nxt.value == "def":
                return True
        return self._will_see_arrow()

    def _will_see_arrow(self):
        """Lookahead to check if we'll see a -> at bracket depth 0 before NEWLINE."""
        saved = self._pos
        depth = 0
        while self._peek().kind not in ("NEWLINE", "DEDENT", "EOF"):
            t = self._peek()
            if t.kind == "ARROW" and depth == 0:
                self._pos = saved
                return True
            if t.kind in ("LBRACKET", "LPAREN"):
                depth += 1
            elif t.kind in ("RBRACKET", "RPAREN"):
                depth -= 1
            self._advance()
        self._pos = saved
        return False

    def _parse_comptime_if(self):
        self._expect("KW","if"); cond=self._parse_expr(0)
        self._expect("COLON"); body=self._parse_block()
        elifs, else_body = [], None
        while self._is_kw("elif"):
            self._advance(); ec = self._parse_expr(0)
            self._expect("COLON"); eb = self._parse_block()
            elifs.append((ec, eb))
        if self._is_kw("else"):
            self._advance();self._expect("COLON");else_body=self._parse_block()
        return ComptimeIfStmt(condition=cond,then_body=body,elifs=elifs,else_body=else_body)

    def _parse_comptime_for(self):
        self._expect("KW","for")
        # Optional convention keyword (var, ref, ...) before the target —
        # same disambiguation as _parse_for's sibling guard just above:
        # `var`/etc. is also a perfectly ordinary identifier, so only treat
        # it as a convention prefix when it's genuinely followed by a
        # separate target, not when it IS the target itself (i.e. peek(1)
        # is `in`, `:`, or `,`). This site previously had no guard at all —
        # it unconditionally swallowed any _CONV_KWS token, misparsing
        # `comptime for var in ...` and `comptime for var, j in ...`
        # (PARSE_FAIL_var_as_for_loop_target_comma).
        if (self._peek().kind == "KW" and self._peek().value in self._CONV_KWS
                and not (self._peek(1).kind == "KW" and self._peek(1).value == "in")
                and self._peek(1).kind != "COLON"
                and self._peek(1).kind != "COMMA"):
            self._advance()
        # Support tuple targets: comptime for i, j in product(...)
        target = self._ident()
        if self._peek().kind == "COMMA":
            names = [target]
            while self._peek().kind == "COMMA":
                self._advance()
                if self._is_kw("in"): break
                names.append(self._ident())
            target = "(" + ", ".join(names) + ")"
        self._expect("KW","in"); iterable=self._parse_expr(0)
        self._expect("COLON")
        return ComptimeForStmt(target=target,iterable=iterable,body=self._parse_block())

    def _parse_pass(self):
        t = self._peek()
        self._expect("KW", 'pass')
        return PassStmt(line=t.line, col=t.col)

    def _parse_return(self):
        t = self._peek()
        self._expect("KW", 'return')
        if self._peek().kind in ("NEWLINE","EOF","DEDENT"):
            return ReturnStmt(value=None, line=t.line, col=t.col)
        expr = self._parse_expr(0)
        # Check for tuple return: return a, b, c
        if self._peek().kind == "COMMA":
            elements = [expr]
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind in ("NEWLINE", "DEDENT", "EOF"):
                    break
                elements.append(self._parse_expr(0))
            # A separate variable, not reassigning `expr` — `expr` is first
            # assigned from self._parse_expr(0) (an opaque/boxed Expr
            # subtype, compiled as generic int64_t), then would be
            # reassigned here to a real TupleExpr(...) constructor call.
            # Joining those two assignment sites' types made the compiled
            # local's declared C type `TupleExpr *` (the type-join rule
            # "one pointer, one non-pointer -> use the pointer type" doesn't
            # know the "non-pointer" int64_t side is itself an opaquely
            # boxed pointer of some OTHER concrete type) — but `expr.line`/
            # `expr.col` just below read the ORIGINAL boxed value through
            # that wrong, TupleExpr-shaped field layout, misreading garbage
            # off whatever real struct (e.g. IdentExpr) `expr` actually
            # held. Found via `def f(a, b): return a, b` compiling to
            # TupleExpr(..., line=<garbage pointer>, ...) once self-hosted.
            tuple_expr = TupleExpr(elements=elements, line=expr.line, col=expr.col)
            return ReturnStmt(value=tuple_expr, line=t.line, col=t.col)
        return ReturnStmt(value=expr, line=t.line, col=t.col)

    def _parse_raise(self):
        self._expect("KW", 'raise')
        if self._peek().kind in ("NEWLINE","EOF","DEDENT"):
            return RaiseStmt(value=None)
        val = self._parse_expr(0)
        # `raise X from Y` / `raise X from None` — exception-chaining
        # suppression. The cause is not modeled by our tag-based exception
        # runtime, but must be consumed so parsing continues past it.
        if self._is_kw("from"):
            self._advance(); self._parse_expr(0)
        return RaiseStmt(value=val)

    def _parse_break(self):
        self._expect("KW", 'break')
        return BreakStmt()

    def _parse_continue(self):
        self._expect("KW", 'continue')
        return ContinueStmt()

    def _parse_assert(self, is_comptime=False):
        t = self._expect("KW", 'assert')
        value = self._parse_expr(0)
        msg = None
        if self._peek().kind == "COMMA":
            self._advance(); msg = self._parse_expr(0)
        return AssertStmt(value=value, msg=msg, is_comptime=is_comptime, line=t.line, col=t.col)

    def _parse_global(self):
        t = self._peek()
        self._expect("KW", 'global')
        names = []
        names.append(self._expect("NAME").value)
        while self._peek().kind == "COMMA":
            self._advance()
            if self._peek().kind in ("NEWLINE", "DEDENT", "EOF"):
                break
            names.append(self._expect("NAME").value)
        return GlobalStmt(names=names, line=t.line, col=t.col)

    def _parse_nonlocal(self):
        """`nonlocal a, b` — see `NonlocalStmt`. Mirrors `_parse_global`."""
        t = self._peek()
        self._expect("KW", 'nonlocal')
        names = [self._expect("NAME").value]
        while self._peek().kind == "COMMA":
            self._advance()
            if self._peek().kind in ("NEWLINE", "DEDENT", "EOF"):
                break
            names.append(self._expect("NAME").value)
        return NonlocalStmt(names=names, line=t.line, col=t.col)

    def _parse_del(self):
        """`del a`, `del a, b`, `del d["k"]`, `del obj.attr` — each
        comma-separated target is an arbitrary expression, not just a name."""
        t = self._peek()
        self._expect("KW", 'del')
        targets = [self._parse_expr(0)]
        while self._peek().kind == "COMMA":
            self._advance()
            if self._peek().kind in ("NEWLINE", "DEDENT", "EOF"):
                break
            targets.append(self._parse_expr(0))
        return DelStmt(targets=targets, line=t.line, col=t.col)

    # ── Expressions ──────────────────────────────────────────────────
    def _at_compare_op(self) -> bool:
        """True if the current token begins a comparison-chain operator:
        one of the OP-form comparisons, or the KW-form 'in'/'is', or the
        two-token 'not in' (only when 'not' is actually followed by 'in' —
        a bare 'not' is the unrelated prefix operator, handled elsewhere)."""
        t = self._peek()
        if t.kind == "OP":
            return t.value in _COMPARE_OPS
        if t.kind == "KW":
            if t.value in ("in", "is"):
                return True
            if t.value == "not" and self._peek(1).kind == "KW" and self._peek(1).value == "in":
                return True
        return False

    def _consume_compare_op(self) -> str:
        """Consume and return the canonical operator string for a
        comparison-chain link. Assumes _at_compare_op() was already checked."""
        t = self._peek()
        if t.kind == "OP":
            return self._advance().value
        kw = self._advance().value  # 'in', 'is', or 'not' (of 'not in')
        if kw == "is" and self._is_kw("not"):
            self._advance()
            return "is not"
        if kw == "not":
            self._advance()  # consume the 'in' that _at_compare_op() confirmed follows
            return "not in"
        return kw  # 'in', or plain 'is'

    def _parse_expr(self, min_prec: int):
        # Boolean `not` is a low-precedence prefix operator (binds looser than
        # comparison/`in`, tighter than `and`): `not a in b` == `not (a in b)`.
        # The binary `not in` form is handled in the operator loop below.
        if self._peek().kind == "KW" and self._peek().value == "not":
            self._advance()
            operand = self._parse_expr(_KW_PREC['not'])
            left = UnaryOp(op="not", operand=operand)
        else:
            left = self._parse_unary()
        while True:
            t = self._peek()
            # Comparison-chain operators (==, !=, <, <=, >, >=, in, is, not
            # in, is not) all bind at _COMPARE_CHAIN_PREC and, unlike every
            # other binary operator, DON'T simply nest left-to-right into
            # BinaryOp(BinaryOp(...), ...) — real Python (and this parser)
            # treats `a < b < c` as one chained comparison `(a < b) and (b <
            # c)`, not `(a < b) < c`. A single link (the overwhelmingly
            # common case, e.g. plain `a < b`) still produces exactly the
            # same BinaryOp node as before this existed; only an actual
            # 2+-link chain produces a CompareChain, appended to
            # incrementally as more links are found.
            if self._at_compare_op():
                if _COMPARE_CHAIN_PREC < min_prec: break
                op = self._consume_compare_op()
                right = self._parse_expr(_COMPARE_CHAIN_PREC + 1)
                if isinstance(left, CompareChain):
                    left.operands.append(right)
                    left.ops.append(op)
                elif self._at_compare_op():
                    left = CompareChain(operands=[left, right], ops=[op])
                else:
                    left = BinaryOp(op=op, left=left, right=right)
                continue
            if t.kind == "OP":
                prec = _PREC.get(t.value, -1)
                if prec < min_prec: break
                op = self._advance().value
                right = self._parse_expr(prec + 1)
                if op == ":=" and isinstance(left, IdentExpr):
                    left = WalrusExpr(name=left.name, value=right)
                else:
                    left = BinaryOp(op=op, left=left, right=right)
            elif t.kind == "KW" and t.value in _KW_PREC:
                prec = _KW_PREC[t.value]
                if prec < min_prec: break
                op = self._advance().value
                right = self._parse_expr(prec + 1)
                left = BinaryOp(op=op, left=left, right=right)
            elif t.kind == "KW" and t.value == "if" and min_prec == 0:
                self._advance()
                cond = self._parse_expr(1)
                self._expect("KW", "else")
                els = self._parse_expr(0)
                left = TernaryExpr(condition=cond, then_val=left, else_val=els)
            else:
                break
        return left

    def _parse_unary(self):
        t = self._peek()
        # `await expr` — `await` lexes as a plain NAME (not a keyword).
        # Milestone 3a: build a real AwaitExpr node (no execution semantics
        # yet — see its docstring) instead of Milestone-1-era silently
        # unwrapping to just the awaited expression. Guard on the next token
        # starting an expression so a variable literally named `await`
        # (`x = await`, `await.foo`) still reads as an identifier.
        if (t.kind == "NAME" and t.value == "await"
                and self._peek(1).kind in ("NAME", "KW", "STRING", "INT",
                    "FLOAT", "IMAG", "LPAREN", "LBRACKET", "LBRACE")):
            self._advance()
            return AwaitExpr(value=self._parse_unary(), line=t.line, col=t.col)
        if t.kind == "OP" and t.value in ("-", "+", "~"):
            self._advance()
            return UnaryOp(op=t.value, operand=self._parse_unary())
        # Boolean `not` is handled as a low-precedence prefix in _parse_expr.
        # Spread/unpack: *expr or **expr (valid inside list/dict/call literals).
        # `**` lexes as a single OP token, so handle it directly — otherwise
        # dict unpacking `{**a, **b}` hit the fallthrough "Unexpected OP('**')".
        if t.kind == "OP" and t.value == "**":
            self._advance()
            return UnaryOp(op="**", operand=self._parse_unary())
        if t.kind == "OP" and t.value == "*":
            self._advance()
            # Check for **
            if self._peek().kind == "OP" and self._peek().value == "*":
                self._advance()
                return UnaryOp(op="**", operand=self._parse_unary())
            return UnaryOp(op="*", operand=self._parse_unary())
        return self._parse_postfix()

    def _parse_subscript_item(self):
        """Parse one subscript element: a slice (`start:stop:step`, every part
        optional) or a plain expression. Slices are returned as a SliceExpr with
        obj=None (the caller attaches the object); plain indices are returned as
        the bare expression node. Used for both 1-D and multi-dim (`a[0:2, ::]`)
        indexing."""
        start = None
        if self._peek().kind != "COLON":
            # A FUNCTION TYPE in index position: `unsafe_bitcast[def(*a: *T)
            # thin abi("C") -> Ret]()`. `_parse_type_ann_inner` already parses
            # the whole `def(params) quals -> Ret` form (balanced-paren
            # parameter skip, `thin`/`abi("C")` qualifiers, recursive return
            # type), whereas `_parse_expr` cannot: the parameter list's own
            # `(*a: *T)` annotation colon is not an expression at all, so the
            # expression parse died on it before the ARROW handling below could
            # ever run.
            if self._peek().kind == "KW" and self._peek().value in ("def", "fn"):
                start = self._parse_type_ann()
                self._skip_fn_quals()
                if self._peek().kind == "ARROW":
                    self._advance(); self._parse_type_ann()
                if self._peek().kind != "COLON":
                    return start  # plain index, not a slice
            else:
                start = self._parse_expr(0)
                # Function-type annotation in type position: def(...) [quals] -> T
                self._skip_fn_quals()
                if self._peek().kind == "ARROW":
                    self._advance(); self._parse_type_ann()
                if self._peek().kind != "COLON":
                    return start  # plain index, not a slice
        # At a COLON → this element is a slice.
        self._advance()
        stop = (None if self._peek().kind in ("RBRACKET", "COMMA", "COLON")
                else self._parse_expr(0))
        step = None
        if self._peek().kind == "COLON":
            self._advance()
            step = (None if self._peek().kind in ("RBRACKET", "COMMA")
                    else self._parse_expr(0))
        return SliceExpr(obj=None, start=start, stop=stop, step=step)

    def _parse_postfix(self):
        expr = self._parse_primary()
        while True:
            t = self._peek()
            line, col = t.line, t.col
            if t.kind == "DOT":
                self._advance()
                # Member can be a NAME (including KW like mut, ref) or a backtick-quoted type
                if self._peek().kind == "STRING" and self._peek().value.startswith("`"):
                    member = self._advance().value
                elif self._peek().kind in ("NAME", "KW"):
                    member = self._advance().value
                else:
                    member = self._expect("NAME").value  # error for invalid syntax
                expr = MemberExpr(obj=expr, member=member, line=line, col=col)
            elif t.kind == "LBRACKET":
                self._advance()
                # Check for empty subscript [] (dereference/special case)
                if self._peek().kind == "RBRACKET":
                    # `raw=''` explicit: the self-hosted compiled backend does
                    # not materialize the `IntLiteral.raw: str = ''` dataclass
                    # field default (its `_alloc_IntLiteral` class-attr seed is
                    # dropped depending on which temp_gen emits it), so an
                    # omitted `raw` dumps as `raw=None` where the reference has
                    # `raw=''`. Every synthetic IntLiteral in this file passes
                    # it explicitly for that reason.
                    idx = IntLiteral(value=0, raw='')  # dummy index for empty subscript
                    self._advance()  # consume RBRACKET
                    expr = SubscriptExpr(obj=expr, index=idx)
                else:
                    # Parse first index/argument
                    # Check for unpacking: *expr
                    if self._peek().kind == "OP" and self._peek().value == "*":
                        self._advance()  # skip *
                        self._parse_expr(0)  # parse and discard unpacked value
                        # Continue parsing remaining arguments
                        while self._peek().kind == "COMMA":
                            self._advance()
                            if self._peek().kind == "RBRACKET": break
                            # Skip remaining arguments/keywords
                            if self._peek().kind == "OP" and self._peek().value == "*":
                                self._advance()
                                self._parse_expr(0)
                            elif self._peek().kind in ("NAME", "KW") and self._peek(1).kind == "ASSIGN":
                                self._advance()  # skip name
                                self._advance()  # skip =
                                self._parse_expr(0)
                            else:
                                self._parse_expr(0)
                            if self._peek().kind != "COMMA" and self._peek().kind != "RBRACKET": break
                        self._expect("RBRACKET")
                        expr = SubscriptExpr(obj=expr, index=IntLiteral(value=0, raw=''))
                    # Check if this is a keyword-style bracket (func=value, attr=value)
                    elif self._peek().kind in ("NAME", "KW") and self._peek(1).kind == "ASSIGN":
                        # Keyword arguments (may include positional args with dotted names and slice values).
                        # We keep (name, value) pairs in `attrs` so consumers that
                        # need them survive — notably MLIR op params like
                        # __mlir_op.`index.cmp`[pred=__mlir_attr.`...`](...).
                        #
                        # A bracket may MIX the two forms, in EITHER order, and
                        # both elements have to be kept: `f[T=Int, "x", linux=1]`
                        # is the ordinary way to call this project's own
                        # `def platform_map[T: DType, operation, *, linux=..., macos=...]`
                        # (std/sys/info.mojo), whose signature puts the positional
                        # `operation` AFTER the keyword `T` and BEFORE the keyword
                        # `linux`/`macos`. Two defects made that shape
                        # unparseable, and both are fixed here:
                        #
                        #   * a bare element that was not a NAME (a literal, a call,
                        #     an ellipsis) fell through both arms, so the loop hit
                        #     its `elif peek != RBRACKET: break`, left the token
                        #     unconsumed, and `_expect("RBRACKET")` raised — a
                        #     ParseError that `_skip_comptime_rhs`'s bare `except`
                        #     turned into the `_comptime_expr` placeholder, so the
                        #     alias read as a placeholder at every use.
                        #   * a bare element that WAS a NAME parsed and was then
                        #     DISCARDED — the old "else positional arg: arg_expr
                        #     already fully parsed" comment described no code. It
                        #     is kept now, as a `(None, value)` pair, which is the
                        #     spelling `emit_calls.py`'s comptime-param threading
                        #     already reads positionals by (`elems = [val for nm,
                        #     val in _bracket_attrs if nm is None]`) and which the
                        #     tuple's own `name: object` field allows for.
                        #
                        # `f[1, 2]` (no keyword at all) still takes the
                        # comma-separated-items branch below and lands in
                        # `index` as a TupleExpr; that is a different path with
                        # its own consumers and it is left alone.
                        _attrs = []
                        while self._peek().kind != "RBRACKET" and self._peek().kind != "EOF":
                            if (self._peek().kind == "DOT" and
                                    self._peek(1).kind == "DOT" and
                                    self._peek(2).kind == "DOT"):
                                # Ellipsis argument (three DOTs) — no value to keep.
                                self._advance(); self._advance(); self._advance()
                            else:
                                # Parse the full expression for the arg (handles dotted names Self.Ts, subscripts, etc.)
                                arg_expr = self._parse_expr(0)
                                if self._peek().kind == "ASSIGN":
                                    # keyword arg: advance = and parse the value,
                                    # which may itself be a slice (key = -50::) or
                                    # a function type. _parse_subscript_item handles
                                    # all of start:stop:step, fn-types, and exprs.
                                    self._advance()
                                    _val = self._parse_subscript_item()
                                    # Real `if`, not a ternary: this codegen's ternary
                                    # always evaluates both branches, so `.name` would
                                    # run even when arg_expr isn't an IdentExpr (see the
                                    # identical fix + note in _parse_stmt's bare-annotation
                                    # branch above).
                                    _name = None
                                    if isinstance(arg_expr, IdentExpr):
                                        _name = arg_expr.name
                                    _attrs.append((_name, _val))
                                elif isinstance(arg_expr, IdentExpr):
                                    # A bare NAME with no `=`: a positional
                                    # parameter, kept under its own name (which is
                                    # what lets a consumer read it either way — the
                                    # `nm is None` positional list and the
                                    # `nm is not None` keyword dict then both see
                                    # it, and `emit_calls.py` prefers the keyword
                                    # lookup and falls back to the positional one).
                                    _attrs.append((arg_expr.name, arg_expr))
                                else:
                                    # A bare literal / call / subscript: positional,
                                    # and its position in `_attrs` is its position
                                    # in the bracket.
                                    _attrs.append((None, arg_expr))
                            if self._peek().kind == "COMMA": self._advance()
                            elif self._peek().kind != "RBRACKET": break
                        self._expect("RBRACKET")
                        # The node inherits the CALLEE's position, which is
                        # where a diagnostic about this bracket belongs —
                        # `SubscriptExpr(...)` built with the dataclass
                        # defaults reports `0:0`, which is what
                        # myinterpreter.py's unbindable-comptime-parameter
                        # TypeError used to print.
                        expr = SubscriptExpr(obj=expr, index=IntLiteral(value=0, raw=''), attrs=_attrs,
                                             line=expr.line, col=expr.col)
                    else:
                        # Parse a comma-separated list of subscript items. Each
                        # item is a slice (start:stop:step) or a plain expression,
                        # so this covers 1-D slicing (a[1:2]), generic params
                        # (List[T, n]), and multi-dim slicing (a[0:2, ::]).
                        items = [self._parse_subscript_item()]
                        while self._peek().kind == "COMMA":
                            self._advance()
                            if self._peek().kind == "RBRACKET": break
                            # Unpacking: *expr
                            if self._peek().kind == "OP" and self._peek().value == "*":
                                self._advance()
                                items.append(self._parse_expr(0))
                            # Keyword argument: name = value (generic params)
                            elif self._peek().kind in ("NAME", "KW") and self._peek(1).kind == "ASSIGN":
                                self._advance()  # name
                                self._advance()  # =
                                items.append(self._parse_subscript_item())
                            # Ellipsis: ...
                            elif (self._peek().kind == "DOT" and
                                  self._peek(1).kind == "DOT" and
                                  self._peek(2).kind == "DOT"):
                                self._advance(); self._advance(); self._advance()
                                items.append(EllipsisLiteral())
                            else:
                                items.append(self._parse_subscript_item())
                        self._expect("RBRACKET")
                        if len(items) == 1:
                            only = items[0]
                            # A bare slice at THIS bracket depth (`x[a:b]`) comes
                            # back from _parse_subscript_item as a fresh
                            # SliceExpr(obj=None, ...) still waiting for its
                            # object. But `only` can also be a SliceExpr whose
                            # obj is ALREADY set -- e.g. `x[y[1:]]`, where the
                            # single subscript item is itself a fully-parsed
                            # nested slice expression (obj=y) returned unchanged
                            # by _parse_subscript_item's "plain index" path
                            # (`_parse_expr(0)` recursing into `_parse_postfix`
                            # for `y[1:]`, then landing right back here one call
                            # deeper, where its own single item's obj=None case
                            # already ran and set obj=y). Checking only
                            # `isinstance(only, SliceExpr)` can't tell these
                            # apart, and used to unconditionally overwrite
                            # `.obj` with the OUTER object -- so `x[y[1:]]`
                            # silently became `x[1:]` (y discarded entirely),
                            # producing a bogus slice-assignment/read target
                            # with the wrong bounds and object. `obj is None`
                            # distinguishes "still needs attaching" from
                            # "already a complete nested expression".
                            if isinstance(only, SliceExpr) and only.obj is None:
                                only.obj = expr  # attach object to the bare slice
                                expr = only
                            else:
                                expr = SubscriptExpr(obj=expr, index=only)
                        else:
                            expr = SubscriptExpr(obj=expr, index=TupleExpr(elements=items))
            elif t.kind == "LPAREN":
                args, kwargs_list = self._parse_paren_args()
                expr = CallExpr(func=expr, args=args, kwargs=kwargs_list, line=line, col=col)
            elif t.kind == "OP" and t.value == "^":
                # Check if ^ is postfix (ownership transfer) or binary (XOR)
                # Postfix: followed by statement-ending token or member/subscript access
                # Binary: followed by expression start token
                next_t = self._peek(1)
                is_postfix = next_t.kind in ("NEWLINE", "DEDENT", "EOF", "COMMA", "RPAREN", "RBRACKET", "RBRACE", "COLON", "SEMICOLON", "DOT", "LBRACKET")
                if is_postfix:
                    self._advance()
                    expr = UnaryOp(op="^", operand=expr, line=line, col=col)
                else:
                    break  # Let binary operator precedence handle it
            else:
                break
        return expr

    def _strip_string_prefix_and_quotes(self, raw: str) -> str:
        """A STRING token's value may carry a prefix (f/F/r/R/b/B/u/U/t/T,
        0-2 chars) before the quotes. F-strings and t-strings deliberately
        KEEP their prefix+quotes in the StringLiteral value (both
        gimple_codegen.py's _lower_StringLiteral and myinterpreter.py's
        eval_StringLiteral need the prefix, to know interpolation is needed
        and to tell the two apart) but every other prefixed string (r'...',
        b'...', rb'...', etc.) must have BOTH the prefix and the quotes
        stripped — this previously only stripped quotes when the raw token
        started with a quote character directly, silently leaving any r/b/u
        prefix as literal text in the StringLiteral's value for every non-f
        prefixed string. Found via reflect.py's own
        `_PROTO_RE = re.compile(r'...')`: the compiled StringLiteral's value
        was the literal text "r'...'" (prefix and quotes included), not the
        real pattern text.
        """
        # NOTE: this codegen's `and`/`or` always evaluate BOTH operands (no
        # real short-circuiting — see gimple_codegen.py's BinaryOp lowering),
        # so every guard below must be a separate nested `if`, never
        # `cond and raw[i]`-style — otherwise the index/slice still runs
        # even when the guard is false and crashes on an empty string.
        # Deliberately avoid `x in "somestring"`/`x in (a, b)`-style checks
        # for the two guards below (prefix-char scan, f/t detection) — this
        # codegen's compiled path has a confirmed, still-open bug where
        # implementing that specific shape of the `in` operator corrupts
        # unrelated state elsewhere (see BACKLOG-CODEGEN.md / the
        # bootstrap-verify-ast-dump-fixes memory note). Explicit `==`
        # comparisons on single characters are a proven-safe, already-used
        # pattern elsewhere in this same function (see the `first == last`
        # comment below) and sidestep that bug entirely.
        prefix_len = 0
        while prefix_len < len(raw) and prefix_len < 2:
            _c = raw[prefix_len]
            _is_prefix_char = (_c == 'f' or _c == 'F' or _c == 'r' or _c == 'R'
                                or _c == 'b' or _c == 'B' or _c == 'u' or _c == 'U'
                                or _c == 't' or _c == 'T')
            if not _is_prefix_char:
                break
            prefix_len += 1
        prefix, rest = raw[:prefix_len], raw[prefix_len:]
        has_quote_after_prefix = False
        if len(rest) >= 1:
            _rc = rest[0]
            if _rc == '"' or _rc == "'":
                has_quote_after_prefix = True
        if not has_quote_after_prefix:
            prefix, rest = '', raw  # no real prefix (nothing quote-like follows it)
        # Compare both cases directly instead of calling .lower() on a raw
        # indexed char (prefix[0]/[1]) — that routes to a runtime helper
        # (char.lower()) this compiler doesn't implement for a bare char,
        # an undefined-symbol link error ("_char_lower"), not a silent bug.
        _has_ft = False
        if len(prefix) >= 1:
            _p0 = prefix[0]
            if _p0 == 'f' or _p0 == 'F' or _p0 == 't' or _p0 == 'T':
                _has_ft = True
        if len(prefix) >= 2:
            _p1 = prefix[1]
            if _p1 == 'f' or _p1 == 'F' or _p1 == 't' or _p1 == 'T':
                _has_ft = True
        if _has_ft:
            return raw
        # Built via concatenation, not written as literal 3-quote runs (see
        # replace_multiline_strings's identical "avoids bootstrap self-match"
        # comment for the same reasoning) — py_tokenize's own docstring
        # placeholder pass has no notion of enclosing-quote context: it
        # matches the FIRST literal triple-quote run it sees in the source
        # and non-greedily extends to the NEXT one found anywhere later, on
        # the assumption both delimit one real multi-line string. Two short,
        # unrelated same-shape literals a few lines apart (a single quote
        # wrapping three double-quote characters, and the mirror case) used
        # to sit right here as literal source text, and that used to be
        # exactly the trigger: self-hosted-compiling THIS function's own
        # body swallowed everything between them as one bogus docstring
        # placeholder, corrupting the compiled function so it always
        # returned false here regardless of the real input — breaking every
        # real triple-quoted docstring's quote-stripping for every
        # self-hosted-compiled program, not just ones with adjacent literals
        # of this shape. Found via bootstrap_test_single_expr.mojo's own
        # plain, isolated docstring picking up two stray extra quote
        # characters once self-hosted. NOTE: keep this whole comment block
        # free of the literal quote-triple shapes described above too — the
        # same self-match hazard applies to comment text, not just code.
        _dq3 = '"' * 3
        _sq3 = "'" * 3
        if len(rest) >= 6:
            if rest.startswith(_dq3) and rest.endswith(_dq3):
                return rest[3:-3]
            if rest.startswith(_sq3) and rest.endswith(_sq3):
                return rest[3:-3]
        if len(rest) >= 2:
            # Compare characters directly (`first == last`) rather than
            # `rest.endswith(rest[0])`: `rest[0]` is a raw single-character
            # scalar (this codegen's string-indexing result), and passing it
            # straight into a call expecting `char *` reinterprets its byte
            # value as a garbage pointer — the same "raw char vs char*"
            # mismatch documented in gimple_codegen.py's _to_char_star, just
            # hit via a call argument instead of a `==` comparison this time.
            first = rest[0]
            last = rest[len(rest) - 1]
            if (first == '"' or first == "'") and first == last:
                return rest[1:-1]
        return raw

    def _raw_string_is_ftstring(self, raw: str) -> bool:
        """True if a raw STRING token carries an f/F/t/T prefix."""
        _n = 0
        while _n < len(raw) and _n < 2:
            _c = raw[_n]
            _is_prefix = (_c == 'f' or _c == 'F' or _c == 'r' or _c == 'R'
                          or _c == 'b' or _c == 'B' or _c == 'u' or _c == 'U'
                          or _c == 't' or _c == 'T')
            if not _is_prefix:
                break
            if _c == 'f' or _c == 'F' or _c == 't' or _c == 'T':
                return True
            _n += 1
        return False

    def _string_literal_inner(self, raw: str) -> str:
        """The inner content of a raw STRING token — prefix and the outer
        quote delimiters removed, `{...}` interpolations and escapes left
        intact. Unlike `_strip_string_prefix_and_quotes` this ALSO unwraps
        f/t-strings, for merging adjacent implicitly-concatenated literals
        (`f'a' f'b'` -> one `f'ab'`). Without this the parser glued the raw
        f-string tokens (`f'a'f'b'`), and codegen's outer-only
        prefix/quote strip then left the inner `'f'` delimiters as literal
        text (the stray `'f'` in every compiled weak-stub)."""
        _n = 0
        while _n < len(raw) and _n < 2:
            _c = raw[_n]
            _is_prefix = (_c == 'f' or _c == 'F' or _c == 'r' or _c == 'R'
                          or _c == 'b' or _c == 'B' or _c == 'u' or _c == 'U'
                          or _c == 't' or _c == 'T')
            if not _is_prefix:
                break
            _n += 1
        rest = raw[_n:]
        if len(rest) >= 1:
            _q = rest[0]
            if _q != '"' and _q != "'":
                rest = raw  # no real prefix
        # len()-based slice bounds (never a negative stop) — the compiled
        # path resolves a negative slice stop wrong.
        _rl = len(rest)
        _dq3 = '"' * 3
        _sq3 = "'" * 3
        if _rl >= 6:
            if rest.startswith(_dq3) and rest.endswith(_dq3):
                return rest[3:_rl - 3]
            if rest.startswith(_sq3) and rest.endswith(_sq3):
                return rest[3:_rl - 3]
        if _rl >= 2:
            _first = rest[0]
            _last = rest[_rl - 1]
            if (_first == '"' or _first == "'") and _first == _last:
                return rest[1:_rl - 1]
        return rest

    def _raw_string_is_bytes(self, raw: str) -> bool:
        """True when a raw STRING token has a `b`/`B` prefix (possibly with
        a companion `r`) immediately before its opening quote — i.e. it is a
        `b'...'` / `rb'...'` byte-string literal, not a text string."""
        prefix_len = 0
        while prefix_len < len(raw) and prefix_len < 2:
            _c = raw[prefix_len]
            _is_prefix_char = (_c == 'f' or _c == 'F' or _c == 'r' or _c == 'R'
                                or _c == 'b' or _c == 'B' or _c == 'u' or _c == 'U'
                                or _c == 't' or _c == 'T')
            if not _is_prefix_char:
                break
            prefix_len += 1
        prefix = raw[:prefix_len]
        rest = raw[prefix_len:]
        if len(rest) < 1:
            return False
        _rc = rest[0]
        if _rc != '"' and _rc != "'":
            return False
        _has_b = False
        for _pc in prefix:
            if _pc == 'b' or _pc == 'B':
                _has_b = True
        return _has_b

    def _raw_string_is_raw(self, raw: str) -> bool:
        """True when a STRING token carries an `r`/`R` prefix before its quote.

        The sibling of `_raw_string_is_bytes`, and it exists because
        `decode_c_escapes` is now the ONE decoder every engine calls (see that
        function), so a raw literal has to be able to say "leave me alone" —
        `r"a\nb"` is four characters to CPython and must be four here too, and
        without this the shared decode would turn it into a newline in all
        three engines at once. The prefix is stripped by
        `_strip_string_prefix_and_quotes` and otherwise thrown away, so this
        reads it off the RAW token before that happens.
        """
        prefix_len = 0
        while prefix_len < len(raw) and prefix_len < 2:
            _c = raw[prefix_len]
            _is_prefix_char = (_c == 'f' or _c == 'F' or _c == 'r' or _c == 'R'
                                or _c == 'b' or _c == 'B' or _c == 'u' or _c == 'U'
                                or _c == 't' or _c == 'T')
            if not _is_prefix_char:
                break
            prefix_len += 1
        prefix = raw[:prefix_len]
        rest = raw[prefix_len:]
        if len(rest) < 1:
            return False
        _rc = rest[0]
        if _rc != '"' and _rc != "'":
            return False
        for _pc in prefix:
            if _pc == 'r' or _pc == 'R':
                return True
        return False

    def _decode_bytes_literal(self, raw: str) -> str:
        """Strip a `b'...'` token's prefix+quotes and decode its escape
        sequences to a latin-1 string carrying one character per output
        byte (codepoints 0-255). `\\xNN`, `\\n`, `\\t`, `\\r`, `\\a`,
        `\\b`, `\\f`, `\\v`, `\\0`, `\\\\`, `\\'`, `\\"` are recognised; a
        raw `r` prefix disables all escape processing. Unknown `\\c`
        sequences are kept verbatim (backslash + char), matching CPython's
        bytes-literal leniency — but a KNOWN one is not unknown, and
        `\\f`/`\\v`/`\\a`/`\\b` were missing from the table below, so
        `b"\\f"` was two characters (backslash, f) rather than one
        (0x0c): a silent wrong value in every bytes literal using them, and
        an inconsistency with the `str` path, which decoded all of them
        correctly. Measured against CPython, all four now agree."""
        inner = self._strip_string_prefix_and_quotes(raw)
        is_raw = False
        prefix_len = 0
        while prefix_len < len(raw) and prefix_len < 2:
            _c = raw[prefix_len]
            if _c == 'r' or _c == 'R':
                is_raw = True
            if not (_c == 'f' or _c == 'F' or _c == 'r' or _c == 'R'
                    or _c == 'b' or _c == 'B' or _c == 'u' or _c == 'U'
                    or _c == 't' or _c == 'T'):
                break
            prefix_len += 1
        if is_raw:
            return inner
        out = []
        i = 0
        n = len(inner)
        _hex = '0123456789abcdefABCDEF'
        while i < n:
            ch = inner[i]
            if ch != '\\' or i + 1 >= n:
                out.append(ch)
                i += 1
                continue
            nxt = inner[i + 1]
            if nxt == 'n':
                out.append('\n'); i += 2; continue
            if nxt == 't':
                out.append('\t'); i += 2; continue
            if nxt == 'r':
                out.append('\r'); i += 2; continue
            if nxt == 'a':
                out.append('\a'); i += 2; continue
            if nxt == 'b':
                out.append('\b'); i += 2; continue
            if nxt == 'f':
                out.append('\f'); i += 2; continue
            if nxt == 'v':
                out.append('\v'); i += 2; continue
            if nxt == '\\':
                out.append('\\'); i += 2; continue
            if nxt == "'":
                out.append("'"); i += 2; continue
            if nxt == '"':
                out.append('"'); i += 2; continue
            if nxt == '0':
                out.append('\x00'); i += 2; continue
            if nxt == 'x' and i + 3 < n and inner[i + 2] in _hex and inner[i + 3] in _hex:
                out.append(chr(int(inner[i + 2:i + 4], 16)))
                i += 4
                continue
            out.append(ch)
            out.append(nxt)
            i += 2
        return ''.join(out)

    def _merge_string_literals(self, raws: list, line: int, col: int):
        """Fold a run of adjacent implicitly-concatenated STRING tokens
        into one StringLiteral. If any is an f/t-string the result is a
        single f-string (`f<q>...<q>`); otherwise it is a plain string."""
        _any_ft = False
        for _r in raws:
            if self._raw_string_is_ftstring(_r):
                _any_ft = True
                break
        if not _any_ft:
            _any_bytes = False
            for _r in raws:
                if self._raw_string_is_bytes(_r):
                    _any_bytes = True
                    break
            if _any_bytes:
                _val = ''
                for _r in raws:
                    if self._raw_string_is_bytes(_r):
                        _val += self._decode_bytes_literal(_r)
                    else:
                        _val += self._strip_string_prefix_and_quotes(_r)
                return StringLiteral(_val, line=line, col=col, is_bytes=True)
            _val = ''
            for _r in raws:
                _val += self._strip_string_prefix_and_quotes(_r)
            # `is_raw` is the AND over the run: an implicitly-concatenated
            # sequence is raw only if every part of it is, because the merged
            # body is one string and one of its halves must not have been
            # decoded. `r"a\n" "b"` is a backslash-n followed by a `b` and the
            # other way round is a newline followed by a `b`, and the second is
            # not something the caller wrote.
            _all_raw = True
            for _r in raws:
                if not self._raw_string_is_raw(_r):
                    _all_raw = False
                    break
            return StringLiteral(_val, line=line, col=col, is_raw=_all_raw)
        _merged = ''
        for _r in raws:
            _merged += self._string_literal_inner(_r)
        _dq3 = '"' * 3
        _sq3 = "'" * 3
        # `is_interpolated=True` on all three returns, and the evidence is the
        # `_any_ft` this branch is reached under: one of the run's TOKENS
        # carried an f/t prefix. The re-wrapped value still starts with an `f`
        # (the consumers strip it), so a reader that sniffed it would agree —
        # which is exactly why the flag is set here rather than left to be
        # sniffed, so that a value whose OWN TEXT begins with `f"` cannot be
        # confused with one.
        if _dq3 not in _merged:
            return StringLiteral('f' + _dq3 + _merged + _dq3, line=line, col=col,
                                 is_interpolated=True)
        if _sq3 not in _merged:
            return StringLiteral('f' + _sq3 + _merged + _sq3, line=line, col=col,
                                 is_interpolated=True)
        # Both triple-quote runs present in the content (extraordinarily
        # rare) — fall back to a double-quoted wrap with `"` escaped.
        return StringLiteral('f"' + _merged.replace('"', '\\"') + '"',
                             line=line, col=col, is_interpolated=True)

    def _parse_primary(self):
        t = self._peek()
        line, col = t.line, t.col
        if t.kind == "INT":
            # Strip numeric-literal underscore separators before `int(...)`:
            # the compiled backend's `int(str, base)` lowers to a C
            # `strtol`-style parse that STOPS at `_`, so `0x2000_0000`
            # parsed as `0x2000` (8192) where the reference gives
            # 536870912 (repro: std/test/builtin/test_print_long_string's
            # `print("*" * 0x2000_0000)`).
            self._advance(); return IntLiteral(_parse_int_literal(t.value), line=line, col=col, raw=t.value)
        if t.kind == "FLOAT":
            self._advance(); return FloatLiteral(float(t.value.replace('_', '')), line=line, col=col)
        if t.kind == "IMAG":
            self._advance(); return ImagLiteral(float(t.value[:-1]), line=line, col=col)
        if t.kind == "KW" and t.value in ("True","False"):
            self._advance()
            return BoolLiteral(t.value == "True", line=line, col=col)
        if t.kind == "STRING" and t.value.startswith("`"):
            # Backtick-quoted identifier reference (e.g. `` `3` `` naming a
            # comptime var whose spelling isn't a valid bare NAME token, or
            # `` `6bit` ``-style names — see _parse_comptime/_parse_param's
            # matching special-cases, which store the name INCLUDING its
            # backticks). Without this, a reference (as opposed to a
            # declaration site) fell through to the generic STRING branch
            # below and became a StringLiteral whose value was the literal
            # text "`3`", backticks and all — so e.g. `"mojo" * \`3\`` tried
            # to multiply a str by a str instead of by the int the comptime
            # var held.
            self._advance()
            return IdentExpr(t.value, line=line, col=col)
        if t.kind == "STRING":
            _raw0 = self._advance().value
            # Implicit string concatenation (adjacent literals). When any
            # participant is an f/t-string the run must be merged into ONE
            # f-string by unwrapping each literal's own prefix+quotes —
            # gluing the raw f-string tokens (`f'a'f'b'`) leaves inner
            # delimiters as literal text once codegen strips only the
            # outer pair.
            if self._peek().kind == "STRING":
                _raws = [_raw0]
                while self._peek().kind == "STRING":
                    _raws.append(self._advance().value)
                return self._merge_string_literals(_raws, line, col)
            if self._raw_string_is_bytes(_raw0):
                return StringLiteral(self._decode_bytes_literal(_raw0),
                                     line=line, col=col, is_bytes=True)
            return StringLiteral(self._strip_string_prefix_and_quotes(_raw0),
                                 line=line, col=col,
                                 is_raw=self._raw_string_is_raw(_raw0),
                                 is_interpolated=self._raw_string_is_ftstring(_raw0))
        if t.kind == "LBRACKET": return self._parse_list_or_compr()
        if t.kind == "LBRACE": return self._parse_dict_or_set()
        if t.kind == "LPAREN":
            self._advance()
            # Allow an ownership/convention prefix inside a parenthesized binding
            # target, e.g. tuple unpacking `(var x), (ref y) = ...`.
            # Disambiguation: real Python has no `var`/`ref`/etc. keyword, so
            # any of _CONV_KWS is also a perfectly ordinary identifier (e.g. a
            # parameter named `var`). A genuine parenthesized binding target
            # is always exactly `(CONV_KW name)` -- the keyword, one name-like
            # token, then the closing RPAREN -- so also require peek(2) to be
            # RPAREN before committing to the convention-prefix reading.
            # Without this, `(var not in lst)` (PARSE_FAIL_conv_kw_prefix_misfires_on_var_not_in)
            # wrongly swallowed `var` as a bogus prefix (peek(1)=KW('not')
            # satisfied the old NAME-or-KW check), leaving `not in lst`
            # dangling and eventually failing with "Expected RPAREN got
            # NAME('lst')".
            if (self._peek().kind == "KW" and self._peek().value in self._CONV_KWS
                    and self._peek(1).kind in ("NAME", "KW")
                    and self._peek(2).kind == "RPAREN"):
                self._advance()
            if self._peek().kind == "RPAREN":
                self._advance(); return TupleExpr(elements=[], line=line, col=col)
            # `_parse_expr_or_yield` (not plain `_parse_expr(0)`): parens are
            # exactly the grouping real Python requires to use `yield`/
            # `yield from` as a sub-expression (e.g. a call argument), so
            # `(yield x)` must be recognized here even though the LPAREN
            # itself belongs to a call/tuple/grouping, not a statement.
            first = self._parse_expr_or_yield()
            if self._is_kw("for"):
                # `_parse_generators` (plural) handles chained clauses:
                # (x for row in rows for x in row) — a single `for` clause
                # left the trailing `for` unconsumed → "Expected RPAREN got for".
                gens = self._parse_generators()
                self._expect("RPAREN")
                return Comprehension(kind="generator", element=first, generators=gens, line=line, col=col)
            if self._peek().kind == "COMMA":
                elems = [first]
                while self._peek().kind == "COMMA":
                    self._advance()
                    if self._peek().kind == "RPAREN": break
                    elems.append(self._parse_expr(0))
                self._expect("RPAREN")
                return TupleExpr(elements=elems, line=line, col=col)
            self._expect("RPAREN")
            return first
        if t.kind in ("NAME", "KW"):
            self._advance()
            if t.value == "lambda" and t.kind == "NAME" and (
                self._peek().kind == "COLON"
                or self._peek().kind == "NAME"
                # LBRACKET/LPAREN/LBRACE are the Mojo lambda's own parameter
                # block, capture list and parameter list; `lambda` is a real
                # Python keyword and so is never an ordinary identifier, which
                # is what makes it safe to treat these as a lambda rather than
                # as a call/index on a variable.
                or self._peek().kind in ("LBRACKET", "LPAREN", "LBRACE")
                or (self._peek().kind == "OP" and self._peek().value in ("*", "**"))
            ):
                return self._parse_lambda()
            return IdentExpr(t.value, line=line, col=col)
        if t.kind == "DOT" and self._peek(1).kind == "DOT" and self._peek(2).kind == "DOT":
            self._advance(); self._advance(); self._advance()
            return EllipsisLiteral(line=line, col=col)
        # Dot-relative value reference: `.always`, `.uint64`, `.of_bytes[128]()`.
        # Only reachable where an expression is expected, so a DOT here can
        # never be the attribute access `_parse_postfix` handles — that one
        # always has a preceding primary. Requiring a NAME (or a backtick-
        # quoted name) after the dot is what keeps `...` above, a float like
        # `.5` (which lexes as a NUMBER, not DOT NUMBER) and a genuine error
        # out of this branch.
        if t.kind == "DOT" and (self._peek(1).kind in ("NAME", "KW")
                                or (self._peek(1).kind == "STRING"
                                    and self._peek(1).value.startswith("`"))):
            self._advance()          # the leading dot
            path = self._ident()
            # `.a.b` — a chain, kept as one dotted string for the same reason
            # the leading dot is: no component is a real binding on its own.
            while self._peek().kind == "DOT" and (
                    self._peek(1).kind in ("NAME", "KW")
                    or (self._peek(1).kind == "STRING"
                        and self._peek(1).value.startswith("`"))):
                self._advance()
                path += "." + self._ident()
            return DottedLiteral(path=path, line=line, col=col)
        raise SyntaxError(f"{self._loc(t)}Unexpected {t.kind}({t.value!r})")

    def _parse_lambda_bracket_params(self):
        """`lambda [i: Int, ...]` — the generic/comptime parameter block in
        front of a lambda's parameter list. Returns `(name, type_ann_or_None)`
        pairs, in source order.

        Same skip-the-body shape as a function's bracket parameters elsewhere
        (`_skip_bracketed`), except the names and their annotations are kept
        rather than discarded, because for a lambda they are the only place the
        parameterization is recorded at all.
        """
        self._expect("LBRACKET")
        out = []
        self._skip_newlines()
        while self._peek().kind not in ("RBRACKET", "EOF"):
            if self._peek().kind == "COMMA":
                self._advance(); self._skip_newlines(); continue
            if self._peek().kind in ("NAME", "KW"):
                nm = self._advance().value
                ann = None
                if self._peek().kind == "COLON":
                    self._advance()
                    ann = self._parse_type_ann()
                # A default (`[i: Int = 4]`) — parsed and dropped; a lambda's
                # generic parameter default is not something the backends read.
                if self._peek().kind == "ASSIGN":
                    self._advance()
                    self._parse_expr(0)
                out.append((nm, ann))
            else:
                t = self._peek()
                raise SyntaxError(
                    f"{self._loc(t)}Unexpected {t.kind}({t.value!r}) in lambda "
                    f"parameter list")
            self._skip_newlines()
        self._expect("RBRACKET")
        return out

    def _parse_lambda_captures(self):
        """`{ref}` / `{imm key}` — the capture list between a lambda's parameter
        list and its `->`. Returns the text between the braces, whitespace-
        normalised (the token-text convention `_parse_decorator_args` uses for
        a brace-delimited clause list), and consumes the braces."""
        self._expect("LBRACE")
        parts = []
        depth = 0
        while True:
            t = self._peek()
            if t.kind == "RBRACE" and depth == 0:
                self._advance()
                break
            if t.kind == "EOF":
                break
            if t.kind == "LBRACE":
                depth += 1
            elif t.kind == "RBRACE":
                depth -= 1
            if t.kind not in ("NEWLINE", "INDENT", "DEDENT"):
                parts.append(t.value)
            self._advance()
        return " ".join(parts)

    def _parse_lambda_paren_params(self):
        """`lambda (a, b: Int = 1, *args, **kw)` — a parenthesised parameter
        list, LPAREN already current. Returns `(params, param_types)` where
        `params` is the 2-tuple list `LambdaExpr` has always carried and
        `param_types` is the positionally aligned annotation list.

        A COLON after a parameter NAME is a type annotation, not the lambda's
        body separator — the distinction the old token loop could not make,
        because it scanned for the first COLON and a typed parameter's own
        annotation colon ended the parameter list early.
        """
        params = []
        param_types = []
        self._advance()          # consume LPAREN
        self._skip_newlines()
        while self._peek().kind not in ("RPAREN", "EOF"):
            if self._peek().kind == "COMMA":
                self._advance(); self._skip_newlines(); continue
            if self._peek().kind == "RPAREN":
                break
            star = ""
            if (self._peek().kind == "OP"
                    and self._peek().value in ("*", "**")):
                star = self._advance().value
            ann = None
            if self._peek().kind in ("NAME", "KW"):
                pname = self._advance().value
                if self._peek().kind == "COLON":
                    self._advance()
                    ann = self._parse_type_ann()
                default = None
                if self._peek().kind == "ASSIGN":
                    self._advance()
                    default = self._parse_expr(0)
                params.append((star + pname, default))
                param_types.append(ann)
            elif star:
                # A bare `*` or `**` with no name after it.
                params.append((star, None))
                param_types.append(None)
            else:
                t = self._peek()
                raise SyntaxError(
                    f"{self._loc(t)}Unexpected {t.kind}({t.value!r}) in lambda "
                    f"parameter list")
            self._skip_newlines()
            if self._peek().kind == "COMMA":
                self._advance(); self._skip_newlines()
        self._skip_newlines()
        return params, param_types

    def _parse_lambda(self):
        """Parse `lambda`, keyword already current and verified as a lambda.

        Three parameter spellings, told apart by what follows the keyword:

          lambda x, y: ...            bare, unannotated (Python's own)
          lambda (i: Int) -> T: ...   parenthesised, annotated
          lambda [i: Int]() -> T: ... comptime block, then empty parens

        plus two optional clauses that sit between the parameter list and the
        body: a `{ref}`/`{imm key}` capture list, and a `-> T` return
        annotation. Neither exists in Python's lambda grammar, so both are
        consumed explicitly here rather than left to the expression parser,
        which would read `{ref}` as a set display and `->` as a syntax error.
        """
        comptime_params = []
        if self._peek().kind == "LBRACKET":
            comptime_params = self._parse_lambda_bracket_params()

        params = []
        param_types = []
        if self._peek().kind == "LPAREN":
            params, param_types = self._parse_lambda_paren_params()
            self._expect("RPAREN")
        else:
            # Bare parameter list — the pre-existing loop, kept verbatim in
            # behaviour: scan to the COLON that opens the body.
            while self._peek().kind != "COLON":
                if self._peek().kind in ("NEWLINE", "INDENT", "DEDENT"):
                    self._advance(); continue
                if self._peek().kind == "RPAREN": break
                if self._peek().kind == "OP" and self._peek().value == "/":
                    # Positional-only parameter separator (PEP 570), also valid in lambdas.
                    self._advance()
                    if self._peek().kind == "COMMA": self._advance()
                    continue
                if self._peek().kind == "OP" and self._peek().value == "*":
                    self._advance()
                    if self._peek().kind in ("NAME", "KW"):
                        params.append(("*" + self._advance().value, None))
                    continue
                if self._peek().kind == "OP" and self._peek().value == "**":
                    self._advance()
                    if self._peek().kind in ("NAME", "KW"):
                        params.append(("**" + self._advance().value, None))
                    continue
                if self._peek().kind in ("NAME", "KW"):
                    pname = self._advance().value
                    default = None
                    if self._peek().kind == "ASSIGN":
                        self._advance()
                        default = self._parse_expr(0)
                    params.append((pname, default))
                elif self._peek().kind == "COMMA":
                    pass
                else:
                    t = self._peek()
                    raise SyntaxError(f"{self._loc(t)}Unexpected {t.kind}({t.value!r}) in lambda parameter list")
                if self._peek().kind == "COMMA": self._advance()

        captures = ''
        if self._peek().kind == "LBRACE":
            captures = self._parse_lambda_captures()
        return_type = None
        if self._peek().kind == "ARROW":
            self._advance()
            if self._is_kw("ref"):
                self._advance()
                if self._peek().kind == "LBRACKET":
                    self._skip_bracketed()
            return_type = self._parse_type_ann()
            while self._peek().kind in ("NAME", "KW") and self._peek().value in (
                    "unified", "register_passable", "capturing", "raises"):
                self._advance()
        self._expect("COLON")
        body = self._parse_expr(0)
        return LambdaExpr(params=params, body=body,
                          param_types=param_types,
                          return_type=return_type,
                          comptime_params=comptime_params,
                          captures=captures)

    def _parse_list_or_compr(self):
        self._expect("LBRACKET")
        if self._peek().kind == "RBRACKET":
            self._advance(); return ListExpr(elements=[])
        first = self._parse_expr(0)
        if self._is_kw("for"):
            gens = self._parse_generators()
            self._expect("RBRACKET")
            return Comprehension(kind="list", element=first, generators=gens)
        elems = [first]
        while self._peek().kind == "COMMA":
            self._advance()
            if self._peek().kind == "RBRACKET": break
            elems.append(self._parse_expr(0))
        self._expect("RBRACKET")
        return ListExpr(elements=elems)

    def _parse_dict_entry(self):
        """Parse one entry after the first in a `{...}` dict literal: either
        a `**expr` unpack spread (returned as `(UnaryOp, None)`, mirroring
        how the first-entry spread case represents it — see
        `_parse_dict_or_set`) or an ordinary `key: value` pair."""
        if self._peek().kind == "OP" and self._peek().value == "**":
            return (self._parse_expr(0), None)
        k = self._parse_expr(0); self._expect("COLON"); v = self._parse_expr(0)
        return (k, v)

    def _parse_dict_or_set(self):
        self._expect("LBRACE")
        if self._peek().kind == "RBRACE":
            self._advance(); return DictExpr(pairs=[])
        first = self._parse_expr(0)
        # Check for struct initializer syntax: {field = value, ...}
        if self._peek().kind == "ASSIGN":
            # This is a struct initializer with named fields
            self._advance()  # skip =
            self._parse_expr(0)  # parse and discard field value
            # Skip any remaining fields
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind == "RBRACE": break
                self._parse_expr(0)  # skip field name
                if self._peek().kind == "ASSIGN": self._advance()
                self._parse_expr(0)  # skip field value
            self._expect("RBRACE")
            # Return as dict for now (struct init not semantically tracked)
            return DictExpr(pairs=[])
        if self._peek().kind == "COLON":
            self._advance(); val = self._parse_expr(0)
            if self._is_kw("for"):
                gens = self._parse_generators()
                self._expect("RBRACE")
                return Comprehension(kind="dict", element=first, key=val, generators=gens)
            pairs = [(first, val)]
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind == "RBRACE": break
                pairs.append(self._parse_dict_entry())
            self._expect("RBRACE")
            return DictExpr(pairs=pairs)
        # Dict-unpack spread as the first entry: `{**a, **b}` (PEP 448). `**`
        # never carries a COLON (there's no key expression to its left), so
        # this must be checked before falling through to the set-literal
        # path below — otherwise `{**a, **b}` gets misclassified as a set of
        # two `**`-UnaryOp "elements", which then crashes in eval_UnaryOp
        # instead of building a dict (see
        # INTERP_dict_double_star_unpack_runtime).
        if isinstance(first, UnaryOp) and first.op == "**":
            pairs = [(first, None)]
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind == "RBRACE": break
                pairs.append(self._parse_dict_entry())
            self._expect("RBRACE")
            return DictExpr(pairs=pairs)
        if self._is_kw("for"):
            gens = self._parse_generators()
            self._expect("RBRACE")
            return Comprehension(kind="set", element=first, generators=gens)
        # Handle named field if first element is followed by =
        if self._peek().kind == "ASSIGN":
            self._advance(); self._parse_expr(0)
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind == "RBRACE": break
                self._parse_expr(0)  # field name or value
                if self._peek().kind == "ASSIGN": self._advance(); self._parse_expr(0)
            self._expect("RBRACE")
            return DictExpr(pairs=[])
        elems = [first]
        while self._peek().kind == "COMMA":
            self._advance()
            if self._peek().kind == "RBRACE": break
            e = self._parse_expr(0)
            # Handle named field (positional then named): {ctx, field = value}
            if self._peek().kind == "ASSIGN":
                self._advance(); self._parse_expr(0)
                while self._peek().kind == "COMMA":
                    self._advance()
                    if self._peek().kind == "RBRACE": break
                    self._parse_expr(0)
                    if self._peek().kind == "ASSIGN": self._advance(); self._parse_expr(0)
                break
            elems.append(e)
        self._expect("RBRACE")
        return SetExpr(elements=elems)

    @staticmethod
    def _rewrap_generator_group(inner: str, saw_comma: bool) -> str:
        """One level of a target group: `(inner)`, `(inner,)` or `inner`.

        The 1-tuple spelling is `(a,)`, so a group whose slots are exactly ONE
        needs the comma back when the text lost it, and a group of two or more
        must not get one. Split out because BOTH joins in
        `_parse_generator_target` ask it — the parenthesis one and the list
        one — and they are the same question: a nested `for (i, (j,)) in ...`
        whose inner comma is dropped here binds the whole inner pair to `j`.
        """
        if not saw_comma:
            return inner
        return f"({inner},)" if len(target_slots(inner)) == 1 else f"({inner})"

    def _parse_generator_target(self):
        """A comprehension/generator `for` clause's target — the sibling
        representation to `_parse_unpack_target`'s (see its docstring for
        the differences: here a bare comma list keeps NO wrapping parens, so
        `for a, b in ...` is the literal string `"a, b"`).

        Returns `(target, saw_comma)` where `saw_comma` says a comma was
        consumed AT THIS LEVEL, which is what distinguishes a 1-tuple from
        a parenthesised single name — the same disambiguation
        `_parse_unpack_target` makes, for the same reason and with the same
        spelling: `for (a) in b:` binds the whole item while `for (a,) in
        b:` unpacks its single element, and both used to reduce to the
        IDENTICAL string `"(a)"`.

        So a parenthesised group that consumed no comma unwraps to its bare
        text, exactly as `_parse_unpack_target` does, and a 1-element group
        that did keeps its parens AND its trailing comma. A trailing comma at
        the top level (`for a, in ...`) therefore produces `"(a,)"`, not the
        bare `"a"` it used to — that bare form was the same bug wearing a
        different spelling.

        The trailing comma is KEPT in the string, and that is a decision this
        function shares with `_parse_unpack_target`: `'(a,)'` and `'(a)'` are
        different targets and the comma is the only thing Python itself
        distinguishes them by, so `for_target_is_tuple` — the ONE reader of
        that difference — has to be able to see it. Emitting `"(a)"` here for a
        top-level trailing comma, as an earlier version of this function did,
        makes it indistinguishable from the parenthesised single name and puts
        the two parsers at odds with each other for the same source line."""
        t = self._peek()
        saw_comma = False
        if t.kind == "LPAREN":
            self._advance()
            sub, sub_comma = self._parse_generator_target()
            self._expect("RPAREN")
            # `f"({sub},)"` when the inner group was a 1-TUPLE, `f"({sub})"`
            # when it was a longer tuple, and the bare text when it consumed no
            # comma at all (the parenthesised single NAME). `for (a,) in ...`
            # reaches here with `sub == 'a'` and `sub_comma` True, and
            # re-wrapping it as `'(a)'` produced a target indistinguishable
            # from the parenthesised single NAME — so `[y for (y,) in xs]` bound
            # each whole item to `y` and printed `[(1,), (2,)]` where CPython
            # prints `[1, 2]`, on the ONE spelling `for_target_is_tuple` exists
            # to tell apart.
            #
            # ONE slot, not merely "does not end in a comma": `for (a, b) in
            # ...` also has `sub_comma` True, and its `sub` is `a, b`, whose
            # last element is `b`, so that test alone appended a comma to a
            # two-slot target and made `for (a, (b, c))` a 1-tuple wrapping its
            # pair. The trailing comma a 1-tuple needs is the one a
            # ONE-element slot list cannot carry, and `target_slots` is what
            # says how many there are.
            #
            # Per-slot, not just for the outermost group: the same question is
            # asked again for every nested group by the recursion, so a nested
            # 1-tuple's comma has to be re-appended at THIS level too. The
            # list-form append below is the other half of that — a nested
            # `(b,)` reached through the `, {inner}` join would otherwise lose
            # its comma here and come out as the parenthesised name `(b)`.
            target = self._rewrap_generator_group(sub, sub_comma)
            saw_comma = sub_comma
        elif t.kind == "LBRACKET":
            # List-pattern unpacking target: `for [off] in ...`
            self._advance()
            sub, _ = self._parse_generator_target()
            self._expect("RBRACKET")
            target = f"[{sub}]"
            saw_comma = True
        elif t.kind in ("NAME", "KW"):
            target = self._advance().value
        elif t.kind == "OP" and t.value == "*":
            # Extended unpacking in a comprehension target — `[r for first,
            # *r in pairs]` is ordinary Python. This parser had no arm for
            # the `*` and fell to `self._expect("NAME")`, so the whole
            # comprehension was a SyntaxError ("Expected NAME got OP('*')")
            # on BOTH the interpreter and the compiled path, while the
            # statement path's own `_parse_unpack_target` has spelled it
            # "*name" in the same target string all along.
            #
            # The representation is the STATEMENT path's, deliberately: one
            # spelling for both, read by the same three consumers
            # (`for_target_names` keeps the star, `boundnames` strips it for
            # the bound-name set, the loop/comprehension lowerings find it by
            # position — see `mojo/middle/loops_shared.starred_slot_index`).
            self._advance()
            target = "*" + self._expect("NAME").value
        else:
            target = self._expect("NAME").value
        # A TRAILING comma at this level makes the pattern a 1-tuple, which is
        # a different target from a parenthesised single name: `for (a,) in
        # xs` unpacks each item, `for (a) in xs` binds the whole item. Both
        # used to come out as the same spelling (`'(a)'` for the parenthesised
        # form, and — dropping the comma entirely — `'a'` for the bare one),
        # so every consumer read "is there a comma?" as NO for a 1-tuple and
        # bound the whole item: a wrong answer with no diagnostic. The comma is
        # kept here and read by `for_target_is_tuple`, which is the only
        # reader of the difference; see the `_parse_unpack_target` note.
        #
        # Two spellings of the same fix were written independently, and this is
        # the survivor. The other kept a `trailing_comma` flag and appended a
        # bare `","` to the target string at the end (`for a, in ...` -> `"a,"`);
        # this one wraps the group in the parens that make it a tuple target
        # (`-> "(a)"`) and reports the fact as a second return value,
        # `saw_comma`, so the CALLER decides rather than the string's spelling.
        # Both feed `for_target_is_tuple` the same answer -- the parenthesised
        # form is unwrapped and then found to end in a comma -- but only this
        # one also distinguishes `for (a,) in b:` from `for (a) in b:`, which
        # the trailing-comma spelling answers identically for a bare `a`, and
        # that distinction is the whole subject of this function.
        while self._peek().kind == "COMMA":
            saw_comma = True
            self._advance()
            if self._is_kw("in"):
                # Trailing comma at the TOP level: `for a, in ...` is a
                # 1-tuple, so it needs the parens that make the string a
                # tuple target — AND the comma, which is what
                # `for_target_is_tuple` reads to tell it from `for (a) in b:`.
                # No comma in the source and none in the string.
                target = f"({target})" if "," in target else f"({target},)"
                break
            # Trailing comma inside a paren/bracket pattern: `(fpath,)` /
            # `[off,]` — leave the closer for the caller's _expect.
            if self._peek().kind in ("RPAREN", "RBRACKET"):
                break
            sub_t = self._peek()
            if sub_t.kind == "LPAREN":
                self._advance()
                inner, inner_comma = self._parse_generator_target()
                self._expect("RPAREN")
                target += f", {self._rewrap_generator_group(inner, inner_comma)}"
            elif sub_t.kind in ("NAME", "KW"):
                target += ", " + self._advance().value
            elif sub_t.kind == "OP" and sub_t.value == "*":
                # The same extended-unpacking slot the top-level arm above
                # takes, in the position AFTER a comma — which is where
                # `[r for first, *r in pairs]` puts it.
                self._advance()
                target += ", *" + self._expect("NAME").value
            else:
                target += ", " + self._expect("NAME").value
        return target, saw_comma

    def _parse_generator(self):
        self._expect("KW", "for")
        target, _ = self._parse_generator_target()
        self._expect("KW", "in")
        iterable = self._parse_expr(1)
        conditions = []
        while self._is_kw("if"):
            self._advance(); conditions.append(self._parse_expr(1))
        return Generator(target=target, iterable=iterable, conditions=conditions)

    def _parse_generators(self):
        """Parse one or more chained `for ... in ... [if ...]` clauses, as in
        nested comprehensions: {a*b for a in xs for b in ys}."""
        gens = [self._parse_generator()]
        while self._is_kw("for"):
            gens.append(self._parse_generator())
        return gens

    def _parse_struct_params_as_fields(self) -> list:
        """Parse struct parameter block [name: Type = default, ...] as VarDecl fields.
        Handles //, * separators and nested brackets in type annotations and defaults."""
        self._expect("LBRACKET")
        fields = []
        while True:
            t = self._peek()
            if t.kind in ('RBRACKET', 'EOF'):
                self._advance()
                break
            # Skip positional-only (//) and keyword-only (*) separators
            if t.kind == 'OP' and t.value in ('//', '*'):
                self._advance()
                if self._peek().kind == 'COMMA':
                    self._advance()
                continue
            if t.kind == 'COMMA':
                self._advance()
                continue
            # Try to parse: name: Type [= default]
            if t.kind == 'NAME':
                name = t.value
                self._advance()
                if self._peek().kind == 'COLON':
                    self._advance()  # consume ':'
                    type_ann = self._parse_type_ann()
                    # Skip optional default value ('=' tokenizes as ASSIGN)
                    if self._peek().kind in ('EQUAL', 'ASSIGN') or (
                            self._peek().kind == 'OP' and self._peek().value == '='):
                        self._advance()  # consume '='
                        # Skip default value expression (balanced brackets)
                        depth = 0
                        while True:
                            pk = self._peek()
                            if pk.kind == 'EOF':
                                break
                            if pk.kind in ('LPAREN', 'LBRACKET', 'LBRACE'):
                                depth += 1
                                self._advance()
                            elif pk.kind in ('RPAREN', 'RBRACE'):
                                depth -= 1
                                self._advance()
                            elif pk.kind == 'RBRACKET':
                                if depth <= 0:
                                    break
                                depth -= 1
                                self._advance()
                            elif pk.kind == 'COMMA' and depth == 0:
                                break
                            else:
                                self._advance()
                    # `name: TraitName` is a generic TYPE parameter (T conforms
                    # to the trait), not a comptime VALUE parameter — it must
                    # NOT become a real field, or @fieldwise_init's synthesized
                    # constructor gets an extra phantom parameter (see
                    # __init__'s _known_traits comment). `_struct_param_is_bound`
                    # is that test, and it has a second arm this did not.
                    if not self._struct_param_is_bound(type_ann):
                        fields.append(VarDecl(name=name, type_ann=type_ann, value=None))
                else:
                    # No colon — skip this token (could be a bare type name)
                    pass
            else:
                self._advance()  # skip unexpected token
        return fields

    def _struct_param_is_bound(self, type_ann: str) -> bool:
        """Is this struct-parameter annotation a comptime BOUND, not a field type?

        Two shapes, and the second one is the defect this exists to close.

          * a single bare name this unit knows is a TRAIT (`T: Movable`).
            Unchanged, including its deliberate conservatism about a trait
            declared in another module: `origin: Origin` and `level: Level`
            stay fields, because this compiler cannot tell a stdlib enum from
            a trait without reading that module.
          * a CONJUNCTION at bracket depth zero (`T: Copyable & Comparable &
            Deinitable`). Every conjunct is a bound whatever it is named, and
            the reason needs no table at all: **`&` cannot occur in a data
            type.** There is no spelling of a struct's storage whose declared
            type contains `&` — it is the trait-constraint operator and
            nothing else — so an annotation carrying one describes a constraint
            on the type parameter and cannot be describing per-instance
            storage. Depth zero because a `&` inside a subscript belongs to
            whatever that subscript spells.

        Why the second arm was needed, measured rather than argued: the first
        arm compared the WHOLE annotation against a set of trait NAMES, so
        `Copyable & Comparable` was not in the set and the parameter became a
        real `VarDecl` field. Fourteen structs in the new-modular stdlib spell
        a bound that way, and every one of them then measured one field more
        than it has. `std/collections/binary_heap.mojo`'s `BinaryHeap` is the
        one this was found on: `BinaryHeap[T: Copyable & Comparable &
        Deinitable]` has exactly one field, `_data`, and it measured two —
        `T` and `_data` — so `formal/model.py`'s `struct_is_one_field` said no,
        the receiver became a FRAME ADDRESS of a two-word block instead of the
        one word it is, and `len(self._data)` inside `__len__` became a read of
        a frame slot whose value nothing establishes, refused by name
        (`frame_slot_value_refusal`: "this slot's DECLARED type is
        'List[Self.T]' … what is missing is the VALUE"). The phantom field is
        upstream of that refusal: the value was missing because the slot was
        read as a frame slot at all.

        So the two arms are ordered cheapest-first and neither is a fallback
        for the other: the first is a NAME test over a table that can be
        incomplete, the second is a SYNTAX test that cannot be.
        """
        depth = 0
        for ch in type_ann:
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            elif ch == '&' and depth == 0:
                return True
        return type_ann.lstrip('*') in self._known_traits

    def _skip_bracketed(self):
        """Consume a balanced [...] block."""
        self._expect("LBRACKET")
        depth = 1
        while depth > 0:
            t = self._advance()
            if t.kind == "LBRACKET":
                depth += 1
            elif t.kind == "RBRACKET":
                depth -= 1
            elif t.kind == "EOF": break

    def _parse_generic_params_capture(self):
        """Consume a `def f[dtype: DType, width: SIMDSize, //, ...](...)`
        generic/comptime parameter block like `_skip_bracketed`, but also
        return the parameter names in declaration order together with the
        DECLARED DEFAULTS of the ones written `name = expr` — enough for
        the interpreter to bind a call-site subscript (`f[Int32]()`) to
        names by position, e.g. so the function body can read `dtype` as a
        plain value, and to answer `f[T=Int]()` for a parameter the bracket
        does not supply (`def f[T, y=0, *, linux=0]()`'s `y`).

        Returns `(names, defaults, annotations)`: `defaults` is
        `{name: expr_node}` for the parameters that declare one, and
        `annotations` is `{name: annotation_text}` for the ones written
        `name: Type`. The annotations were the missing third and they are what
        `formal/model.py::param_annotation` asks about a bracket parameter -- the
        bracket block used to keep the NAME and throw the TYPE away, so nothing in
        the tree could say what `keys` held in `def f[T: AnyType, keys: List[T]]`.
        The defaults are kept apart from
        `FunctionDef.param_defaults` because that table is the RUNTIME
        parameter list's, and its LENGTH is the trailing-default offset
        arithmetic's input (`_trailing_default_at`) — a comptime default in
        there would shift every runtime default's slot.

        The default's value is read by `_parse_bracket_param_default`, which
        takes the token span between the `=` and the next top-level COMMA or
        RBRACKET — so a `=` is only read as a default at bracket depth 1, and
        the parameter list's own punctuation after the value (notably the
        comptime/runtime separator `//`) is not fed to the expression parser.
        """
        self._expect("LBRACKET")
        names = []
        defaults = {}
        annotations = {}
        depth = 1
        expect_name = True
        while depth > 0:
            t = self._peek()
            # Parens/braces nest TOO: a FUNCTION-typed bracket parameter's
            # annotation (`f_key: def(Self.K, mut Some[Writer]) thin`)
            # carries commas inside `(...)` that must NOT be treated as
            # parameter separators — otherwise the type's argument list
            # leaks phantom "parameter" names (`mut`, `List`, ...) into
            # comptime_params, and every consumer keying on declaration
            # order/count (call-site bracket-argument mapping via
            # _method_comptime_param_order) mis-aritificates the call.
            if t.kind in ("LPAREN", "LBRACE"):
                self._advance(); depth += 1; continue
            if t.kind in ("RPAREN", "RBRACE"):
                self._advance(); depth -= 1; continue
            if t.kind == "LBRACKET":
                self._advance(); depth += 1; continue
            if t.kind == "RBRACKET":
                self._advance(); depth -= 1; continue
            if t.kind == "EOF":
                break
            if t.kind == "COMMA" and depth == 1:
                self._advance(); expect_name = True; continue
            if depth == 1 and expect_name and t.kind in ("NAME", "KW"):
                _nm = t.value
                names.append(_nm)
                self._advance()
                expect_name = False
                if self._peek().kind == "COLON":
                    self._advance()
                    annotations[_nm] = self._capture_bracket_param_annotation()
                    continue
                if self._peek().kind == "ASSIGN":
                    self._advance()
                    defaults[_nm] = self._parse_bracket_param_default()
                continue
            self._advance()
        return names, defaults, annotations

    def _capture_bracket_param_annotation(self) -> str:
        """The DECLARED TYPE of a bracketed parameter, as source text.

        Consumes tokens until the next top-level COMMA or RBRACKET and returns
        them joined with spaces -- the same span discipline as
        `_parse_bracket_param_default`, and for the same reason: what FOLLOWS is
        parameter-list punctuation (`//`, `,`, `]`), not part of the type. Text
        and not a parsed expression because a type is not an expression here, and
        the consumers (`model.param_annotation` -> `declared_type_kind`,
        `model.optional_receiver_types`) reduce it from text.

        The span is consumed whether or not anybody wants it, so the caller's
        loop resumes at the separator either way; an EMPTY annotation (`f[T: ]`)
        yields `""` and every reader treats that as absent, which is the same
        answer the parameter had before this existed.
        """
        parts = []
        depth = 1
        while True:
            t = self._peek()
            if t.kind == "EOF":
                break
            if t.kind == "COMMA" and depth == 1:
                break
            if t.kind == "RBRACKET" and depth == 1:
                break
            if t.kind in ("LBRACKET", "LPAREN", "LBRACE"):
                depth += 1
            elif t.kind in ("RBRACKET", "RPAREN", "RBRACE"):
                depth -= 1
            parts.append(self._advance().value)
        # Tokens are joined with a space (the `_capture_bracketed_text` rule: a
        # token's `.value` is its exact source substring and joining without a
        # separator would fuse `Self` and `.` into `Self.`), and then the space
        # is taken back OFF the punctuation a type argument list is written with
        # -- so `List [ T ]` is stored as `List[T]`, which is the spelling every
        # reader of an annotation in this tree reduces (`model.
        # annotation_base_name` strips the arguments and then requires an
        # IDENTIFIER, and `List ` is not one). Only the brackets and the comma
        # are tightened; spaces between words are left, because
        # `borrowed List[T]` and a function type's `def(A, B) thin` both need
        # them to stay words apart.
        text = " ".join(parts).strip()
        for ch in "[],":
            text = text.replace(" " + ch, ch).replace(ch + " ", ch)
        return text

    def _parse_bracket_param_default(self):
        """The declared default of a bracketed (`def f[T, y=0, ...]`)
        parameter, parsed from the token span that runs from here to the next
        top-level COMMA or RBRACKET. The span is consumed either way, so the
        caller's loop resumes at the separator.

        Spanned, not parsed in place, because what FOLLOWS the value is
        parameter-list punctuation and is not part of it: the
        comptime/runtime separator `//` (`def f[T: Int //, n: Int]`) lexes as
        the floor-div OPERATOR, so an in-place `_parse_expr` swallows it
        looking for a right operand and dies on the `,` — turning a
        declaration this function used to skip over into a SyntaxError.
        Parsing the span with a sub-parser is the same shape the rest of the
        tree uses for a bracket item that has to be a self-contained
        expression run (`myinterpreter.py`'s subscript re-parse).

        Layout tokens are dropped: a multi-line parameter list carries
        NEWLINE/INDENT/DEDENT the expression parser must not see.
        """
        _start = self._pos
        _depth = 1
        _end = _start
        while _end < len(self._tok):
            _tk = self._tok[_end]
            if _tk.kind == "EOF":
                break
            if _tk.kind in ("LPAREN", "LBRACE", "LBRACKET"):
                _depth += 1
            elif _tk.kind in ("RPAREN", "RBRACE"):
                _depth -= 1
            elif _tk.kind == "RBRACKET":
                if _depth == 1:
                    break
                _depth -= 1
            elif _tk.kind == "COMMA" and _depth == 1:
                break
            _end += 1
        _span = []
        # A trailing `//` is the comptime/runtime separator, not part of the
        # value (`def f[T = 1 //, n: Int]`), so it stays in the parameter
        # list for the caller's loop to step over — as it did before any
        # default was captured. Only a TRAILING one: `1 // 2` is a floor
        # division and keeps its operator.
        if _end > _start and self._tok[_end - 1].kind == "OP" \
                and self._tok[_end - 1].value == "//":
            _end -= 1
        for _i in range(_start, _end):
            if self._tok[_i].kind in ("NEWLINE", "INDENT", "DEDENT"):
                continue
            _span.append(self._tok[_i])
        self._pos = _end
        if _end > len(self._tok):
            self._pos = len(self._tok)
        if not _span:
            return None
        return Parser(_span).with_filename(self._filename)._parse_expr(0)

    def _skip_fn_quals(self):
        """Skip function-type qualifiers between a parameter list and `->`:
        capturing, raises, unified, register_passable, and calling-convention
        markers thin / abi("C"). Note `raises` lexes as a keyword, the rest as
        plain names, so accept both token kinds."""
        while self._peek().kind in ("NAME", "KW") and self._peek().value in (
            "capturing", "raises", "unified", "register_passable", "thin", "abi"):
            self._advance()
            # abi may take a parenthesized convention string: abi("C")
            if self._peek().kind == "LPAREN":
                self._advance()  # consume LPAREN
                depth = 1
                while depth > 0:
                    t = self._advance()
                    if t.kind == "LPAREN":
                        depth += 1
                    elif t.kind == "RPAREN":
                        depth -= 1
                    elif t.kind == "EOF": break

    def _parse_type_ann(self) -> str:
        """Parse a type annotation, including a trailing `?` optional-type suffix
        (`Token?` == `Optional[Token]`)."""
        name = self._parse_type_ann_inner()
        if self._peek().kind == "OP" and self._peek().value == "?":
            self._advance()
            name = f"Optional[{name}]"
        return name

    def _parse_type_ann_inner(self) -> str:
        """Parse a type annotation: Name or Name[TypeArgs] or Name.Member.Type[Args] or `backtick_type`."""
        # Handle * prefix for variadic/unpacking types (*Ts)
        prefix = ""
        if self._peek().kind == "OP" and self._peek().value == "*":
            prefix = "*"
            self._advance()
        # Handle `ref` or `mut` keyword prefix on type (lifetime annotation)
        if self._is_kw("ref") or self._is_kw("mut"):
            self._advance()  # drop ref/mut prefix
            # Skip lifetime parameters in brackets: ref[Origin]
            if self._peek().kind == "LBRACKET":
                self._skip_bracketed()
        # Handle backtick-quoted MLIR types (e.g., `!pop.scalar<bool>`)
        if self._peek().kind == "STRING" and self._peek().value.startswith("`"):
            return prefix + self._advance().value  # return the backtick string as-is
        # Forward-reference string annotation: `-> "TermState"`, `x: "SomeType"`
        # (PEP 484). Strip the quotes and treat the contents as the type name.
        if self._peek().kind == "STRING":
            return prefix + self._strip_string_prefix_and_quotes(self._advance().value)
        # Handle parenthesized types like () for unit type, e.g. `y: (1).__class__`
        # (a parenthesized-expression-shaped annotation, PEP 649-legal but not a
        # real type). Captured as opaque text and then, same as every other
        # branch below, falls through to the shared continuation tail (dotted-
        # name loop / call-parens / subscript loop / trailing-op consumption)
        # instead of returning immediately — see
        # PARSE_FAIL_annotation_paren_then_dot for why an early return
        # here left a trailing `.attr`/`|`/`&` continuation dangling.
        if self._peek().kind == "LPAREN":
            name = prefix + "("
            self._advance()
            depth = 1
            while depth > 0:
                t = self._advance()
                if t.kind == "LPAREN":
                    depth += 1
                    name += "("
                elif t.kind == "RPAREN":
                    depth -= 1
                    if depth > 0:
                        name += ")"
                elif t.kind == "EOF":
                    break
                else:
                    name += t.value
            name += ")"
            return self._finish_type_ann_tail(name)
        # Allow KW tokens as type names (e.g., "let", "var", "if")
        t = self._peek()
        if t.kind == "NAME": name = prefix + self._advance().value
        elif t.kind == "KW":
            kw_value = self._advance().value
            # Handle function types: def() -> ReturnType
            if kw_value == "def":
                # Skip function parameters in parentheses and brackets
                if self._peek().kind == "LBRACKET":
                    self._skip_bracketed()  # skip generic parameters [T, ...]
                if self._peek().kind == "LPAREN":
                    # Skip parameter list: consume balanced parentheses
                    self._advance()  # consume LPAREN
                    depth = 1
                    while depth > 0:
                        t = self._advance()
                        if t.kind == "LPAREN":
                            depth += 1
                        elif t.kind == "RPAREN":
                            depth -= 1
                        elif t.kind == "EOF": break
                # Skip optional qualifiers like 'capturing', 'raises', 'unified',
                # calling-convention markers 'thin'/'abi("C")', etc.
                # ('raises' lexes as a keyword, the rest as names.)
                while self._peek().kind in ("NAME", "KW") and self._peek().value in ("capturing", "raises", "unified", "register_passable", "thin", "abi"):
                    self._advance()
                    # capturing/abi may take a bracketed or parenthesized argument list
                    if self._peek().kind == "LBRACKET":
                        self._skip_bracketed()
                    if self._peek().kind == "LPAREN":
                        self._advance()  # consume LPAREN
                        depth = 1
                        while depth > 0:
                            t = self._advance()
                            if t.kind == "LPAREN":
                                depth += 1
                            elif t.kind == "RPAREN":
                                depth -= 1
                            elif t.kind == "EOF": break
                # Skip return type if present
                if self._peek().kind == "ARROW":
                    self._advance()  # skip ->
                    # Recursively parse the return type
                    return_type = self._parse_type_ann()
                    return prefix + f"def ... -> {return_type}"
                return prefix + "def"
            name = prefix + kw_value
        elif t.kind == "LBRACKET":
            # An annotation position occupied by a list-literal-shaped thing,
            # e.g. `var2: [Int, String]` — nonsensical as a real type, but
            # Python's (and Mojo's) grammar allows an arbitrary expression
            # here syntactically. Rather than aborting the whole parse, just
            # consume the balanced `[...]` opaquely (reusing the same
            # bracket-depth-aware capture used for subscript assignment
            # targets) and hand back SOME string for the annotation slot.
            # Nothing downstream gives semantic meaning to an annotation
            # string it doesn't recognize as a real type name — e.g.
            # gimple_codegen.py's `_mojo_type`/`_resolve_type` harmlessly
            # fall through to the int64_t default for unrecognized text —
            # so this is safe to leave un-type-checked.
            return self._finish_type_ann_tail(prefix + "[" + self._capture_bracketed_text() + "]")
        elif t.kind == "LBRACE":
            # An annotation position occupied by a dict/set-literal-shaped
            # thing, e.g. `-> {}:` (an empty dict literal used, legally but
            # nonsensically, as a return type — a real Python grammar
            # permissiveness case). Same opaque-capture treatment as the
            # LBRACKET case above.
            self._advance()  # consume {
            depth = 1
            parts = ["{"]
            while depth > 0:
                tok = self._advance()
                if tok.kind == "LBRACE":
                    depth += 1
                    parts.append("{")
                elif tok.kind == "RBRACE":
                    depth -= 1
                    if depth > 0: parts.append("}")
                elif tok.kind == "EOF": break
                else: parts.append(tok.value)
            parts.append("}")
            return self._finish_type_ann_tail(prefix + "".join(parts))
        elif t.kind == "DOT" and self._peek(1).kind == "DOT" and self._peek(2).kind == "DOT":
            # `...` (Ellipsis) in annotation position, e.g. `g: ...` or
            # `-> ...`. The tokenizer produces THREE separate DOT tokens for
            # `...` (there's no single ELLIPSIS token kind) — mirrors
            # _parse_primary's identical three-DOT lookahead for Ellipsis as
            # an ordinary expression. Without this case, DOT falls to the
            # generic catch-all below, which consumes only the first dot and
            # leaves the other two dangling for the parameter-list parser to
            # choke on. Annotation text is never semantically type-checked
            # downstream, so the literal string "..." is a safe, sufficient
            # representation. Also route through _finish_type_ann_tail
            # for consistency with every other branch (e.g. `g: ... | None`).
            # See PARSE_FAIL_annotation_ellipsis.
            self._advance(); self._advance(); self._advance()
            return self._finish_type_ann_tail(prefix + "...")
        else:
            # Last-resort fallback: some other single token occupies the
            # annotation position (e.g. a bare operator or literal). Consume
            # it as opaque raw text rather than aborting the parse — see the
            # LBRACKET/LBRACE cases above for why this is safe. Then, same as
            # the NAME/KW path, consume any trailing operator continuing the
            # expression (e.g. `radd: 1 + a` — a NUMBER-shaped prefix followed
            # by a binary op; see
            # PARSE_FAIL_annotation_leading_literal_trailing_op).
            return self._finish_type_ann_tail(prefix + self._advance().value)
        return self._finish_type_ann_tail(name)

    def _finish_type_ann_tail(self, name: str) -> str:
        """Shared continuation tail for `_parse_type_ann_inner`: given an
        already-captured type-shaped prefix `name` (from ANY of that
        function's branches — NAME/KW, LPAREN, LBRACKET, LBRACE, the
        three-DOT ellipsis case, or the single-token catch-all), consume
        every further continuation the token stream might hold — a dotted
        `.member` chain, a call-parens application `(...)`, chained
        `[...]`/`.attr`/`(...)` subscript/call combinations, and finally any
        trailing PEP 604 union/intersection or other stray operator via
        `_consume_trailing_annotation_ops` — and return the fully-extended
        text.

        Every branch of `_parse_type_ann_inner` now routes through here
        instead of returning its own opaquely-captured text directly. This
        was added as the fix for the fourth in a chain of annotation-parsing
        gaps found in one session (see
        PARSE_FAIL_annotation_paren_then_dot): each earlier fix
        (6ee8291, 6e6020f, bb28e80, c2933a7) patched exactly one branch to
        handle exactly one missing continuation shape (a trailing binary
        op, then specifically `|`/`&`, then LPAREN/LBRACKET/LBRACE routing
        through the op-continuation helper) — but none of those handled a
        trailing `.attr` DOT-chain after a non-NAME-shaped prefix, e.g.
        `y: (1).__class__`. Rather than patch the LPAREN branch a fifth
        time and leave LBRACKET/LBRACE/ellipsis/catch-all with the same
        latent gap for a sixth, this single shared tail is now the ONE place
        that knows how to consume a continuation, and every branch supplies
        it with its own already-parsed prefix."""
        # Support dotted type names like __mlir_type.i1 or __mlir_type.`backtick_type`
        while self._peek().kind == "DOT":
            self._advance()  # consume dot
            # Next part can be a NAME (including KW like mut, ref) or a backtick-quoted type
            if self._peek().kind == "STRING" and self._peek().value.startswith("`"):
                name += "." + self._advance().value
            elif self._peek().kind in ("NAME", "KW"):
                name += "." + self._advance().value
            else:
                name += "." + self._expect("NAME").value  # error for invalid syntax
        # Handle function call types like type_of(x)
        if self._peek().kind == "LPAREN":
            self._advance()  # (
            name += "("
            depth = 1
            while depth > 0:
                t = self._advance()
                if t.kind == "LPAREN":
                    depth += 1
                    name += "("
                elif t.kind == "RPAREN":
                    depth -= 1
                    if depth > 0:
                        name += ")"
                elif t.kind == "EOF":
                    break
                else:
                    name += t.value
            name += ")"
            # Do NOT return here; check for dotted names and subscripts after the call
            # Second dotted-name loop after function call
            while self._peek().kind == "DOT":
                self._advance()  # consume dot
                # Next part can be a NAME or a backtick-quoted type
                if self._peek().kind == "STRING" and self._peek().value.startswith("`"):
                    name += "." + self._advance().value
                else:
                    name += "." + self._expect("NAME").value
        if self._peek().kind != "LBRACKET":
            # Handle PEP 604 union types (X | Y | Z), trait intersections
            # (X & Y & Z), and any other trailing operator continuing an
            # arbitrary (non-type) expression in this annotation position.
            return self._consume_trailing_annotation_ops(name)
        # Consume [TypeArgs] and any chained subscripts, .member accesses, or
        # comptime-call applications, e.g. `_field_types_of[Self.T]()[idx]`.
        parts = [name]
        while self._peek().kind in ("LBRACKET", "DOT", "LPAREN"):
            if self._peek().kind == "DOT":
                self._advance()  # consume dot
                if self._peek().kind == "STRING" and self._peek().value.startswith("`"):
                    parts.append("." + self._advance().value)
                elif self._peek().kind in ("NAME", "KW"):
                    parts.append("." + self._advance().value)
                else:
                    break
            elif self._peek().kind == "LPAREN":
                self._advance()  # (
                parts.append("(")
                depth = 1
                while depth > 0:
                    t = self._advance()
                    if t.kind == "LPAREN":
                        depth += 1
                        parts.append("(")
                    elif t.kind == "RPAREN":
                        depth -= 1
                        if depth > 0: parts.append(")")
                    elif t.kind == "EOF": break
                    else: parts.append(t.value)
                parts.append(")")
            else:
                self._advance()  # [
                parts.append("[")
                depth = 1
                while depth > 0:
                    t = self._advance()
                    if t.kind == "LBRACKET":
                        depth += 1
                        parts.append("[")
                    elif t.kind == "RBRACKET":
                        depth -= 1
                        if depth > 0: parts.append("]")
                    elif t.kind == "EOF": break
                    else: parts.append(t.value)
                parts.append("]")
        result = "".join(parts)
        # Handle PEP 604 union types (X | Y | Z), trait intersections
        # (X & Y & Z), and any other trailing operator continuing an
        # arbitrary (non-type) expression in this annotation position.
        return self._consume_trailing_annotation_ops(result)
    def with_filename(self, filename: str) -> Parser:
        """Attach a source filename for `file:line:col:` diagnostics.
        Kept as a separate setter (not an __init__ param) because the
        self-hosted compiled path emits one fixed C signature per function —
        callers passing 1 vs 2 constructor args would produce two conflicting
        declarations for Parser___init__."""
        self._filename = filename
        return self

    def _peek(self, offset: int = 0) -> Token:
        i = self._pos + offset
        if i < len(self._tok):
            return self._tok[i]
        last_line = 0
        last_col = 0
        if self._tok:
            last_tok = self._tok[-1]
            last_line = last_tok.line
            last_col = last_tok.col
        # Pass every field explicitly (not relying on Token's `col: int = 0`
        # dataclass default) — the self-hosted compiled path doesn't reliably
        # apply Python default field values on a constructor call that omits
        # them, so an implicit default can come back as an uninitialized/
        # None-ish slot instead of 0 (seen as "file:line:None:" in a
        # compiled-path diagnostic).
        return Token("EOF", "", line=last_line, col=last_col)

    def _advance(self) -> Token:
        t = self._tok[self._pos]
        if self._pos < len(self._tok) - 1: self._pos += 1
        return t

    def _loc(self, tok: Token) -> str:
        """Format a gcc-style `file:line:col: ` prefix for a diagnostic.
        Omits the filename segment when none was supplied to the Parser
        (e.g. inline snippets compiled from a string with no source file).

        `tok` is required (no default/None-fallback) — every call site
        already has a concrete token in hand, and a `tok if tok is not
        None else self._peek()` ternary here previously confused the
        self-hosted compiled path's type inference: the phi'd local came
        back typed int64_t instead of Token*, so `.col` silently read back
        as garbage/None in compiled diagnostics (`.line` happened to still
        work). Only ever called from *inside* an f-string interpolation at
        each raise site (never via a `raise self._error(...)` indirection)
        — the compiled path's raise-lowering (_gen_stmt_RaiseStmt) pattern-
        matches the literal shape `raise ExcName(single_string_arg)` to
        capture the exception's type tag and message; routing the raise
        through a helper method call breaks that match silently (the
        exception still fires, but with an empty message and no type tag,
        since `val.func` is a MemberExpr instead of a bare IdentExpr)."""
        if self._filename:
            return f"{self._filename}:{tok.line}:{tok.col}: "
        return f"{tok.line}:{tok.col}: "

    def _expect(self, kind: str, value: str = None) -> Token:
        t = self._peek()
        if t.kind != kind:
            raise SyntaxError(f"{self._loc(t)}Expected {kind} got {t.kind}({t.value!r})")
        if value and t.value != value:
            raise SyntaxError(f"{self._loc(t)}Expected {value!r} got {t.value!r}")
        return self._advance()

    def _ident(self) -> str:
        """Consume an identifier, allowing keywords (e.g. `out`, `mut`) and
        backtick-quoted names to be used as plain identifiers."""
        t = self._peek()
        if t.kind in ("NAME", "KW"):
            return self._advance().value
        if t.kind == "STRING" and t.value.startswith("`"):
            return self._advance().value
        raise SyntaxError(f"{self._loc(t)}Expected NAME or KW got {t.kind}({t.value!r})")

    def _capture_opaque_annotation_tail(self) -> str:
        """Consume the remainder of an arbitrary (non-type) expression that
        continues past a type-shaped annotation prefix, e.g. the `obj)` in
        `gamma: some < obj)` — see PARSE_FAIL_annotation_trailing_binary_op.
        Python's grammar permits any expression in an annotation position
        with zero semantic type-checking, and nothing downstream re-parses
        the annotation string assuming real type syntax (traced in commit
        6ee8291), so the tail is captured as opaque raw text rather than
        raised as a SyntaxError.

        Bracket-depth-aware (nested `(`/`[`/`{` don't prematurely trip a
        terminator check) and stops BEFORE consuming whichever terminator
        token the various `_parse_type_ann` call sites rely on to know the
        annotation is done: COMMA/RPAREN for parameter lists, COLON/ASSIGN
        for return types and var-decls, ARROW, NEWLINE/EOF, INDENT/DEDENT.
        An unmatched closing `)`/`]`/`}` (depth back to 0) is left for the
        caller the same way; only a still-open nested bracket's closer is
        consumed as part of the opaque text."""
        STOP_KINDS = ("COMMA", "COLON", "ASSIGN", "ARROW", "NEWLINE", "EOF", "INDENT", "DEDENT")
        depth = 0
        parts = []
        while True:
            t = self._peek()
            if depth == 0 and t.kind in STOP_KINDS:
                break
            if t.kind in ("LPAREN", "LBRACKET", "LBRACE"):
                depth += 1
                parts.append(self._advance().value)
            elif t.kind in ("RPAREN", "RBRACKET", "RBRACE"):
                if depth == 0:
                    break
                depth -= 1
                parts.append(self._advance().value)
            elif t.kind == "EOF":
                break
            else:
                parts.append(self._advance().value)
        return " ".join(parts)

    def _consume_trailing_annotation_ops(self, name: str) -> str:
        """After a type-shaped annotation prefix (`name`) is fully parsed,
        consume any trailing operator that continues the expression:
        1. PEP 604 union (`|`) / trait intersection (`&`) — real Mojo type
           syntax, recursively parsing a real nested type annotation as the
           RHS (pre-existing behavior).
        2. Any OTHER trailing operator (`<`, `>`, `==`, binary `+`/`-`, etc.)
           — not real type syntax, but Python's grammar syntactically
           permits an arbitrary expression in an annotation position (PEP
           649), so the operator and its RHS are captured as opaque text via
           `_capture_opaque_annotation_tail` instead of raising. See
           PARSE_FAIL_annotation_trailing_binary_op. `?` is
           deliberately excluded here — it's the optional-type suffix
           handled by the caller, `_parse_type_ann`."""
        while self._peek().kind == "OP" and self._peek().value in ("|", "&"):
            op = self._advance().value
            rhs = self._parse_type_ann()
            name = name + f" {op} " + rhs
        if self._peek().kind == "OP" and self._peek().value != "?":
            op = self._advance().value
            tail = self._capture_opaque_annotation_tail()
            name = name + " " + op + (" " + tail if tail else "")
        return name

    def _capture_bracketed_text(self) -> str:
        """Consume a balanced `[...]` (tracking nested bracket depth so an
        inner comma, e.g. `d[a, b]`'s tuple key, is correctly treated as
        part of the subscript rather than ending the block early) and
        return its contents — WITHOUT the enclosing brackets — reconstructed
        as source text by joining consumed tokens' raw values. Every token's
        `.value` is the exact matched source substring (see the tokenizer's
        `_TOKEN_RE`, including STRING tokens which keep their quotes), so
        joining them with spaces reconstructs syntactically valid Mojo
        source that myinterpreter.py can re-tokenize/re-parse later via its
        own `py_tokenize`/`Parser` (the same approach already used for
        f-string field interpolation)."""
        self._expect("LBRACKET")
        depth = 1
        parts = []
        while depth > 0:
            t = self._peek()
            if t.kind == "LBRACKET":
                depth += 1
                parts.append(self._advance().value)
            elif t.kind == "RBRACKET":
                depth -= 1
                self._advance()
                if depth == 0:
                    break
                parts.append("]")
            elif t.kind == "EOF":
                break
            else:
                parts.append(self._advance().value)
        return " ".join(parts)

    def _parse_unpack_target(self):
        """Parse a single unpacking-target element, supporting nested tuples:
        (a, (b, c)) and a single starred element within a comma-list
        (`a, *rest`), matching Python's extended-unpacking grammar. The
        starred form is represented as "*rest" in the comma-joined string
        target that myinterpreter.py's _bind_comprehension_target consumes.

        A target element may also be a dotted attribute-access expression
        (`st.lineno`, possibly chained `a.b.c`), e.g. `for st.lineno, line
        in items:` — real-world code (CPython's configparser.py) mutates an
        existing object's attribute directly in the loop instead of binding
        a fresh local. This is kept as literal text ("st.lineno") within
        the comma-joined string, the same way a starred name is kept as
        literal text ("*rest"); myinterpreter.py's _bind_comprehension_target
        recognizes the embedded "." and performs a real attribute SET
        (reusing _assign_target) instead of a scope.define().

        A target element may also be a subscript expression (`d["k"]`,
        possibly chained `d[1][0]`), e.g. `for d["k"] in items:` or
        `with EXPR as targets[1][0]:` (the latter straight from CPython's
        own `Lib/test/test_with.py`). Same "keep as literal text" scheme:
        the bracket and its contents are captured verbatim (via
        `_capture_bracketed_text`) and appended to the target string
        ("d[\"k\"]"); myinterpreter.py's `_bind_single_target` recognizes
        the embedded "[" and performs a real subscript SET (again reusing
        `_assign_target`, via a re-parsed `SubscriptExpr`). NOTE: because a
        subscript's contents are an arbitrary expression that could itself
        contain a top-level comma (`d[a, b]`, a tuple key) — which would be
        ambiguous with this SAME comma used to separate elements of the
        outer target list — the outer comma-list join above only splits on
        commas it consumes as its own token stream (safe), but
        myinterpreter.py's later `str.split(',')` re-parse of the joined
        target string is NOT bracket-depth-aware. A comma-containing
        subscript key as a for/with target is therefore not supported; the
        real-world motivating case (`targets[1][0]`) and this bug's own
        repro (`d["k"]`) both use comma-free keys and work correctly.

        Shared by `for`-loop targets and `with ... as (a, b):` targets — one
        representation, one parser, reused everywhere a comma-joined
        unpacking-target string is needed (per this project's consolidation
        convention). (Chained-assignment tuple targets use a separate
        Expr-based TupleExpr representation, not this string form — see
        _parse_stmt's ASSIGN handling.)"""
        if self._peek().kind == "LPAREN":
            self._advance()
            parts = []
            saw_comma = False
            while self._peek().kind != "RPAREN" and self._peek().kind != "EOF":
                parts.append(self._parse_unpack_target())
                if self._peek().kind == "COMMA":
                    saw_comma = True
                    self._advance()
                    saw_comma = True
            self._expect("RPAREN")
            # `for (a) in b:` is a PARENTHESISED NAME, not a 1-tuple: Python
            # binds the whole item to `a`. `for (a,) in b:` IS a 1-tuple and
            # unpacks the item's single element. Both used to reduce to the
            # IDENTICAL string "(a)" (a trailing comma at the top level
            # reuses this spelling too — see _parse_for), so the compiled
            # path's `for (a) in ...` unpacked instead of binding and
            # printed `1` where CPython prints `(1,)`.
            #
            # The parens are the whole disambiguation, and keeping them is
            # not optional: every consumer already reads a parenthesised
            # target as "this is a tuple target" (that is what makes
            # `for (a,) in b:` unpack correctly today) and a bare name as
            # "bind the whole item". So the parenthesised single name
            # unwraps to its bare text — `a` — which is exactly the
            # representation `for a in b:` already produces. A 1-element group
            # that really did have a comma keeps "(a)", and the trailing comma
            # SURVIVES into that string: it is the only thing that tells
            # `'(a,)'` from `'(a)'`, and `for_target_is_tuple` is its one reader.
            # `split_top_level_commas` drops the empty slot the comma leaves,
            # so no other consumer has to learn a second spelling of a 1-tuple
            # — which is the failure this branch's version of the fix made, by
            # appending a bare `"a,"` with no parens for the `for a, in ...`
            # spelling while this one wraps it.
            if len(parts) == 1 and not saw_comma:
                return parts[0]
            _body = ", ".join(parts)
            if saw_comma and len(parts) == 1:
                _body += ","
            return "(" + _body + ")"
        elif self._peek().kind == "OP" and self._peek().value == "*":
            self._advance()
            tok = self._advance()
            return "*" + tok.value
        else:
            # Accept KW tokens (e.g. "fn", "var") as variable names
            tok = self._advance()
            name = tok.value
            # Dotted attribute target: st.lineno, or chained a.b.c
            while self._peek().kind == "DOT":
                self._advance()
                attr_tok = self._advance()
                name += "." + attr_tok.value
            # Subscript target: d["k"], or chained d[1][0]
            while self._peek().kind == "LBRACKET":
                name += "[" + self._capture_bracketed_text() + "]"
            return name

    def _parse_dotted_name(self) -> str:
        """Consume a dotted name like `asyncio.CancelledError` and return it
        as a single string. Used for exception types in `except` clauses."""
        name = self._ident()
        while self._peek().kind == "DOT":
            self._advance(); name += "." + self._ident()
        return name

    def _dotted_name_expr(self, dotted: str):
        """The AST for a dotted name string, as nested IdentExpr/MemberExpr.

        The inverse of `_parse_dotted_name`, needed because a decorator with
        arguments (`@functools.lru_cache(maxsize=8)`) has to be recorded as a
        real CallExpr rather than as a bare name: the argument list is
        discarded by the name-only form, so `@deco` and `@deco(x)` were
        indistinguishable in the AST, and both silently did nothing."""
        parts = dotted.split('.')
        node = IdentExpr(name=parts[0])
        for p in parts[1:]:
            node = MemberExpr(obj=node, member=p)
        return node

    def _parse_paren_args(self):
        """Parse a call's argument list, with LPAREN already current. Returns
        `(args, kwargs)` where `kwargs` is the `(name, expr)` list shape
        `CallExpr.kwargs` holds.

        Extracted from `_parse_expr`'s postfix loop so a decorator's argument
        list can be parsed by exactly the same rules as any other call's --
        before, `@deco(x)` skipped the tokens instead, so the AST could not
        tell it from a bare `@deco` and every parameterised decorator was
        silently inert."""
        self._advance()          # skip LPAREN
        args = []
        keywords = {}
        while self._peek().kind != "RPAREN":
            # Handle unpacking (*expr / **expr). Don't consume the
            # star(s) here — let _parse_expr (via _parse_unary) wrap
            # the operand in UnaryOp(op='*'/'**', operand=...) so the
            # marker survives into the AST. The interpreter's call
            # evaluation (myinterpreter.py) detects that wrapper and
            # splices the iterable's elements/mapping's items into
            # the flat arg/kwargs lists at call time, instead of
            # treating the whole expression as one ordinary
            # positional argument value.
            if self._peek().kind == "OP" and self._peek().value in ("*", "**"):
                args.append(self._parse_expr(0))
            # Handle keyword arguments (name=value) — name can be NAME or KW token
            elif self._peek().kind in ("NAME", "KW") and self._peek(1).kind == "ASSIGN":
                keyword_name = self._advance().value  # get keyword name
                self._advance()  # skip =
                keywords[keyword_name] = self._parse_expr(0)  # parse and store value
            else:
                first = self._parse_expr(0)
                if self._is_kw("for"):
                    gens = self._parse_generators()  # allow chained for-clauses
                    args = [Comprehension(kind="generator", element=first, generators=gens)]
                    continue
                args.append(first)
            if self._peek().kind == "COMMA": self._advance()
        self._expect("RPAREN")
        # Convert keywords dict to list of (name, expr) tuples for
        # CallExpr.kwargs. Explicit accumulation loop, NOT the
        # `[(k, v) for k, v in keywords.items()]` comprehension — a
        # list comprehension over dict items is the established
        # self-hosted trap (same family as `''.join(<genexpr>)`):
        # the compiled result erased to the garbage non-list 1.
        kwargs_list = []
        for _kw_name, _kw_val in keywords.items():
            kwargs_list.append((_kw_name, _kw_val))
        return args, kwargs_list

    def _parse_decorator_args(self, dec_name: str):
        """A decorator's parenthesised argument list, with LPAREN current.

        Returns either a `CallExpr` — the ordinary case, `@deco(x, k=1)`, the
        exact node `_parse_expr`'s own call would build — or a
        `DecoratorArgs` when the region is a `;`-separated specification.

        WHY the second case exists. A decorator's argument list is NOT a call
        argument list: the arguments belong to the decorator's own
        mini-grammar, and at least one real grammar in this tree
        (`formal/examples/{fact,fib,sum,count}.mojo`'s `@spec(...)`, read by
        the Lean proof pipeline) is not Mojo expression syntax at all:

            @spec(fact_spec; fact_spec 0 = 1; fact_spec (n+1) = (n+1) * fact_spec n)

        That is a name, then `;`-separated EQUATIONS: juxtaposed application
        (`fact_spec 0`), a bare `=` in operator position, and a `;` between
        clauses. Reading it as a call argument list is a `SyntaxError` at the
        first `;` (it was introduced by 19bc0dd, which made this a real parse
        where it used to skip the tokens, and it took 13 of 45
        `formal/examples/*.mojo` out of the parser).

        The `;` is the discriminator, and it is unambiguous rather than a
        guess: a semicolon is not valid anywhere in a Mojo EXPRESSION — the
        same file's `_split_on_separators` already states the rule ("real
        Python has no such thing as a semicolon inside an expression at all")
        and, crucially, already DELEGATES that case to the bracketed reader by
        tracking bracket depth so a `;` inside `(...)` is left in place
        instead of being split off as a statement separator. This is that
        bracketed reader. A `;` nested inside a further `(`/`[`/`{` does not
        count, so a `;` that somehow appeared in a real call's arguments would
        still be reported rather than silently reinterpreted.

        So a decorator region containing no top-level `;` takes the
        `_parse_paren_args()` path unchanged, which is what every other
        decorator in the tree uses and what keeps `@deco` and `@deco(x)`
        distinguishable (the point of 19bc0dd). Nothing is discarded either
        way: the CallExpr keeps its parsed arguments, and `DecoratorArgs`
        keeps its clauses as text.
        """
        # Look ahead for a top-level SEMICOLON before committing to a shape.
        # Rewind and re-parse rather than remember a token list: `_parse_
        # paren_args` is the single definition of what a call's arguments
        # mean, and a second copy of it would drift from it.
        start = self._pos
        self._advance()          # skip LPAREN, so `depth` counts only INNER
        depth = 0
        spec = False
        while True:
            k = self._peek().kind
            if k == "LPAREN" or k == "LBRACKET" or k == "LBRACE":
                depth += 1
            elif k == "RPAREN" or k == "RBRACKET" or k == "RBRACE":
                if depth == 0:
                    break
                depth -= 1
            elif k == "SEMICOLON" and depth == 0:
                spec = True
            elif k == "EOF":
                break
            self._advance()
        close_line = self._peek().line
        close_col = self._peek().col
        self._pos = start
        if not spec:
            args, kwargs = self._parse_paren_args()
            return CallExpr(func=self._dotted_name_expr(dec_name),
                            args=args, kwargs=kwargs)
        # The specification form: consume the balanced region and keep each
        # `;`-separated clause as text. Token values, not source slicing:
        # Token carries line/col but no source offset, and a STRING token's
        # `;` is already part of its value rather than a SEMICOLON.
        self._advance()          # skip LPAREN
        clauses = []
        cur = []
        depth = 0
        while True:
            k = self._peek().kind
            if k == "RPAREN" and depth == 0:
                self._advance()
                break
            if k == "EOF":
                break
            if k == "SEMICOLON" and depth == 0:
                self._advance()
                clauses.append(" ".join(cur))
                cur = []
                # Layout tokens inside the region (a multi-line `@spec(...)`)
                # are dropped by the filter at the bottom of this loop; no
                # extra advance here, or the first token of the next clause
                # is swallowed.
                continue
            if k == "LPAREN" or k == "LBRACKET" or k == "LBRACE":
                depth += 1
            elif k == "RPAREN" or k == "RBRACKET" or k == "RBRACE":
                depth -= 1
            if k != "NEWLINE" and k != "INDENT" and k != "DEDENT":
                cur.append(self._peek().value)
            self._advance()
        clauses.append(" ".join(cur))
        return DecoratorArgs(name=dec_name, clauses=clauses,
                             line=close_line, col=close_col)

    def _skip_newlines(self):
        while self._peek().kind == "NEWLINE": self._advance()

    def _at_end(self) -> bool: return self._peek().kind == "EOF"
    def _is_kw(self, *w) -> bool:
        t = self._peek(); return t.kind == "KW" and t.value in w

    def parse_module(self) -> list:
        stmts = []
        self._skip_newlines()
        while not self._at_end():
            self._parse_stmt_into(stmts)
            self._skip_newlines()
        return _synthesize_fieldwise_inits(stmts)

    def _parse_stmt_into(self, stmts: list):
        """Parse one statement and append it to `stmts`.

        One syntactic construct can yield SEVERAL statements — a multi-target
        `comptime a, b = expr` is two ComptimeVarStmts — so a parse result may
        be a single node or a list of them. Flattening here, in the two places
        that collect statements, keeps every `_parse_stmt` branch free to return
        either without each caller having to know which it got.
        """
        produced = self._parse_stmt()
        if isinstance(produced, list):
            stmts.extend(produced)
        else:
            stmts.append(produced)

    def _parse_block(self) -> list:
        # Support inline single-statement body: "def foo(): return x" on one line
        if self._peek().kind != "NEWLINE":
            start_line = self._peek().line
            stmt = self._parse_stmt()
            stmts = [stmt] if stmt is not None else []
            # Same-line multi-statement inline body: "if x: a = 1; continue" —
            # the tokenizer (see py_tokenize's `_split_on_separators` loop)
            # splits each ';'-separated piece of a physical line into its own
            # token run terminated by a NEWLINE, which loses the fact that
            # every piece after the colon is still part of THIS compound
            # statement's body, not a sibling of the enclosing block. Without
            # this loop, only the first piece ("a = 1") became the body and
            # anything after the first ';' (here, "continue") silently became
            # a sibling statement instead — executing unconditionally on every
            # loop iteration regardless of `x`. Detected via physical line
            # number: every ';'-split piece from the same source line shares
            # the same `line`, so a NEWLINE followed by a token still on the
            # same line means "more of this same-line body", not a new line.
            while (self._peek().kind == "NEWLINE"
                   and self._peek(1).line == start_line
                   and self._peek(1).kind not in ("DEDENT", "EOF")):
                self._advance()  # consume the semicolon-split NEWLINE
                start_line = self._peek().line
                nxt = self._parse_stmt()
                if nxt is not None:
                    stmts.append(nxt)
            return stmts
        self._expect("NEWLINE")
        self._skip_newlines()
        # Empty block: comment-only body produces DEDENT with no INDENT
        if self._peek().kind in ("DEDENT", "EOF", "KW"):
            return [PassStmt()]
        self._expect("INDENT")
        stmts = []
        self._skip_newlines()
        while self._peek().kind not in ("DEDENT", "EOF"):
            self._parse_stmt_into(stmts)
            self._skip_newlines()
        self._expect("DEDENT")
        return stmts

    def _parse_yield_expr(self):
        """Parse a `yield`/`yield from` expression — assumes the current
        token is the NAME('yield') token. `yield` is never a real Python
        identifier (reserved since Python 2.2; confirmed by grepping
        CPython's own test suite — the only `yield = ...`-shaped source
        found there is test_syntax.py/test_generators.py doctests that
        assert it's a SyntaxError), so no `var`/`await`-style "used as an
        identifier" disambiguation is needed — every call site below only
        invokes this where real Python's own grammar also treats `yield` as
        the keyword, so no ambiguity is possible.
        """
        t = self._advance()  # consume 'yield'
        line, col = t.line, t.col
        if self._peek().kind == "KW" and self._peek().value == "from":
            self._advance()
            val = self._parse_expr(0)
            return YieldFromExpr(value=val, line=line, col=col)
        # Bare `yield`: next token can't start an expression.
        if self._peek().kind in ("NEWLINE", "DEDENT", "EOF", "RPAREN",
                "RBRACKET", "RBRACE", "COMMA", "COLON", "SEMICOLON"):
            return YieldExpr(value=None, line=line, col=col)
        val = self._parse_expr(0)
        # Implicit tuple: yield a, b, c — same convention as `return a, b`.
        if self._peek().kind == "COMMA":
            elements = [val]
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind in ("NEWLINE", "DEDENT", "EOF", "RPAREN",
                        "RBRACKET", "RBRACE", "COLON", "SEMICOLON"):
                    break
                elements.append(self._parse_expr(0))
            val = TupleExpr(elements=elements, line=val.line, col=val.col)
        return YieldExpr(value=val, line=line, col=col)

    def _parse_expr_or_yield(self):
        """Like `_parse_expr(0)` but also recognizes a leading `yield`/
        `yield from` — for use ONLY at the specific grammar positions real
        Python allows a bare (unparenthesized) yield expression: the whole
        RHS of a simple/chained/annotated/augmented assignment, and a bare
        expression statement. Every other position (call arguments, `return`
        value, `if`/`while` conditions, container-literal elements, ...)
        must keep going through plain `_parse_expr(0)` so `yield` there
        still requires explicit parens, matching real Python (`f((yield x))`,
        not `f(yield x)`) — parenthesized grouping itself routes back through
        this same recognition (see the LPAREN case in `_parse_primary`), so
        `(yield x)` still works in those positions.
        """
        t = self._peek()
        if t.kind == "NAME" and t.value == "yield":
            return self._parse_yield_expr()
        return self._parse_expr(0)

    def _parse_stmt(self):
        t = self._peek()
        line, col = t.line, t.col
        # `match` is a soft keyword (like Python's own) — only a match
        # statement when followed by a real expression and a top-level `:`
        # before the line ends; otherwise it's an ordinary identifier
        # (`match(x)` a call, `match = 5` an assignment, etc).
        if t.kind == "NAME" and t.value in ("match", "__match") and self._is_match_stmt():
            return self._parse_match()
        # `async` is a soft keyword, same story as `match`/`fn`/`struct`/`var`
        # above: `async` lexes as a plain NAME (not in _KEYWORDS — real
        # Python has no bare `async` keyword outside `async def`/`async
        # for`/`async with` either), so it's also a legal ordinary
        # identifier. Only commit to an async-prefixed parse when the very
        # next token is one of the three real async-statement openers
        # (`def`/`fn`, `for`, `with`); otherwise fall through to ordinary
        # expression/assignment parsing, where `async` reads as a plain
        # identifier via _parse_primary. This is the UNDECORATED path for
        # `async def` — the decorated path (`@dec\nasync def f(): ...`) is
        # handled separately below, in the `@` decorator block, which strips
        # a leading `async` before dispatching to `def`/`fn`.
        if t.kind == "NAME" and t.value == "async":
            nxt = self._peek(1)
            if nxt.kind == "KW" and nxt.value in ("def", "fn"):
                self._advance()  # consume 'async'
                self._advance()  # consume 'def'/'fn'
                return self._parse_funcdef([], is_async=True)
            if nxt.kind == "KW" and nxt.value == "for":
                self._advance()  # consume 'async'
                stmt = self._parse_for()
                stmt.is_async = True
                return stmt
            if nxt.kind == "KW" and nxt.value == "with":
                self._advance()  # consume 'async'
                stmt = self._parse_with()
                stmt.is_async = True
                return stmt
            # else: `async` used as an ordinary identifier — fall through.
        if t.kind == "KW":
            if t.value == "import": return self._parse_import()
            if t.value == "from":   return self._parse_from_import()
            if t.value == 'var':
                # `var` is ambiguous, same as `fn`/`struct`: it's both this
                # dialect's declaration keyword AND a perfectly ordinary
                # Python identifier (arguably more common as a plain name
                # than `fn`/`struct`/`enum` ever are). Only commit to
                # _parse_var_decl() when the shape that follows could
                # actually BE a declaration. Per _parse_var_decl itself, a
                # real declaration is `var` followed by either:
                #   - a name-like token (NAME/KW/backtick-STRING) that then
                #     becomes the declared name (optionally followed by
                #     `,` more names, `:` a type annotation, `=` a value,
                #     or nothing — a bare uninitialized `var x`), or
                #   - `:` directly, meaning `var` itself is the field name
                #     being annotated (`var: Type`) — this shape parses
                #     identically whether `var` is "the keyword declaring a
                #     field named var" or "the identifier var being
                #     annotated", so there's no actual ambiguity to resolve
                #     there.
                # Anything else — `var.attr` (member access), `var.method()`
                # (call), `var,` where var is itself one of several plain
                # tuple-unpack targets (`var, x = ...`), `var == y`,
                # `var[0]`, `var =`/`var +=` (assignment), bare `var` alone,
                # etc. — means `var` is being used as an ordinary identifier
                # here, so fall through to ordinary expression/assignment
                # parsing (which already accepts KW tokens as identifiers
                # via _parse_primary).
                nxt = self._peek(1)
                name_like = nxt.kind in ("NAME", "KW") or (
                    nxt.kind == "STRING" and nxt.value.startswith("`"))
                looks_like_vardecl = name_like or nxt.kind == "COLON"
                if looks_like_vardecl:
                    return self._parse_var_decl()
                # else: fall through to expression/assignment handling below
            if t.value == 'if': return self._parse_if()
            if t.value == 'while': return self._parse_while()
            if t.value == 'for': return self._parse_for()
            if t.value in ("def", "fn"):
                # `fn` is ambiguous: it's both this dialect's function-def
                # keyword AND a legal plain identifier in real Python code
                # (e.g. `fn, lno, func, sinfo = self.findCaller(...)` in
                # CPython's logging/__init__.py). Only commit to the
                # function-definition parse when the token shape that
                # follows could actually BE a function signature: `fn`
                # immediately followed by a name (the function's name,
                # which per _parse_funcdef may itself be NAME/KW/backtick)
                # and then either `(` (no generics) or `[` (generic params
                # before the `(`). Anything else — `fn,` (tuple-unpacking
                # target), `fn =`/`fn +=` (assignment), `fn.attr`
                # (attribute access), `fn == x`, `fn[0]` used as a subscript
                # target, `fn` alone, etc. — means `fn` is being used as an
                # ordinary identifier here, so fall through to ordinary
                # expression/assignment parsing (which accepts KW tokens as
                # identifiers via _parse_primary).
                if t.value == "fn":
                    nxt, nxt2 = self._peek(1), self._peek(2)
                    name_like = nxt.kind in ("NAME", "KW") or (
                        nxt.kind == "STRING" and nxt.value.startswith("`"))
                    looks_like_funcdef = name_like and nxt2.kind in ("LPAREN", "LBRACKET")
                    if not looks_like_funcdef:
                        pass  # fall through to expression statement
                    else:
                        self._advance(); return self._parse_funcdef([])
                else:
                    self._advance(); return self._parse_funcdef([])
            if t.value in ("struct", "class"):
                # `struct` is ambiguous the same way `fn` is (see the `fn`
                # carve-out above): it's both this dialect's struct-def
                # keyword AND a legal plain identifier/module name in real
                # Python code (e.g. `struct.pack_into(...)` using the
                # stdlib `struct` module, from CPython's
                # multiprocessing/shared_memory.py). Real Python has no
                # `struct` keyword at all, so this collision is real.
                # `class`, by contrast, IS a hard keyword in real Python —
                # a variable literally named `class` is invalid Python — so
                # it has no realistic identifier-collision risk and is left
                # unconditionally routed to _parse_struct.
                #
                # Only commit to the struct-definition parse when the shape
                # that follows could actually BE one: `struct` immediately
                # followed by a name-like token (per _parse_struct's name
                # read via `self._ident()`, struct names may be NAME/KW/
                # backtick-quoted, just like function names — a struct can
                # itself be named after another keyword, e.g. `struct
                # super:`, mirroring CPython's own test_super.py which
                # defines a class named `super`) and then one of `[`
                # (struct param block), `(` (base-class list), or `:`
                # (straight into the body). Anything else — `struct.attr`
                # (attribute access), `struct(...)` used as a call, `struct
                # =` (assignment), `struct` alone, etc. — means `struct` is
                # being used as an ordinary identifier here, so fall through
                # to ordinary expression/assignment parsing (which accepts
                # KW tokens as identifiers via _parse_primary).
                if t.value == "struct":
                    nxt, nxt2 = self._peek(1), self._peek(2)
                    name_like = nxt.kind in ("NAME", "KW") or (
                        nxt.kind == "STRING" and nxt.value.startswith("`"))
                    looks_like_structdef = name_like and nxt2.kind in (
                        "LBRACKET", "LPAREN", "COLON")
                    if looks_like_structdef:
                        return self._parse_struct()
                    # else: fall through to expression statement
                else:
                    return self._parse_struct()
            if t.value == "enum":
                # `enum` is ambiguous the same way `fn`/`struct` are (see the
                # carve-outs above): real Python has no `enum` keyword — it's
                # a common plain identifier/module name (e.g. `import enum`
                # then `enum = SomeEnum`, or a local var named `enum`). Only
                # commit to the enum-definition parse when the shape that
                # follows could actually BE one: `enum` immediately followed
                # by a name-like token (per _parse_enum's name read) and then
                # one of `(` (optional base-class list) or `:` (straight into
                # the body). Anything else — `enum.attr` (attribute access),
                # `enum(...)` used as a call, `enum =` (assignment), `enum`
                # alone, etc. — means `enum` is being used as an ordinary
                # identifier here, so fall through to ordinary
                # expression/assignment parsing (which accepts KW tokens as
                # identifiers via _parse_primary).
                nxt, nxt2 = self._peek(1), self._peek(2)
                name_like = nxt.kind in ("NAME", "KW") or (
                    nxt.kind == "STRING" and nxt.value.startswith("`"))
                looks_like_enumdef = name_like and nxt2.kind in ("LPAREN", "COLON")
                if looks_like_enumdef:
                    return self._parse_enum()
                # else: fall through to expression statement
            if t.value == "trait": return self._parse_trait()
            if t.value == "try": return self._parse_try()
            if t.value == "with": return self._parse_with()
            if t.value == "comptime":
                # Only commit to the comptime-statement parse when the next
                # token could actually start one: `comptime if/for/assert`,
                # `comptime var NAME = ...`, `comptime NAME = ...`, or
                # `comptime \`name\` = ...`.
                # Anything else — `comptime.foo` (imported module named
                # comptime), `comptime(...)`, `comptime = ...`, bare
                # `comptime` — is an ordinary identifier use; fall through
                # to expression/assignment parsing (same carve-out pattern
                # as `enum` above; `_parse_primary` accepts KW as ident).
                nxt = self._peek(1)
                if ((nxt.kind == "KW"
                     and nxt.value in ("if", "for", "assert", "var", "let"))
                        or nxt.kind == "NAME"
                        or (nxt.kind == "STRING" and nxt.value.startswith("`"))):
                    return self._parse_comptime()
                # else: fall through to expression statement
            if t.value == 'pass': return self._parse_pass()
            if t.value == 'return': return self._parse_return()
            if t.value == 'raise': return self._parse_raise()
            if t.value == 'break': return self._parse_break()
            if t.value == 'continue': return self._parse_continue()
            if t.value == 'assert': return self._parse_assert()
            if t.value == 'global': return self._parse_global()
            if t.value == 'nonlocal': return self._parse_nonlocal()
            if t.value == 'del': return self._parse_del()
        # Handle __mlir_attr and other MLIR/special forms as opaque no-ops.
        # NOT __mlir_region (handled below) and NOT __mlir_op: a bare __mlir_op
        # statement is a real side-effecting op (e.g. `pop.store`, ownership
        # markers) — let it fall through to an expression statement so the
        # backend lowers it (mlir.py).
        if t.kind == "NAME" and t.value.startswith("__mlir") \
                and t.value not in ("__mlir_region", "__mlir_op"):
            self._advance()  # skip __mlir_attr/etc
            # Skip string literal if present
            if self._peek().kind == "LPAREN":
                self._advance()  # skip (
                if self._peek().kind == "STRING":
                    self._advance()  # skip string
                self._advance()  # skip )
            # Skip the rest of the line (result type annotation, etc)
            while self._peek().kind not in ("NEWLINE", "DEDENT", "EOF"):
                self._advance()
            return PassStmt()
        # Handle __extension Type: methods and __mlir_region name(...): body
        if t.kind == "NAME" and t.value in ("__extension", "__mlir_region"):
            self._advance()  # skip __extension or __mlir_region
            name = self._expect("NAME").value
            # Skip any function call arguments if present
            if self._peek().kind == "LPAREN":
                self._advance()  # (
                depth = 1
                while depth > 0:
                    t_inner = self._advance()
                    if t_inner.kind == "LPAREN":
                        depth += 1
                    elif t_inner.kind == "RPAREN": depth -= 1
            self._expect("COLON")
            # Check if there is a body on this line or on following lines
            if self._peek().kind == "NEWLINE":
                # Indented block follows
                body = self._parse_block()
            else:
                # Body on same line, skip until newline
                while self._peek().kind not in ("NEWLINE", "DEDENT", "EOF"):
                    self._advance()
            # Treat as a pass statement
            return PassStmt(line=line, col=col)
        if t.kind == "OP" and t.value == "@":
            decs = []
            while self._peek().kind == "OP" and self._peek().value == "@":
                self._advance()
                # Decorator name may be dotted (@functools.lru_cache, @a.b.c)
                # and each component may lex as a Mojo keyword while still
                # being an ordinary Python identifier (e.g. `@enum.global_enum`,
                # `@ref(...)`) — use _parse_dotted_name(), the same
                # keyword-accepting helper used for `except mod.Error:` and
                # the earlier `from X import ref` fix, instead of
                # _expect("NAME") which only accepts a real NAME token.
                dec_name = self._parse_dotted_name()
                # Handle decorator with arguments: @decorator(args).
                #
                # The argument list used to be SKIPPED token by token, so
                # `@deco` and `@deco(x)` produced the identical AST node --
                # the arguments were unrecoverable, which is part of why a
                # decorator could be dropped without anything noticing. The
                # call is now parsed into a real CallExpr and stored in place
                # of the bare name, so the two are distinguishable and
                # `dumps` (which prints `node.decorators` verbatim) no longer
                # loses the arguments. A bare `@deco` still stores the plain
                # string, so every existing `X in decorators` check -- the
                # `staticmethod`/`classmethod`/`property`/`export`/`parameter`
                # readers across the tree -- is unaffected.
                #
                # `_parse_decorator_args` picks between that CallExpr and a
                # `DecoratorArgs`, whose argument list is a `;`-separated
                # specification rather than Mojo call syntax (`@spec(...; ...)`);
                # its docstring has the rule and the regression it fixes.
                if self._peek().kind == "LPAREN":
                    decs.append(self._parse_decorator_args(dec_name))
                    self._skip_newlines()
                    continue
                decs.append(dec_name)
                self._skip_newlines()
            kw = self._peek()
            if kw.kind == "KW" and kw.value in ("struct", "class"):
                self._pending_decs = decs
                return self._parse_struct()
            if kw.kind == "KW" and kw.value == "enum":
                self._pending_decs = decs
                return self._parse_enum()
            if kw.kind == "KW" and kw.value == "trait":
                self._pending_decs = decs
                return self._parse_trait()
            if kw.kind == "KW" and kw.value == "comptime":
                # Same carve-out as the statement-level dispatch: only a
                # real comptime-statement shape commits; `comptime.foo` etc.
                # falls through (and the decorator path below will 404 with
                # a clear expect-error rather than misparse).
                nxt = self._peek(1)
                if ((nxt.kind == "KW"
                     and nxt.value in ("if", "for", "assert", "var", "let"))
                        or nxt.kind == "NAME"
                        or (nxt.kind == "STRING" and nxt.value.startswith("`"))):
                    return self._parse_comptime()
                # else: fall through
            # Handle 'async def' — async is tokenized as NAME not KW. Milestone
            # 3a: build a real is_async=True FunctionDef instead of silently
            # discarding the `async` token (see AwaitExpr's docstring).
            is_async = False
            if kw.kind == "NAME" and kw.value == "async":
                is_async = True
                self._advance()
                kw = self._peek()
            if kw.kind == "KW" and kw.value in ("def", "fn"):
                self._advance()
                return self._parse_funcdef(decs, is_async=is_async)
            # Field-level decorators (e.g. @__allow_legacy_any_origin_fields)
            # applied to a `var` declaration: decorators carry no codegen
            # meaning here, so just parse the var decl and drop them.
            if kw.kind == "KW" and kw.value == "var":
                return self._parse_var_decl()
            # A decorated import: `@stable(recursive=True)` in front of
            # `from std.builtin.tuple import Tuple`. The decorator is recorded
            # on the import node rather than dropped, because `@deco` and
            # `@deco(x)` are otherwise indistinguishable — the same reason
            # `_parse_decorator_args` parses the argument list instead of
            # skipping it.
            if kw.kind == "KW" and kw.value in ("from", "import"):
                stmt = (self._parse_from_import() if kw.value == "from"
                        else self._parse_import())
                stmt.decorators = decs
                return stmt
            self._expect("KW", "def or fn")
            return self._parse_funcdef(decs)
        expr = self._parse_expr_or_yield()
        # Collect a comma-separated group starting with `expr` — this is
        # either a tuple-unpacking target (if followed by `=`) or a bare
        # comma/tuple expression statement (if not).
        saw_comma = self._peek().kind == "COMMA"
        if saw_comma:
            first_group = [expr]
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind == "ASSIGN": break
                # A trailing comma with nothing meaningful after it (e.g.
                # `print(1),` as its own statement, or `a, b,` — a plain
                # expression statement, not a tuple-unpacking target) —
                # matches the terminator check the chained-assignment RHS
                # loop below already does. Without this, `expr,` at
                # statement end tried to parse another expression starting
                # at NEWLINE/DEDENT/EOF and blew up with "Unexpected
                # NEWLINE". Leave the comma consumed; first_group already
                # has everything that came before it.
                if self._peek().kind in ("NEWLINE", "DEDENT", "EOF", "SEMICOLON"):
                    break
                first_group.append(self._parse_expr(0))
        else:
            first_group = [expr]

        # Chained assignment where ANY link (including the first) may itself
        # be a comma-separated tuple-unpacking target list, e.g.
        # `a, b = x = pair` (unpack AND keep the whole value bound to `x`,
        # matching CPython's difflib.py / platform.py idiom) as well as the
        # simpler `x = y = expr` and `a, b = expr` cases. Was: the
        # tuple-target branch (above) and the chained-assignment loop
        # (formerly below) were mutually exclusive passes, so a tuple target
        # followed by another `= target` link hit "Unexpected ASSIGN".
        if self._peek().kind == "ASSIGN":
            # Parallel lists `group_elems` / `group_had_comma`: `had_comma`
            # records that this group was written with a trailing comma
            # (`nm,`), i.e. a 1-element TUPLE target / value (`nm, = args`
            # unpacks args' single element), NOT a bare `nm`. Without the
            # flag a single-element comma group is indistinguishable from a
            # plain target and `nm, = args` silently became `nm = args`.
            # Two PARALLEL lists (not a list of (elems, flag) tuples): this
            # file is compiled by the self-hosted compiler, and 2-tuple
            # unpacking over `list` elements boxes the slots to int64_t
            # there — the tuple-of-tuples form silently corrupted the parse
            # (58-file A/B regression, found 2026-09-25).
            group_elems = [first_group]
            group_had_comma = [saw_comma]
            while self._peek().kind == "ASSIGN":
                self._advance()
                val_expr = self._parse_expr_or_yield()
                group = [val_expr]
                had_comma = False
                while self._peek().kind == "COMMA":
                    had_comma = True
                    self._advance()
                    if self._peek().kind in ("NEWLINE", "DEDENT", "EOF", "ASSIGN"):
                        break
                    group.append(self._parse_expr(0))
                group_elems.append(group)
                group_had_comma.append(had_comma)

            def _group_to_expr(g, had_comma):
                if len(g) == 1 and not had_comma:
                    return g[0]
                return TupleExpr(elements=g)

            # The last group parsed is the real RHS; every group before it
            # (starting with `first_group`) is a target in the chain — a
            # single-element group WITHOUT a trailing comma is a plain
            # target, otherwise it is a tuple-unpacking target.
            _last = len(group_elems) - 1
            val = _group_to_expr(group_elems[_last], group_had_comma[_last])
            targets = []
            for _gi in range(_last):
                targets.append(_group_to_expr(group_elems[_gi], group_had_comma[_gi]))
            if len(targets) == 1:
                return AssignStmt(target=targets[0], value=val, line=line, col=col)
            return MultiAssignStmt(targets=targets, value=val, line=line, col=col)

        if saw_comma:
            # Not an assignment, treat as expression statement with comma
            # operator — a 1-element `first_group` here means a single
            # trailing comma (`EXPR,`), which is still a 1-element tuple
            # literal in Python, just like `len(first_group) > 1` (`EXPR1,
            # EXPR2,` etc.) is a multi-element one.
            return ExprStmt(TupleExpr(elements=first_group), line=line, col=col)
        expr = first_group[0]
        # Annotated assignment: target: Type [= value]
        if self._peek().kind == "COLON":
            self._advance()
            type_ann = self._parse_type_ann()
            if self._peek().kind == "ASSIGN":
                self._advance()
                val = self._parse_expr_or_yield()
                # `x: Type = value` previously silently discarded the
                # annotation (AssignStmt has no type_ann field) — harmless
                # for a local (type gets re-inferred from the value), but a
                # real bug for a dataclass field with both an annotation AND
                # a default (`x: list = field(default_factory=list)`, the
                # normal shape for every trailing/optional field in this
                # file's own AST-node dataclasses): the struct-field scanner
                # that builds struct_field_types only recognized VarDecl (no
                # value = pure declaration), so every such field was
                # invisible to the self-hosted compiled path — found via
                # StructDef's own _fieldwise_ctor_synthesized field aborting
                # through the generic getattr fallback. Switching this whole
                # branch to VarDecl (instead of adding type_ann to
                # AssignStmt) turned out to have a much wider blast radius:
                # every module-level `X: dict = {...}`-style global is
                # driven by machinery keyed on `isinstance(stmt, AssignStmt)`
                # (global C-storage boxing, _toplevel() statement collection)
                # that doesn't know about VarDecl — so stick the annotation
                # directly on AssignStmt instead, touching nothing else.
                return AssignStmt(target=expr, value=val, type_ann=type_ann, line=line, col=col)
            else:
                # Bare annotation (e.g. class field `kind: str`) → VarDecl for struct fields.
                # NOTE: this codegen's ternary always evaluates BOTH branches (no
                # real short-circuiting), so `expr.name if isinstance(expr, IdentExpr)
                # else None` would call `.name` unconditionally even when expr isn't
                # an IdentExpr — falling to the dynamic-getattr runtime path, which
                # aborts by design for an unresolvable static type. Use a real `if`
                # instead. Found via example_imports.mojo's module docstring.
                name = None
                if isinstance(expr, IdentExpr):
                    name = expr.name
                if name:
                    return VarDecl(name=name, type_ann=type_ann, value=None, line=line, col=col)
                return ExprStmt(expr, line=line, col=col)
        # Augmented assignment (`=`/chained-assignment/tuple-unpacking are
        # all handled uniformly above, before the COLON-annotation check).
        if self._peek().kind == "AUGASSIGN":
            op = self._advance().value
            val = self._parse_expr_or_yield()
            return AugAssignStmt(target=expr, op=op, value=val, line=line, col=col)
        self._skip_newlines()
        return ExprStmt(expr, line=line, col=col)

    def _parse_import(self):
        t = self._peek()
        self._expect("KW", "import")
        module, alias = self._parse_import_target()
        # `import a, b, c` — comma-separated module list
        extra = None
        while self._peek().kind == "COMMA":
            self._advance()
            if extra is None:
                extra = []
            extra.append(self._parse_import_target())
        return ImportStmt(module=module, alias=alias, extra=extra,
                          line=t.line, col=t.col)

    def _parse_import_target(self):
        # Handle relative imports: import .warp, import ..sibling
        module = ""
        while self._peek().kind == "DOT":
            self._advance()
            module += "."
        # Module names may collide with keywords (e.g. a module named `comptime`),
        # so accept NAME or KW via _ident().
        module += self._ident()
        while self._peek().kind == "DOT":
            self._advance()
            module += "." + self._ident()
        alias = None
        if self._is_kw("as"):
            self._advance(); alias = self._ident()
        return (module, alias)

    def _parse_from_import(self):
        t = self._peek()
        self._expect("KW", "from")
        # Handle relative imports: from . or from .. or from .module
        module = ""
        while self._peek().kind == "DOT":
            self._advance()
            module += "."
        # If not just dots, parse the module name. Accept a keyword-named
        # module (e.g. `from struct import pack` — `struct` lexes as KW), but
        # never swallow the `import` keyword itself as the module name.
        if self._peek().kind == "NAME" or (self._peek().kind == "KW" and not self._is_kw("import")):
            module += self._advance().value
            while self._peek().kind == "DOT":
                self._advance()
                module += "." + self._ident()
        elif not module:
            # No dots and no name: error
            self._expect("NAME")  # Will raise error
        self._expect("KW", "import")
        if self._peek().kind == "OP" and self._peek().value == "*":
            self._advance()
            return FromImportStmt(module=module, names=[], wildcard=True, line=t.line, col=t.col)
        # Handle parenthesized multi-line imports: from x import (a, b, c)
        paren_import = False
        if self._peek().kind == "LPAREN":
            self._advance()
            paren_import = True
        names = []
        _nas = []
        # Parse first name, skipping any leading newlines in parenthesized imports
        if paren_import:
            while self._peek().kind == "NEWLINE": self._advance()
        if self._peek().kind == "RPAREN":
            # Empty parens: from x import ()
            self._advance()
            return FromImportStmt(module=module, names=names, wildcard=False, line=t.line, col=t.col)
        # `_ident()` (not `_expect("NAME")`): an imported name may collide with
        # a Mojo keyword, e.g. `from weakref import ref` — `ref` lexes as KW.
        name = self._ident()
        alias = None
        if self._is_kw("as"):
            self._advance(); alias = self._ident()
        names.append((name, alias))
        _nas.append((name + '|' + alias) if alias else name)
        # Parse remaining names
        while True:
            if paren_import:
                while self._peek().kind == "NEWLINE": self._advance()
            if self._peek().kind == "RPAREN":
                self._advance()
                break
            if self._peek().kind != "COMMA":
                break
            self._advance()
            if paren_import:
                while self._peek().kind == "NEWLINE": self._advance()
            if self._peek().kind == "RPAREN":
                self._advance()
                break
            name = self._ident()  # keyword-named imports (e.g. `ref`) allowed
            alias = None
            if self._is_kw("as"):
                self._advance(); alias = self._ident()
            names.append((name, alias))
            _nas.append((name + '|' + alias) if alias else name)
        return FromImportStmt(module=module, names=names, wildcard=False,
                              name_alias_strs=_nas, line=t.line, col=t.col)

    def _parse_var_decl(self):
        self._expect("KW", 'var')
        # Allow KW, backtick identifiers as variable names (e.g., "out", "fn", `6bit`)
        t = self._peek()
        if t.kind == "NAME": name = self._advance().value
        elif t.kind == "KW": name = self._advance().value
        elif t.kind == "STRING" and t.value.startswith("`"): name = self._advance().value
        elif t.kind == "COLON":
            # Python-style field annotation: "var: type"  (var is the field name)
            name = "var"
        else: raise SyntaxError(f"{self._loc(t)}Expected NAME or KW got {t.kind}({t.value!r})")
        # Check for tuple unpacking (var a, b, c = ...)
        if self._peek().kind == "COMMA":
            names = [name]
            while self._peek().kind == "COMMA":
                self._advance()
                t = self._peek()
                if t.kind == "NAME": names.append(self._advance().value)
                elif t.kind == "KW": names.append(self._advance().value)
                elif self._peek().kind == "ASSIGN": break
                else: break
            # Tuple unpacking: create as single VarDecl with tuple name
            if self._peek().kind == "ASSIGN":
                self._advance()
                value = self._parse_expr(0)
                # Handle tuple RHS: var a, b = x, y
                if self._peek().kind == "COMMA":
                    rhs = [value]
                    while self._peek().kind == "COMMA":
                        self._advance()
                        if self._peek().kind == "NEWLINE": break
                        rhs.append(self._parse_expr(0))
                    value = TupleExpr(elements=rhs)
                return VarDecl(name=",".join(names), type_ann=None, value=value)
            else:
                # No assignment, treat as error or incomplete
                return VarDecl(name=",".join(names), type_ann=None, value=None)
        type_ann = None
        if self._peek().kind == "COLON":
            self._advance()
            type_ann = self._parse_type_ann()
        value = None
        if self._peek().kind == "ASSIGN":
            self._advance(); value = self._parse_expr(0)
            # Implicit (parenthesis-less) tuple RHS: `var name = 'a', 'b', 'c'`
            # — a bare comma-separated list on the right of `=` is a tuple.
            # Mirrors the plain-assignment handling in the AssignStmt path above.
            if self._peek().kind == "COMMA":
                rhs_elements = [value]
                while self._peek().kind == "COMMA":
                    self._advance()
                    if self._peek().kind in ("NEWLINE", "DEDENT", "EOF"):
                        break
                    rhs_elements.append(self._parse_expr(0))
                value = TupleExpr(elements=rhs_elements)
        return VarDecl(name=name, type_ann=type_ann, value=value)

    def _parse_if(self):
        self._expect("KW", "if")
        cond = self._parse_expr(0)
        self._expect("COLON")
        body = self._parse_block()
        elifs, else_body = [], None
        self._skip_newlines()
        while self._is_kw("elif"):
            self._advance(); ec = self._parse_expr(0)
            self._expect("COLON"); eb = self._parse_block()
            elifs.append((ec, eb))
            self._skip_newlines()
        if self._is_kw("else"):
            self._advance(); self._expect("COLON")
            else_body = self._parse_block()
        return IfStmt(condition=cond, then_body=body, elifs=elifs, else_body=else_body)

    def _parse_while(self):
        self._expect("KW", "while")
        cond = self._parse_expr(0)
        self._expect("COLON")
        body = self._parse_block()
        else_body = None
        self._skip_newlines()
        if self._is_kw("else"):
            self._advance(); self._expect("COLON")
            else_body = self._parse_block()
        return WhileStmt(condition=cond, body=body, else_body=else_body)

    def _is_match_stmt(self):
        """Lookahead for the `match`/`__match` soft keyword: it's a match
        statement only if, after the subject expression, the next token before any
        NEWLINE is a top-level `:` — a real expression can never contain a
        bare top-level colon (dict/slice colons are always inside braces/
        brackets, which this tracks via depth). Doesn't consume anything;
        always restores position."""
        saved = self._pos
        self._advance()  # consume 'match'
        depth = 0
        is_match = False
        while True:
            t = self._peek()
            if t.kind in ("NEWLINE", "EOF"):
                break
            if t.kind in ("LPAREN", "LBRACKET", "LBRACE"):
                depth += 1
            elif t.kind in ("RPAREN", "RBRACKET", "RBRACE"):
                depth -= 1
            elif t.kind == "COLON" and depth == 0:
                is_match = True
                break
            self._advance()
        self._pos = saved
        return is_match

    def _parse_match(self):
        """Parse a `match`/`__match` statement (the keyword is current).

        Two case-block layouts, because the two spellings disagree:

          match x:              __match x:
          case .A:              case .A:
              body                  body

        Real Python (and every `match` in this tree's own tests) indents the
        cases one level past the `match`; Mojo's `__match` puts them at the SAME
        indentation as the keyword, with only the case BODIES indented. Both are
        accepted, and the two are told apart by whether an INDENT follows the
        header's newline rather than by the keyword, so `match x:` with
        same-level cases parses too rather than needing a second keyword test.

        The case list terminates on the enclosing block either way: a DEDENT/EOF
        for the indented layout, and for the flat layout the first token that is
        not a `case` at the first case's column — which is what stops the flat
        form from swallowing the statements that follow the match inside the same
        enclosing block.
        """
        self._advance()  # consume 'match'/'__match' (a NAME token, soft keyword)
        subject = self._parse_expr(0)
        self._expect("COLON")
        self._expect("NEWLINE")
        self._skip_newlines()
        indented = self._peek().kind == "INDENT"
        if indented:
            self._advance()
        cases = []
        self._skip_newlines()
        case_col = None
        while True:
            t = self._peek()
            if t.kind in ("DEDENT", "EOF"):
                break
            if not (t.kind == "NAME" and t.value == "case"):
                break
            if case_col is None:
                case_col = t.col
            elif t.col != case_col:
                break        # a `case` belonging to an OUTER match
            cases.append(self._parse_match_case())
            self._skip_newlines()
        if indented:
            self._expect("DEDENT")
        return MatchStmt(subject=subject, cases=cases)

    def _parse_match_case(self):
        # 'case' is also a soft keyword (NAME, not KW) — same as real Python.
        t = self._peek()
        if not (t.kind == "NAME" and t.value == "case"):
            raise SyntaxError(f"{self._loc(t)}Expected 'case' got {t.kind}({t.value!r})")
        self._advance()
        # `case _:` (bare wildcard, an IdentExpr named '_') is recognized at
        # match time (interpreter/codegen), not specially here — parsing it
        # as a plain expression pattern keeps this parser simple, and lets
        # `_` combine with an or-pattern list the same as any other pattern.
        # Patterns are parsed at min_prec=1 (the same trick comprehension
        # `for`/`if` clauses use below) so a top-level `if` here is left
        # untouched for the guard-clause check below instead of being
        # swallowed by _parse_expr's ternary-conditional-expression handling
        # (`X if COND else Y`), which only fires at min_prec==0. Without
        # this, `case n if n > 0:` fails trying to parse `if n > 0:` as a
        # ternary expecting a matching `else`.
        patterns = [self._parse_expr(1)]
        while self._peek().kind == "COMMA":
            self._advance()
            if self._peek().kind == "COLON" or self._is_kw("if"):
                break  # trailing comma before guard/colon
            patterns.append(self._parse_expr(1))
        guard = None
        if self._is_kw("if"):
            self._advance()
            guard = self._parse_expr(0)
        self._expect("COLON")
        body = self._parse_block()
        return MatchCase(patterns=patterns, body=body, guard=guard)

    def _parse_for(self):
        _for_tok = self._peek()
        self._expect("KW", "for")
        # Skip optional convention keyword (var, ref, mut, etc.) — but only
        # when it's genuinely a prefix, i.e. something that can start a
        # target follows it (another name, or `(` for tuple unpacking).
        # `var` is BOTH a convention keyword (`for var x in y:`, never
        # actually used anywhere in this codebase — grepped) AND a
        # perfectly ordinary Python identifier for the loop variable
        # itself (`for var in (...):`, real code in imports.py). Without
        # the peek(1) check, `for var in (...):` swallowed `var` as a
        # bogus convention prefix, then swallowed `in` too (mistaking it
        # for the loop-variable name), leaving the parser expecting `in`
        # but finding the tuple's `(` instead — "Expected KW got LPAREN".
        # `peek(1) != COMMA` guards the same collision for a plain
        # tuple-unpack target starting with the identifier `var`/etc.,
        # e.g. `for var, other_var in pairs:`
        # (PARSE_FAIL_var_as_for_loop_target_comma) — without it,
        # `var` was swallowed as a bogus prefix (peek(1)=COMMA matched
        # neither existing exclusion), leaving `_parse_unpack_target()` to
        # start from the comma itself and misparse everything after.
        if (self._peek().kind == "KW" and self._peek().value in self._CONV_KWS
                and not (self._peek(1).kind == "KW" and self._peek(1).value == "in")
                and self._peek(1).kind != "COLON"
                and self._peek(1).kind != "COMMA"):
            self._advance()

        # Handle tuple unpacking: for (a, b) in ..., for a, b in ..., or
        # for a, *rest in ... (single starred element anywhere in the list).
        # _parse_unpack_target is the shared unpacking-target-element parser
        # (also used by `with ... as (a, b):`) — see its docstring.
        target = self._parse_unpack_target()
        if self._peek().kind == "COMMA":
            names = [target]
            trailing_comma = False
            while self._peek().kind == "COMMA":
                self._advance()
                # A TRAILING comma makes the target a 1-tuple, and the `in`
                # that follows is what says so — `for patterns, in
                # _resolve_file_values(f, xs.items()):` (real: c_parser/
                # preprocessor/__init__.py:169) is Python-legal and means
                # "unpack each item's single element", which is NOT the same
                # as the bare-name target this loop would otherwise produce:
                # `_parse_unpack_target()` has no way to know a comma is
                # trailing rather than a separator, so it happily consumed
                # the `in` as a second target name and the parse then died
                # with "Expected KW got NAME('<iterable>')". Closing the
                # target here preserves the 1-tuple meaning — and preserves
                # the COMMA with it, because `for a, in b:` is the same target
                # as `for (a,) in b:` and must get the same `"(a,)"` spelling
                # (see the `_parse_unpack_target` note above and
                # `for_target_is_tuple`). Silently dropping the comma instead
                # would bind the whole item to the name: a wrong answer with
                # no error at all.
                if self._is_kw("in"):
                    trailing_comma = True
                    break
                names.append(self._parse_unpack_target())
            if trailing_comma and len(names) == 1:
                target = "(" + names[0] + ",)"
            else:
                target = "(" + ", ".join(names) + ")"
        self._expect("KW", "in")
        iterable = self._parse_expr(0)
        # Implicit (parenthesis-less) tuple iterable: `for x in a, b, c:`
        if self._peek().kind == "COMMA":
            elems = [iterable]
            while self._peek().kind == "COMMA":
                self._advance()
                if self._peek().kind == "COLON": break
                elems.append(self._parse_expr(0))
            iterable = TupleExpr(elements=elems)
        self._expect("COLON")
        body = self._parse_block()
        else_body = None
        if self._is_kw("else"):
            self._advance(); self._expect("COLON")
            else_body = self._parse_block()
        return ForStmt(target=target, iterable=iterable, body=body, else_body=else_body,
                       line=_for_tok.line, col=_for_tok.col)

    # Ownership/convention keywords preserved in param_convs
    _CONV_KWS = {'ref', 'out', 'mut', 'var', 'deinit', 'read', 'inout', 'borrowed', 'owned', 'imm'}
    # Canonical spelling for each convention keyword — old-style Mojo syntax
    # (`inout`/`borrowed`) and new-style (`mut`/`read`) are semantically
    # identical, and a parameter-position `var` means the same thing as
    # `owned` (the callee receives the value outright). Storing the
    # canonical form in param_convs means every later consumer (the
    # ownership_check.py move/borrow analysis, eventually codegen) checks
    # one spelling instead of tracking both historical names everywhere —
    # see doc/OWNERSHIP_MODEL.md's Phase 0. `ref`/`out`/`deinit` have no
    # older synonym and pass through unchanged.
    #
    # `imm` is the stdlib's immutable-borrow convention and has no older
    # synonym either, so it likewise passes through unchanged — but it is NOT
    # interchangeable with `ref`: it is what `read` means (a shared read-only
    # borrow), so `_param_ctype` treats the two alike when adding `const`. It
    # has to be a member of this set at all because a convention keyword is
    # consumed as a PREFIX here; left out, `def __eq__(imm self, imm other:
    # Self)` parsed as four parameters named `imm`, `self`, `imm`, `other` and
    # emitted `(int64_t imm, LinkedList * self, int64_t imm, LinkedList *
    # other)` — a C redefinition of `imm`, a hard error.


def emit_module(stmts: list, indent: int = 0) -> str:
    return "\n".join(emit(s, indent) for s in stmts)

def emit(node, indent: int = 0) -> str:
    pad = "    " * indent
    if isinstance(node,IntLiteral): return str(node.value)
    if isinstance(node,FloatLiteral): return repr(node.value)
    if isinstance(node,ImagLiteral): return repr(node.value) + "j"
    if isinstance(node,BoolLiteral): return str(node.value)
    if isinstance(node,StringLiteral): return node.value
    if isinstance(node,EllipsisLiteral): return "..."
    if isinstance(node,IdentExpr): return node.name
    if isinstance(node,CallExpr):
        f = emit(node.func, 0) if not isinstance(node.func,str) else node.func
        args = ", ".join(emit(a, 0) for a in node.args)
        return f"{f}({args})"
    if isinstance(node,BinaryOp): return f"({emit(node.left, 0)} {node.op} {emit(node.right, 0)})"
    if isinstance(node,CompareChain):
        parts = [emit(node.operands[0], 0)]
        for op, operand in zip(node.ops, node.operands[1:]):
            parts.append(f"{op} {emit(operand, 0)}")
        return "(" + " ".join(parts) + ")"
    if isinstance(node,UnaryOp):  return f"({node.op} {emit(node.operand, 0)})"
    if isinstance(node,TernaryExpr): return f"({emit(node.then_val, 0)} if {emit(node.condition, 0)} else {emit(node.else_val, 0)})"
    if isinstance(node,WalrusExpr): return f"({node.name} := {emit(node.value, 0)})"
    if isinstance(node,MemberExpr): return f"{emit(node.obj, 0)}.{node.member}"
    if isinstance(node,SubscriptExpr):
        # A tuple index is multi-dimensional indexing (a[i, j], a[0:2, ::]); emit
        # the elements comma-joined without the tuple's surrounding parentheses.
        if isinstance(node.index, TupleExpr):
            inner = ", ".join(emit(e, 0) for e in node.index.elements)
            return f"{emit(node.obj, 0)}[{inner}]"
        return f"{emit(node.obj, 0)}[{emit(node.index, 0)}]"
    if isinstance(node,SliceExpr):
        start = emit(node.start, 0) if node.start is not None else ""
        stop  = emit(node.stop, 0)  if node.stop  is not None else ""
        step  = getattr(node, "step", None)
        body  = f"{start}:{stop}:{emit(step, 0)}" if step is not None else f"{start}:{stop}"
        # A bare slice (obj=None) is one element of a multi-dim index; emit just
        # the slice. Otherwise emit the indexing expression obj[...].
        if node.obj is None:
            return body
        return f"{emit(node.obj, 0)}[{body}]"
    if isinstance(node,ListExpr): return "[" + ", ".join(emit(e, 0) for e in node.elements) + "]"
    if isinstance(node,DictExpr):
        # A `**expr` unpack spread pair is stored as (UnaryOp(op='**', ...),
        # None) — see `_parse_dict_or_set`/`_parse_dict_entry` — so it emits
        # as just the spread itself, not a bogus "(** x): None" pair.
        def _emit_pair(k, v):
            if v is None and isinstance(k, UnaryOp) and k.op == "**":
                return emit(k, 0)
            return f"{emit(k, 0)}: {emit(v, 0)}"
        return "{" + ", ".join(_emit_pair(k, v) for k, v in node.pairs) + "}"
    if isinstance(node,SetExpr): return "{" + ", ".join(emit(e, 0) for e in node.elements) + "}"
    if isinstance(node,TupleExpr):
        if not node.elements: return "()"
        return "(" + ", ".join(emit(e, 0) for e in node.elements) + ("," if len(node.elements)==1 else "") + ")"
    if isinstance(node,LambdaExpr):
        pstr = ", ".join(p[0] + (f"={emit(p[1])}" if p[1] is not None else "") for p in node.params)
        return f"lambda {pstr}: {emit(node.body)}"
    if isinstance(node,Comprehension):
        gens = " ".join(f"for {g.target} in {emit(g.iterable)}" + "".join(f" if {emit(c)}" for c in g.conditions) for g in node.generators)
        if node.kind == "list": return f"[{emit(node.element)} {gens}]"
        if node.kind == "set":  return "{" + f"{emit(node.element)} {gens}" + "}"
        if node.kind == "dict": return "{" + f"{emit(node.element)}: {emit(node.key)} {gens}" + "}"
        return f"({emit(node.element)} {gens})"
    if isinstance(node,ExprStmt): return f"{pad}{emit(node.value, 0)}"
    if isinstance(node,AssignStmt): return f"{pad}{emit(node.target)} = {emit(node.value, 0)}"
    if isinstance(node,AugAssignStmt): return f"{pad}{emit(node.target)} {node.op} {emit(node.value, 0)}"
    if isinstance(node,VarDecl):
        ann = f": {node.type_ann}" if node.type_ann else ""
        val = f" = {emit(node.value, 0)}" if node.value is not None else ""
        return f"{pad}{node.name}{ann}{val}"
    if isinstance(node,MultiAssignStmt):
        return f"{pad}" + " = ".join(emit(t) for t in node.targets) + " = " + emit(node.value, 0)
    if isinstance(node,ImportStmt):
        def _seg(m, a):
            return m + (f" as {a}" if a else "")
        parts = [_seg(node.module, node.alias)]
        for m, a in (node.extra or []):
            parts.append(_seg(m, a))
        return f"{pad}import " + ", ".join(parts)
    if isinstance(node,FromImportStmt):
        if node.wildcard: return f"{pad}from {node.module} import *"
        names = ", ".join(n + (f" as {a}" if a else "") for n,a in node.names)
        return f"{pad}from {node.module} import {names}"
    if isinstance(node,IfStmt):
        out = [f"{pad}if {emit(node.condition, 0)}:"]
        out += [emit(s,indent+1) for s in node.then_body]
        for (ec,eb) in node.elifs:
            out.append(f"{pad}elif {emit(ec)}:"); out += [emit(s,indent+1) for s in eb]
        if node.else_body is not None:
            out.append(f"{pad}else:"); out += [emit(s,indent+1) for s in node.else_body]
        return "\n".join(out)
    if isinstance(node,WhileStmt):
        out = [f"{pad}while {emit(node.condition, 0)}:"]
        out += [emit(s,indent+1) for s in node.body]
        if node.else_body is not None:
            out.append(f"{pad}else:"); out += [emit(s,indent+1) for s in node.else_body]
        return "\n".join(out)
    if isinstance(node,ForStmt):
        out = [f"{pad}for {emit(node.target) if not isinstance(node.target,str) else node.target} in {emit(node.iterable)}:"]
        out += [emit(s,indent+1) for s in node.body]
        if node.else_body is not None:
            out.append(f"{pad}else:"); out += [emit(s,indent+1) for s in node.else_body]
        return "\n".join(out)
    if isinstance(node,FunctionDef):
        def _fmt_param(n,t):
            ann = f": {t}" if t else ""
            return f"{n}{ann}"  # strip Mojo arg-convention prefix for Python
        params = ", ".join(_fmt_param(n,t) for n,t in node.params)
        ret = f" -> {node.return_type}" if node.return_type else ""
        out = [f"{pad}@{d}" for d in node.decorators]
        out.append(f"{pad}def {node.name}({params}){ret}:")
        out += [emit(s,indent+1) for s in node.body]
        return "\n".join(out)
    if isinstance(node,PassStmt): return f"{pad}pass"
    if isinstance(node,ReturnStmt):
        val = f" {emit(node.value, 0)}" if node.value is not None else ""
        return f"{pad}return{val}"
    if isinstance(node,RaiseStmt):
        val = f" {emit(node.value, 0)}" if node.value is not None else ""
        return f"{pad}raise{val}"
    if isinstance(node,BreakStmt): return f"{pad}break"
    if isinstance(node,ContinueStmt): return f"{pad}continue"
    if isinstance(node,AssertStmt):
        val = f" {emit(node.value, 0)}" if node.value is not None else ""
        msg_s = f", {emit(node.msg)}" if node.msg is not None else ""
        return f"{pad}assert{val}{msg_s}"
    if isinstance(node,TryStmt):
        out = [f"{pad}try:"]
        out += [emit(s,indent+1) for s in node.body]
        for h in node.handlers:
            if isinstance(h.exc_type, list):
                exc = " (" + ", ".join(h.exc_type) + ")"
            elif h.exc_type:
                exc = f" {h.exc_type}"
            else:
                exc = ""
            name = f" as {h.name}"  if h.name    else ""
            out.append(f"{pad}except{exc}{name}:")
            out += [emit(s,indent+1) for s in h.body]
        if node.else_body:
            out.append(f"{pad}else:"); out += [emit(s,indent+1) for s in node.else_body]
        if node.finally_body:
            out.append(f"{pad}finally:"); out += [emit(s,indent+1) for s in node.finally_body]
        return "\n".join(out)
    if isinstance(node,WithStmt):
        items_str = ", ".join(f"{emit(i.expr)} as {i.alias}" if i.alias else emit(i.expr) for i in node.items)
        out = [f"{pad}with {items_str}:"]
        out += [emit(s,indent+1) for s in node.body]
        return "\n".join(out)
    if isinstance(node,ComptimeIfStmt):
        out = [f"{pad}if {emit(node.condition, 0)}:  # comptime"]
        out += [emit(s,indent+1) for s in node.then_body]
        for (ec,eb) in node.elifs:
            out.append(f"{pad}elif {emit(ec)}:"); out += [emit(s,indent+1) for s in eb]
        if node.else_body is not None:
            out.append(f"{pad}else:"); out += [emit(s,indent+1) for s in node.else_body]
        return "\n".join(out)
    if isinstance(node,ComptimeForStmt):
        out = [f"{pad}for {node.target} in {emit(node.iterable)}:  # comptime"]
        out += [emit(s,indent+1) for s in node.body]
        return "\n".join(out)
    if isinstance(node,StructDef):
        _OWN_DECS = {"Copyable","Movable","ImplicitlyCopyable","ExplicitlyCopyable",
                     "Writable","Sized","Boolable","Stringable","Hashable","AnyType"}
        has_init = any(d == "fieldwise_init" for d in node.decorators)
        ext_decs = [d for d in node.decorators if d not in _OWN_DECS and d != "fieldwise_init"]
        out = [f"{pad}@{d}" for d in ext_decs]
        out.append(f"{pad}class {node.name}:")
        body = []
        if has_init and node.fields:
            ps = ", ".join(f.name for f in node.fields if isinstance(f, VarDecl))
            body.append(f"{pad}    def __init__(self, {ps}):")
            for f in node.fields:
                if isinstance(f, VarDecl):
                    body.append(f"{pad}        self.{f.name} = {f.name}")
                else:
                    body.append(f"{pad}        self.{emit(f.target)} = {emit(f.target)}")
        elif node.fields:
            for f in node.fields:
                if isinstance(f, VarDecl):
                    ann = f": {f.type_ann}" if f.type_ann else ""
                    val = f" = {emit(f.value)}" if f.value is not None else " = None"
                    body.append(f"{pad}    {f.name}{ann}{val}")
                else:
                    val = f" = {emit(f.value)}" if f.value is not None else " = None"
                    body.append(f"{pad}    {emit(f.target)}{val}")
        for m in node.methods:
            body.append(emit(m,indent+1))
        out += body if body else [f"{pad}    pass"]
        return "\n".join(out)
    if isinstance(node,TraitDef):
        out = [f"{pad}class {node.name}:  # trait"]
        body = []
        for m in node.methods:
            is_abs = (not m.body or
                      (len(m.body)==1 and isinstance(m.body[0],PassStmt)) or
                      (len(m.body)==1 and isinstance(m.body[0],ExprStmt)
                       and isinstance(m.body[0].value,EllipsisLiteral)))
            if is_abs: body.append(f"{pad}    @abstractmethod")
            body.append(emit(m,indent+1))
        out += body if body else [f"{pad}    pass"]
        return "\n".join(out)
    # Transfer sigil ^ is stripped by the tokenizer (XFER ignored)
    raise TypeError(f"Cannot emit {type(node).__name__}")

# ── Driver ──────────────────────────────────────────────────────────
def compile(src: str, filename: str = "") -> str:
    tokens = py_tokenize(src)
    stmts  = Parser(tokens).with_filename(filename).parse_module()
    return emit_module(stmts)

def compile_with_interpreter(src: str, filename: str = "") -> str:
    # Compile Mojo source to GIMPLE C using gimple_codegen.
    # This is the interpreter-based compilation path used during bootstrap.
    from gimple_codegen import compile_to_gimple
    return compile_to_gimple(src, do_imports=False, filename=filename)

if __name__ == '__main__':
    import sys
    filename = sys.argv[1] if len(sys.argv) >= 2 else "<stdin>"
    src = sys.stdin.read() if len(sys.argv) < 2 else open(filename).read()
    try:
        print(compile(src, filename=filename))
    except SyntaxError as e:
        print(str(e), file=sys.stderr)
        sys.exit(1)
